INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8e7ea2-7550-4805-9629-fc905e815bc4', '贈崔九載華', '贈崔九載华', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["憐君一見一悲歌，歲歲無如老去何。","白屋漸看秋草沒，青雲莫道故人多。"]', '["怜君一见一悲歌，歲歲無如老去何。","白屋漸看秋草沒，青云莫道故人多。"]', '诗', 'shi', '', NULL, '贈崔九載華 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51188758-7ff5-4252-adc3-ef87fb6cbdca', '同崔載華贈日本聘使', '同崔載华贈日本聘使', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["憐君異域朝周遠，積水連天何處通。","遙指來從初日外，始知更有扶桑東。"]', '["怜君異域朝周远，積水連天何处通。","遙指来從初日外，始知更有扶桑东。"]', '诗', 'shi', '', NULL, '同崔載華贈日本聘使 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147e279d-ec0b-44c6-9a43-c93f3fe1dc63', '送建州陸使君', '送建州陸使君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["漢庭初拜建安侯，天子臨軒寄所憂。","從此向南無限路，雙旌已去水悠悠。"]', '["漢庭初拜建安侯，天子臨軒寄所憂。","從此向南無限路，雙旌已去水悠悠。"]', '诗', 'shi', '', NULL, '送建州陸使君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec89983-bf8a-4474-9b19-e00ea24e0de7', '送秦侍御外甥張篆之福州謁鮑大夫秦侍御與大夫有舊', '送秦侍御外甥張篆之福州謁鲍大夫秦侍御與大夫有旧', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬里閩中去渺然，孤舟水上入寒煙。","轅門拜首儒衣弊，貌似牢之豈不憐。"]', '["万里閩中去渺然，孤舟水上入寒煙。","轅门拜首儒衣弊，貌似牢之豈不怜。"]', '诗', 'shi', '', NULL, '送秦侍御外甥張篆之福州謁鮑大夫秦侍御與大夫有舊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23011bdb-2593-4ae8-a04e-69b1b1ce833e', '聞奉迎皇太后使沈判官至因有此作', '闻奉迎皇太后使沈判官至因有此作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長樂宮人掃落花，君王正候五雲車。","萬方臣妾同瞻望，疑在曾城阿母家。"]', '["长乐宮人掃落花，君王正候五云车。","万方臣妾同瞻望，疑在曾城阿母家。"]', '诗', 'shi', '', NULL, '聞奉迎皇太后使沈判官至因有此作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be507a52-15f0-43be-96d8-f58a94e54c64', '送劉萱之道州謁崔大夫', '送劉萱之道州謁崔大夫', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["沅水悠悠湘水春，臨岐南望一沾巾。","信陵門下三千客，君到長沙見幾人。"]', '["沅水悠悠湘水春，臨岐南望一沾巾。","信陵门下三千客，君到长沙见幾人。"]', '诗', 'shi', '', NULL, '送劉萱之道州謁崔大夫 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db76ca9e-6e19-409a-b66a-0fc2e277c060', '過鄭山人所居', '過鄭山人所居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["寂寂孤鶯啼杏園，寥寥一犬吠桃源。","落花芳草無尋處，萬壑千峰獨閉門。"]', '["寂寂孤鶯啼杏园，寥寥一犬吠桃源。","落花芳草無尋处，万壑千峰独閉门。"]', '诗', 'shi', '', NULL, '過鄭山人所居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d618f36-2127-411c-8978-9884a92f56d8', '奉送賀若郎中賊退後之杭州', '奉送賀若郎中賊退後之杭州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江上初收戰馬塵，鶯聲柳色待行春。","雙旌誰道來何暮，萬井如今有幾人。"]', '["江上初收戰马塵，鶯声柳色待行春。","雙旌誰道来何暮，万井如今有幾人。"]', '诗', 'shi', '', NULL, '奉送賀若郎中賊退後之杭州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b87684b6-8286-4391-be4b-3578d86e370c', '瓜洲驛重送梁郎中赴吉州', '瓜洲驛重送梁郎中赴吉州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["渺渺雲山去幾重，依依獨聽廣陵鐘。","明朝借問南來客，五馬雙旌何處逢。"]', '["渺渺云山去幾重，依依独听廣陵鐘。","明朝借问南来客，五马雙旌何处逢。"]', '诗', 'shi', '', NULL, '瓜洲驛重送梁郎中赴吉州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a28e97-a4ad-4956-bebf-4950f46da6f8', '奉使鄂渚至烏江道中作', '奉使鄂渚至烏江道中作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["滄洲不復戀魚竿，白髮那堪戴鐵冠。","客路向南何處是，蘆花千里雪漫漫。"]', '["滄洲不复戀鱼竿，白髮那堪戴鐵冠。","客路向南何处是，蘆花千里雪漫漫。"]', '诗', 'shi', '', NULL, '奉使鄂渚至烏江道中作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f3b863-0617-4347-bce9-467baacd9423', '新息道中作', '新息道中作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蕭條獨向汝南行，客路多逢漢騎營。","古木蒼蒼離亂後，幾家同住一孤城。"]', '["蕭條独向汝南行，客路多逢漢騎營。","古木蒼蒼離亂後，幾家同住一孤城。"]', '诗', 'shi', '', NULL, '新息道中作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bba59d0-7837-4edd-9651-efabe2d9753f', '春日宴魏萬成湘水亭', '春日宴魏万成湘水亭', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何年家住此江濱，幾度門前北渚春。","白髮亂生相顧老，黃鶯自語豈知人。"]', '["何年家住此江濱，幾度门前北渚春。","白髮亂生相顧老，黄鶯自語豈知人。"]', '诗', 'shi', '', NULL, '春日宴魏萬成湘水亭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c32fc96-9419-4178-9fbf-e5e2809a2c28', '重送道標上人', '重送道標上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["衡陽千里去人稀，遙逐孤雲入翠微。","春草青青新覆地，深山無路若爲歸。"]', '["衡陽千里去人稀，遙逐孤云入翠微。","春草青青新覆地，深山無路若爲归。"]', '诗', 'shi', '', NULL, '重送道標上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a52b5e-062d-4d77-870a-83b3f75b4c3a', '送李判官之潤州行營', '送李判官之潤州行營', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["萬里辭家事鼓鼙，今陵驛路楚雲西。","江春不肯留歸客，草色青青送馬蹄。"]', '["万里辞家事鼓鼙，今陵驛路楚云西。","江春不肯留归客，草色青青送马蹄。"]', '诗', 'shi', '', NULL, '送李判官之潤州行營 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eefce47d-74f9-4c94-9ec0-65a80d897d6a', '將赴南巴至餘干別李十二', '將赴南巴至餘干別李十二', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江上花催問禮人，鄱陽鶯報越鄉春。","誰憐此別悲歡異，萬里青山送逐臣。"]', '["江上花催问禮人，鄱陽鶯報越乡春。","誰怜此別悲歡異，万里青山送逐臣。"]', '诗', 'shi', '', NULL, '將赴南巴至餘干別李十二 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4f7562-3dfe-4b93-a8f8-14fca44a5960', '時平後春日思歸', '时平後春日思归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["一尉何曾及布衣，時平却憶臥柴扉。","故園柳色催南客，春水桃花待北歸。"]', '["一尉何曾及布衣，时平却憶臥柴扉。","故园柳色催南客，春水桃花待北归。"]', '诗', 'shi', '', NULL, '時平後春日思歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15f0418-0911-4134-b0b7-01bd28ec5623', '送陶十赴杭州攝掾', '送陶十赴杭州攝掾', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["莫歎江城一掾卑，滄洲未是阻心期。","浙中山色千萬狀，門外潮聲朝暮時。"]', '["莫歎江城一掾卑，滄洲未是阻心期。","浙中山色千万狀，门外潮声朝暮时。"]', '诗', 'shi', '', NULL, '送陶十赴杭州攝掾 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01033ac8-52e9-4cd7-a8b2-1f55b4cc1364', '使還七里瀨上逢薛承規赴江西貶官', '使還七里瀨上逢薛承規赴江西貶官', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["遷客歸人醉晚寒，孤舟暫泊子陵灘。","憐君更去三千里，落日青山江上看。"]', '["遷客归人醉晚寒，孤舟暫泊子陵灘。","怜君更去三千里，落日青山江上看。"]', '诗', 'shi', '', NULL, '使還七里瀨上逢薛承規赴江西貶官 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71b92ee1-1476-4a2d-bdb9-b618120a07b2', '使回赴蘇州道中作', '使回赴蘇州道中作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["春風何事遠相催，路盡天涯始却回。","萬里無人空楚水，孤帆送客到魚臺。"]', '["春风何事远相催，路尽天涯始却回。","万里無人空楚水，孤帆送客到鱼台。"]', '诗', 'shi', '', NULL, '使回赴蘇州道中作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a231a2-3110-46db-8454-0521b1ac5925', '昭陽曲', '昭陽曲', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["昨夜承恩宿未央，羅衣猶帶御衣香。","芙蓉帳小雲屏暗，楊柳風多水殿涼。"]', '["昨夜承恩宿未央，羅衣猶带御衣香。","芙蓉帳小云屏暗，楊柳风多水殿涼。"]', '诗', 'shi', '', NULL, '昭陽曲 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c1fb37-4ae2-4a05-b355-31cfe9a6e9d2', '罪所留繫每夜聞長洲軍笛聲', '罪所留繫每夜闻长洲軍笛声', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["白日浮雲閉不開，黃沙誰問冶長猜。","只憐橫笛關山月，知處愁人夜夜來。"]', '["白日浮云閉不开，黄沙誰问冶长猜。","只怜橫笛关山月，知处愁人夜夜来。"]', '诗', 'shi', '', NULL, '罪所留繫每夜聞長洲軍笛聲 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b891a3e0-c4af-42b3-833e-9083c22b7eb7', '贈微上人', '贈微上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["禪門來往翠微間，萬里千峰在剡山。","何時共到天台裏，身與浮雲處處閑。"]', '["禪门来往翠微间，万里千峰在剡山。","何时共到天台裏，身與浮云处处闲。"]', '诗', 'shi', '', NULL, '贈微上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('638c9288-ef7f-4478-8731-0bf5ab7fdcd4', '東湖送朱逸人歸', '东湖送朱逸人归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山色湖光併在東，扁舟歸去有樵風。","莫道野人無外事，開田鑿井白雲中。"]', '["山色湖光併在东，扁舟归去有樵风。","莫道野人無外事，开田鑿井白云中。"]', '诗', 'shi', '', NULL, '東湖送朱逸人歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0046c0d4-5957-496f-bc0f-0ee705197f5a', '舟中送李十八', '舟中送李十八', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["釋子身心無有分，獨將衣鉢去人羣。","相思晚望西林寺，唯有鐘聲出白雲。"]', '["釋子身心無有分，独將衣鉢去人羣。","相思晚望西林寺，唯有鐘声出白云。"]', '诗', 'shi', '', NULL, '舟中送李十八 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291050c9-d586-4465-8423-530b784b44f0', '送李穆歸淮南', '送李穆归淮南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["揚州春草新年綠，未去先愁去不歸。","淮水問君來早晚，老人偏畏過芳菲。"]', '["揚州春草新年綠，未去先愁去不归。","淮水问君来早晚，老人偏畏過芳菲。"]', '诗', 'shi', '', NULL, '送李穆歸淮南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c604753a-df3f-4171-8d5a-19b8e3260aa3', '晚春歸山居題窗前竹', '晚春归山居題窗前竹', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["溪上殘春黃鳥稀，辛夷花盡杏花飛。","始憐幽竹山窗下，不改清陰待我歸。"]', '["溪上殘春黄鸟稀，辛夷花尽杏花飞。","始怜幽竹山窗下，不改清陰待我归。"]', '诗', 'shi', '', NULL, '晚春歸山居題窗前竹 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed35e220-5c75-4dc8-986f-af19200286fb', '送盧侍御赴河北', '送盧侍御赴河北', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["謫居爲別倍傷情，何事從戎獨遠行。","千里按圖收故地，三軍罷戰及春耕。","江天渺渺鴻初去，漳水悠悠草欲生。","莫學仲連逃海上，田單空愧取聊城。"]', '["謫居爲別倍傷情，何事從戎独远行。","千里按圖收故地，三軍罷戰及春耕。","江天渺渺鴻初去，漳水悠悠草欲生。","莫学仲連逃海上，田單空愧取聊城。"]', '诗', 'shi', '', NULL, '送盧侍御赴河北 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f524913b-4ec2-43ab-838e-068a8121ccd1', '送子壻崔真父歸長城', '送子壻崔真父归长城', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["送君巵酒不成歡，幼女辭家事伯鸞。","桃葉宜人誠可詠，柳花如雪若爲看。","心憐稚齒鳴環去，身愧衰顏對玉難。","惆悵暮帆何處落，青山無限水漫漫。"]', '["送君巵酒不成歡，幼女辞家事伯鸾。","桃葉宜人誠可詠，柳花如雪若爲看。","心怜稚齒鳴环去，身愧衰顏对玉难。","惆悵暮帆何处落，青山無限水漫漫。"]', '诗', 'shi', '', NULL, '送子壻崔真父歸長城 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94688bea-6d3f-4aec-9a91-4fccae99de86', '送陸[澧]倉曹西上', '送陸[澧]倉曹西上', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長安此去欲何依，先達誰當薦陸機。","日下鳳翔雙闕迥，雪中人去二陵稀。","舟從故里難移棹，家住寒塘獨掩扉。","臨水自傷流落久，贈君空有淚霑衣。"]', '["长安此去欲何依，先達誰當薦陸機。","日下鳳翔雙闕迥，雪中人去二陵稀。","舟從故里难移棹，家住寒塘独掩扉。","臨水自傷流落久，贈君空有泪霑衣。"]', '诗', 'shi', '', NULL, '送陸[澧]倉曹西上 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6177928c-10b5-4b13-8c66-d54a9695036f', '送柳使君赴袁州', '送柳使君赴袁州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["宜陽出守新恩至，京口因家始願違。","五柳閉門高士去，三苗按節遠人歸。","月明江路聞猨斷，花暗山城見吏稀。","惟有郡齋窗裏岫，朝朝空對謝玄暉。"]', '["宜陽出守新恩至，京口因家始願違。","五柳閉门高士去，三苗按節远人归。","月明江路闻猨斷，花暗山城见吏稀。","惟有郡斋窗裏岫，朝朝空对謝玄暉。"]', '诗', 'shi', '', NULL, '送柳使君赴袁州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb449a6-871b-4105-ba63-700ebe55e2d1', '戲題贈二小男', '戲題贈二小男', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["異鄉流落頻生子，幾許悲歡併在身。","欲並老容羞白髮，每看兒戲憶青春。","未知門戶誰堪主，且免琴書別與人。","何幸暮年方有後，舉家相對却霑巾。"]', '["異乡流落頻生子，幾許悲歡併在身。","欲並老容羞白髮，每看兒戲憶青春。","未知门戶誰堪主，且免琴书別與人。","何幸暮年方有後，舉家相对却霑巾。"]', '诗', 'shi', '', NULL, '戲題贈二小男 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d53fd44-4008-4822-ac67-79e9688142a5', '謫官後臥病官舍簡賀蘭侍郎', '謫官後臥病官舍簡賀蘭侍郎', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["青春衣繡共稱宜，白首垂絲恨不遺。","江上幾回今夜月，鏡中無復少年時。","生還北闕誰相引，老向南邦衆所悲。","歲歲任他芳草綠，長沙未有定歸期。"]', '["青春衣繡共稱宜，白首垂絲恨不遺。","江上幾回今夜月，镜中無复少年时。","生還北闕誰相引，老向南邦衆所悲。","歲歲任他芳草綠，长沙未有定归期。"]', '诗', 'shi', '', NULL, '謫官後臥病官舍簡賀蘭侍郎 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ea5d5d-5395-41ae-b662-f1f9a125ec98', '歲日見新曆因寄都官裴郎中', '歲日见新曆因寄都官裴郎中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["青陽振蟄初頒曆，白首銜冤欲問天。","絳老更能經幾歲，賈生何事又三年。","愁占蓍草終難決，病對椒花倍自憐。","若道平分四時氣，南枝爲底發春偏。"]', '["青陽振蟄初頒曆，白首銜冤欲问天。","絳老更能經幾歲，賈生何事又三年。","愁占蓍草終难決，病对椒花倍自怜。","若道平分四时氣，南枝爲底發春偏。"]', '诗', 'shi', '', NULL, '歲日見新曆因寄都官裴郎中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9dd3520-9aab-4b1b-bd57-810f29391667', '江州重別薛六柳八二員外', '江州重別薛六柳八二員外', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["生涯豈料承優詔，世事空知學醉歌。","江上月明胡鴈過，淮南木落楚山多。","寄身且喜滄洲近，顧影無如白髮何。","今日龍鍾人共棄，媿君猶遣慎風波。"]', '["生涯豈料承優詔，世事空知学醉歌。","江上月明胡鴈過，淮南木落楚山多。","寄身且喜滄洲近，顧影無如白髮何。","今日龙鍾人共棄，媿君猶遣慎风波。"]', '诗', 'shi', '', NULL, '江州重別薛六柳八二員外 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab26a26-680d-40cd-92a0-49a4a94cba73', '青溪口送人歸岳州', '青溪口送人归岳州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["洞庭何處鴈南飛，江菼蒼蒼客去稀。","帆帶夕陽千里沒，天連秋水一人歸。","黃花裛露開沙岸，白鳥銜魚上釣磯。","岐路相逢無可贈，老年空有淚霑衣。"]', '["洞庭何处鴈南飞，江菼蒼蒼客去稀。","帆带夕陽千里沒，天連秋水一人归。","黄花裛露开沙岸，白鸟銜鱼上釣磯。","岐路相逢無可贈，老年空有泪霑衣。"]', '诗', 'shi', '', NULL, '青溪口送人歸岳州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be42c69-302b-41b7-800d-0e5ce5084fb6', '送靈澈上人還越中', '送靈澈上人還越中', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["禪客無心杖錫還，沃洲深處草堂閑。","身隨敝屨經殘雪，手綻寒衣入舊山。","獨向青溪依樹下，空留白日在人間。","那堪別後長相憶，雲木蒼蒼但閉關。"]', '["禪客無心杖錫還，沃洲深处草堂闲。","身隨敝屨經殘雪，手綻寒衣入旧山。","独向青溪依樹下，空留白日在人间。","那堪別後长相憶，云木蒼蒼但閉关。"]', '诗', 'shi', '', NULL, '送靈澈上人還越中 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('271a4a04-81b6-45b2-a14b-3afac8ce973e', '送耿拾遺歸上都', '送耿拾遺归上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["若爲天畔獨歸秦，對水看山欲暮春。","窮海別離無限路，隔河征戰幾歸人。","長安萬里傳雙淚，建德千峰寄一身。","想到郵亭愁駐馬，不堪西望見風塵。"]', '["若爲天畔独归秦，对水看山欲暮春。","窮海別離無限路，隔河征戰幾归人。","长安万里傳雙泪，建德千峰寄一身。","想到郵亭愁駐马，不堪西望见风塵。"]', '诗', 'shi', '', NULL, '送耿拾遺歸上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091efd68-4464-4304-b626-1d115da86f63', '和樊使君登潤州城樓', '和樊使君登潤州城楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山城迢遰敞高樓，露冕吹鐃居上頭。","春草連天隨北望，夕陽浮水共東流。","江田漠漠全吳地，野樹蒼蒼故蔣州。","王粲尚爲南郡客，別來何處更銷憂。"]', '["山城迢遰敞高楼，露冕吹鐃居上头。","春草連天隨北望，夕陽浮水共东流。","江田漠漠全吳地，野樹蒼蒼故蔣州。","王粲尚爲南郡客，別来何处更銷憂。"]', '诗', 'shi', '', NULL, '和樊使君登潤州城樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('848a6a9f-9b2c-4b54-a98a-555f800745b4', '餞王相公出牧括州', '餞王相公出牧括州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["縉雲詎比長沙遠，出牧猶承明主恩。","城對寒山開畫戟，路飛秋葉轉朱轓。","江潮淼淼連天望，旌斾悠悠上嶺翻。","蕭索庭槐空閉閤，舊人誰到翟公門。"]', '["縉云詎比长沙远，出牧猶承明主恩。","城对寒山开畫戟，路飞秋葉轉朱轓。","江潮淼淼連天望，旌斾悠悠上嶺翻。","蕭索庭槐空閉閤，旧人誰到翟公门。"]', '诗', 'shi', '', NULL, '餞王相公出牧括州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe83fa6d-6e42-4a20-a262-2ef7afe28a17', '題靈祐和尚故居', '題靈祐和尚故居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["歎逝翻悲有此身，禪房寂寞見流塵。","多時行徑空秋草，幾日浮生哭故人。","風竹自吟遙入磬，雨花隨淚共霑巾。","殘經窗下依然在，憶得山中問許詢。"]', '["歎逝翻悲有此身，禪房寂寞见流塵。","多时行徑空秋草，幾日浮生哭故人。","风竹自吟遙入磬，雨花隨泪共霑巾。","殘經窗下依然在，憶得山中问許詢。"]', '诗', 'shi', '', NULL, '題靈祐和尚故居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db80963-60bb-4d4c-a0f1-0d20c3b30874', '尋龍井楊老', '尋龙井楊老', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["柴門草舍絕風塵，空谷耕田學子真。","泉咽恐勞經隴底，山深不覺有秦人。","手栽松樹蒼蒼老，身臥桃園寂寂春。","唯有胡麻當雞黍，白雲來往未嫌貧。"]', '["柴门草舍絕风塵，空谷耕田学子真。","泉咽恐勞經隴底，山深不覺有秦人。","手栽松樹蒼蒼老，身臥桃园寂寂春。","唯有胡麻當雞黍，白云来往未嫌貧。"]', '诗', 'shi', '', NULL, '尋龍井楊老 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('472a69cd-c17c-4780-b02f-6299a982c23c', '見故人李均所借古鏡恨其未獲歸府斯人已亡愴然有作', '见故人李均所借古镜恨其未獲归府斯人已亡愴然有作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人留鏡無歸處，今日懷君試暫窺。","歲久豈堪塵自入，夜長應待月相隨。","空憐瓊樹曾臨匣，猶見菱花獨映池。","所恨平生還不早，如今始挂隴頭枝。"]', '["故人留镜無归处，今日懷君試暫窺。","歲久豈堪塵自入，夜长應待月相隨。","空怜瓊樹曾臨匣，猶见菱花独映池。","所恨平生還不早，如今始挂隴头枝。"]', '诗', 'shi', '', NULL, '見故人李均所借古鏡恨其未獲歸府斯人已亡愴然有作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2160310-2cf5-46ac-832e-d7216c588d75', '聞虞沔州有替將歸上都登漢東城寄贈', '闻虞沔州有替將归上都登漢东城寄贈', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["淮南搖落客心悲，溳水悠悠怨別離。","早鴈初辭舊關塞，秋風先入古城池。","腰章建隼皇恩賜，露冕臨人白髮垂。","惆悵恨君先我去，漢陽耆老憶旌麾。"]', '["淮南搖落客心悲，溳水悠悠怨別離。","早鴈初辞旧关塞，秋风先入古城池。","腰章建隼皇恩賜，露冕臨人白髮垂。","惆悵恨君先我去，漢陽耆老憶旌麾。"]', '诗', 'shi', '', NULL, '聞虞沔州有替將歸上都登漢東城寄贈 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8414e0dd-1d05-4f0f-b38d-92d937fa7a2f', '獻淮寧軍節度使李相公', '獻淮寧軍節度使李相公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["建牙吹角不聞喧，三十登壇衆所尊。","家散萬金酬士死，身留一劍答君恩。","漁陽老將多迴席，魯國諸生半在門。","白馬翩翩春草細，郊原西去獵平原。"]', '["建牙吹角不闻喧，三十登壇衆所尊。","家散万金酬士死，身留一劍答君恩。","漁陽老將多迴席，魯国諸生半在门。","白马翩翩春草細，郊原西去獵平原。"]', '诗', 'shi', '', NULL, '獻淮寧軍節度使李相公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c5c24a-ea68-450d-8329-204042ff4f08', '觀校獵上淮西相公', '观校獵上淮西相公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["龍驤校獵邵陵東，野火初燒楚澤空。","師事黃公千戰後，身騎白馬萬人中。","笳隨晚吹吟邊草，箭沒寒雲落塞鴻。","三十擁旄誰不羨，周郎少小立奇功。"]', '["龙驤校獵邵陵东，野火初燒楚澤空。","師事黄公千戰後，身騎白马万人中。","笳隨晚吹吟邊草，箭沒寒云落塞鴻。","三十擁旄誰不羨，周郎少小立奇功。"]', '诗', 'shi', '', NULL, '觀校獵上淮西相公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b644fb-e623-47eb-b2b0-b97586564f63', '送皇甫曾赴上都', '送皇甫曾赴上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["東遊久與故人違，西去荒涼舊路微。","秋草不生三徑處，行人獨向五陵歸。","離心日遠如流水，迴首川長共落暉。","楚客豈勞傷此別，滄江欲暮自霑衣。"]', '["东游久與故人違，西去荒涼旧路微。","秋草不生三徑处，行人独向五陵归。","離心日远如流水，迴首川长共落暉。","楚客豈勞傷此別，滄江欲暮自霑衣。"]', '诗', 'shi', '', NULL, '送皇甫曾赴上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0539dbe-3448-4b90-a554-cd82d319ad5d', '送李錄事兄歸襄鄧', '送李錄事兄归襄鄧', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["十年多難與君同，幾處移家逐轉蓬。","白首相逢征戰後，青春已過亂離中。","行人杳杳看西月，歸馬蕭蕭向北風。","漢水楚雲千萬里，天涯此別恨無窮。"]', '["十年多难與君同，幾处移家逐轉蓬。","白首相逢征戰後，青春已過亂離中。","行人杳杳看西月，归马蕭蕭向北风。","漢水楚云千万里，天涯此別恨無窮。"]', '诗', 'shi', '', NULL, '送李錄事兄歸襄鄧 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b75e406-e8fa-453a-b749-52a205d807ba', '漢陽獻李相公', '漢陽獻李相公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["退身高臥楚城幽，獨掩閑門漢水頭。","春草雨中行徑沒，暮山江上捲簾愁。","幾人猶憶孫弘閣，百口同乘范蠡舟。","早晚却還丞相印，十年空被白雲留。"]', '["退身高臥楚城幽，独掩闲门漢水头。","春草雨中行徑沒，暮山江上捲簾愁。","幾人猶憶孫弘閣，百口同乘范蠡舟。","早晚却還丞相印，十年空被白云留。"]', '诗', 'shi', '', NULL, '漢陽獻李相公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cefa67f-2b9a-4e13-8158-4d38cbfb331b', '長沙過賈誼宅', '长沙過賈誼宅', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["三年謫宦此棲遲，萬古惟留楚客悲。","秋草獨尋人去後，寒林空見日斜時。","漢文有道恩猶薄，湘水無情弔豈知。","寂寂江山搖落處，憐君何事到天涯。"]', '["三年謫宦此棲遲，万古惟留楚客悲。","秋草独尋人去後，寒林空见日斜时。","漢文有道恩猶薄，湘水無情弔豈知。","寂寂江山搖落处，怜君何事到天涯。"]', '诗', 'shi', '', NULL, '長沙過賈誼宅 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2aafd5a-1f1a-4eca-9801-284443b8cac5', '奉酬辛大夫喜湖南臘月連日降雪見示之作', '奉酬辛大夫喜湖南臘月連日降雪见示之作', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長沙耆舊拜旌麾，喜見江潭積雪時。","柳絮三冬先北地，梅花一夜徧南枝。","初開窗閣寒光滿，欲掩軍城暮色遲。","閭里何人不相慶，萬家同唱郢中詞。"]', '["长沙耆旧拜旌麾，喜见江潭積雪时。","柳絮三冬先北地，梅花一夜徧南枝。","初开窗閣寒光满，欲掩軍城暮色遲。","閭里何人不相慶，万家同唱郢中词。"]', '诗', 'shi', '', NULL, '奉酬辛大夫喜湖南臘月連日降雪見示之作 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d08bde34-da46-4e92-ac67-961c18ca7d1b', '登餘干古縣城', '登餘干古縣城', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["孤城上與白雲齊，萬古荒涼楚水西。","官舍已空秋草綠，女牆猶在夜烏啼。","平江渺渺來人遠，落日亭亭向客低。","沙鳥不知陵谷變，朝飛暮去弋陽溪。"]', '["孤城上與白云齊，万古荒涼楚水西。","官舍已空秋草綠，女牆猶在夜烏啼。","平江渺渺来人远，落日亭亭向客低。","沙鸟不知陵谷变，朝飞暮去弋陽溪。"]', '诗', 'shi', '', NULL, '登餘干古縣城 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ca796c-9117-448a-9d19-669ac1e6f831', '將赴嶺外留題蕭寺遠公院', '將赴嶺外留題蕭寺远公院', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["竹房遙閉上方幽，苔徑蒼蒼訪昔遊。","內史舊山空日暮，南朝古木向人秋。","天香月色同僧室，葉落猨啼傍客舟。","此去播遷明主意，白雲何事欲相留。"]', '["竹房遙閉上方幽，苔徑蒼蒼訪昔游。","內史旧山空日暮，南朝古木向人秋。","天香月色同僧室，葉落猨啼傍客舟。","此去播遷明主意，白云何事欲相留。"]', '诗', 'shi', '', NULL, '將赴嶺外留題蕭寺遠公院 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1143da-ec70-486b-960a-13a50b8e73d4', '初聞貶謫續喜量移登干越亭贈鄭校書', '初闻貶謫續喜量移登干越亭贈鄭校书', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["青青草色滿江洲，萬里傷心水自流。","越鳥豈知南國遠，江花獨向北人愁。","生涯已逐滄浪去，冤氣初逢渙汗收。","何事還邀遷客醉，春風日夜待歸舟。"]', '["青青草色满江洲，万里傷心水自流。","越鸟豈知南国远，江花独向北人愁。","生涯已逐滄浪去，冤氣初逢渙汗收。","何事還邀遷客醉，春风日夜待归舟。"]', '诗', 'shi', '', NULL, '初聞貶謫續喜量移登干越亭贈鄭校書 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9dc37bc-ac68-4ca7-86d2-9f29bc565b2d', '北歸入至德州界偶逢洛陽鄰家李光宰', '北归入至德州界偶逢洛陽鄰家李光宰', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["生涯心事已蹉跎，舊路依然此重過。","近北始知黃葉落，向南空見白雲多。","炎州日日人將老，寒渚年年水自波。","華髮相逢俱若是，故園秋草復如何。"]', '["生涯心事已蹉跎，旧路依然此重過。","近北始知黄葉落，向南空见白云多。","炎州日日人將老，寒渚年年水自波。","华髮相逢俱若是，故园秋草复如何。"]', '诗', 'shi', '', NULL, '北歸入至德州界偶逢洛陽鄰家李光宰 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a87264-b316-4409-aaa5-903ace5479c8', '自江西歸至舊任官舍贈袁贊府', '自江西归至旧任官舍贈袁贊府', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["却見同官喜復悲，此生何幸有歸期。","空庭客至逢搖落，舊邑人稀經亂離。","湘路來過迴鴈處，江城臥聽擣衣時。","南方風土勞君問，賈誼長沙豈不知。"]', '["却见同官喜复悲，此生何幸有归期。","空庭客至逢搖落，旧邑人稀經亂離。","湘路来過迴鴈处，江城臥听擣衣时。","南方风土勞君问，賈誼长沙豈不知。"]', '诗', 'shi', '', NULL, '自江西歸至舊任官舍贈袁贊府 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd68fdf-913e-4f32-a7a6-2696bad60c3e', '赴南中題褚少府湖上亭子', '赴南中題褚少府湖上亭子', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["種田東郭傍春陂，萬事無情把釣絲。","綠竹放侵行徑裏，青山常對卷簾時。","紛紛花落門空閉，寂寂鶯啼日更遲。","從此別君千萬里，白雲流水憶佳期。"]', '["種田东郭傍春陂，万事無情把釣絲。","綠竹放侵行徑裏，青山常对卷簾时。","紛紛花落门空閉，寂寂鶯啼日更遲。","從此別君千万里，白云流水憶佳期。"]', '诗', 'shi', '', NULL, '赴南中題褚少府湖上亭子 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf69f48-d5e3-404f-8e89-4db538d009f7', '上巳日越中與鮑侍郎泛舟耶溪', '上巳日越中與鲍侍郎泛舟耶溪', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["蘭橈縵轉傍汀沙，應接雲峰到若耶。","舊浦滿來移渡口，垂楊深處有人家。","永和春色千年在，曲水鄉心萬里賒。","君見漁船時借問，前洲幾路入烟花。"]', '["蘭橈縵轉傍汀沙，應接云峰到若耶。","旧浦满来移渡口，垂楊深处有人家。","永和春色千年在，曲水乡心万里賒。","君见漁船时借问，前洲幾路入烟花。"]', '诗', 'shi', '', NULL, '上巳日越中與鮑侍郎泛舟耶溪 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af936ab6-911f-4133-bf56-8d8f79731971', '雙峰下哭故人李宥', '雙峰下哭故人李宥', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["憐君孤壠寄雙峰，埋骨窮泉復幾重。","白露空霑九原草，青山猶閉數株松。","圖書經亂知何在，妻子因貧失所從。","惆悵東臯却歸去，人間無處更相逢。"]', '["怜君孤壠寄雙峰，埋骨窮泉复幾重。","白露空霑九原草，青山猶閉數株松。","圖书經亂知何在，妻子因貧失所從。","惆悵东臯却归去，人间無处更相逢。"]', '诗', 'shi', '', NULL, '雙峰下哭故人李宥 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e9b2b2-8032-4c32-b5fe-3def1e3840e3', '使次安陸寄友人', '使次安陸寄友人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["新年草色遠萋萋，久客將歸失路蹊。","暮雨不知溳口處，春風只到穆陵西。","孤城盡日空花落，三戶無人自鳥啼。","君在江南相憶否，門前五柳幾枝低。"]', '["新年草色远萋萋，久客將归失路蹊。","暮雨不知溳口处，春风只到穆陵西。","孤城尽日空花落，三戶無人自鸟啼。","君在江南相憶否，门前五柳幾枝低。"]', '诗', 'shi', '', NULL, '使次安陸寄友人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a31f91c-d216-4169-9e56-b7f8794486a8', '哭陳歙州', '哭陳歙州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["千秋萬古葬平原，素業清風及子孫。","旅櫬歸程傷道路，舉家行哭向田園。","空山寂寂開新壠，喬木蒼蒼掩舊門。","儒行公才竟何在，獨憐棠樹一枝存。"]', '["千秋万古葬平原，素業清风及子孫。","旅櫬归程傷道路，舉家行哭向田园。","空山寂寂开新壠，喬木蒼蒼掩旧门。","儒行公才竟何在，独怜棠樹一枝存。"]', '诗', 'shi', '', NULL, '哭陳歙州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3955c600-fc70-4d7f-9daf-bdd7d1d83b7d', '酬屈突陜', '酬屈突陜', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["落葉紛紛滿四鄰，蕭條環堵絕風塵。","鄉看秋草歸無路，家對寒江病且貧。","藜杖懶迎征騎客，菊花能醉去官人。","憐君計畫誰知者，但見蓬蒿空沒身。"]', '["落葉紛紛满四鄰，蕭條环堵絕风塵。","乡看秋草归無路，家对寒江病且貧。","藜杖懶迎征騎客，菊花能醉去官人。","怜君計畫誰知者，但见蓬蒿空沒身。"]', '诗', 'shi', '', NULL, '酬屈突陜 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28deb91b-aaa3-4c2f-8563-a36a97dfdf3f', '送惠法師遊天台因懷智大師故居', '送惠法師游天台因懷智大師故居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["翠屏瀑水知何在，鳥道猨啼過幾重。","落日獨搖金策去，深山誰向石橋逢。","定攀巖下叢生桂，欲買雲中若箇峰。","憶想東林禪誦處，寂寥惟聽舊時鐘。"]', '["翠屏瀑水知何在，鸟道猨啼過幾重。","落日独搖金策去，深山誰向石橋逢。","定攀巖下叢生桂，欲買云中若箇峰。","憶想东林禪誦处，寂寥惟听旧时鐘。"]', '诗', 'shi', '', NULL, '送惠法師遊天台因懷智大師故居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f049d66-1513-407f-bb4e-cf25a7b5069a', '自夏口至鸚鵡洲夕望岳陽寄源中丞', '自夏口至鸚鵡洲夕望岳陽寄源中丞', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["[汀]洲無浪復無煙，楚客相思益渺然。","漢口夕陽斜渡鳥，洞庭秋水遠連天。","孤城背嶺寒吹角，獨戍臨江夜泊船。","賈誼上書憂漢室，長沙謫去古今憐。"]', '["[汀]洲無浪复無煙，楚客相思益渺然。","漢口夕陽斜渡鸟，洞庭秋水远連天。","孤城背嶺寒吹角，独戍臨江夜泊船。","賈誼上书憂漢室，长沙謫去古今怜。"]', '诗', 'shi', '', NULL, '自夏口至鸚鵡洲夕望岳陽寄源中丞 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2e7187-f5eb-4aab-81db-fb4258110e3b', '送侯中丞流康州', '送侯中丞流康州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長江極目帶楓林，匹馬孤雲不可尋。","遷播共知臣道枉，猜讒却爲主恩深。","轅門畫角三軍思，驛路青山萬里心。","北闕九重誰許屈，獨看湘水淚霑襟。"]', '["长江極目带楓林，匹马孤云不可尋。","遷播共知臣道枉，猜讒却爲主恩深。","轅门畫角三軍思，驛路青山万里心。","北闕九重誰許屈，独看湘水泪霑襟。"]', '诗', 'shi', '', NULL, '送侯中丞流康州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf9ae01-feb3-4a31-a3ac-6148b69831fe', '別嚴士元', '別嚴士元', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["春風倚棹闔閭城，水國春寒陰復晴。","細雨濕衣看不見，閑花落地聽無聲。","日斜江上孤帆影，草綠湖南萬里情。","東道若逢相識問，青袍今日誤儒生。"]', '["春风倚棹闔閭城，水国春寒陰复晴。","細雨濕衣看不见，闲花落地听無声。","日斜江上孤帆影，草綠湖南万里情。","东道若逢相識问，青袍今日誤儒生。"]', '诗', 'shi', '', NULL, '別嚴士元 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38180b90-13e7-49c5-8c06-3cc6708a4e6b', '避地江東留別淮南使院諸公', '避地江东留別淮南使院諸公', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["長安路絕鳥飛通，萬里孤雲西復東。","舊業已應成茂草，餘生只是任飄蓬。","何辭向物開秦鏡，却使他人得楚弓。","此去行持一竿竹，等閑將狎釣漁翁。"]', '["长安路絕鸟飞通，万里孤云西复东。","旧業已應成茂草，餘生只是任飄蓬。","何辞向物开秦镜，却使他人得楚弓。","此去行持一竿竹，等闲將狎釣漁翁。"]', '诗', 'shi', '', NULL, '避地江東留別淮南使院諸公 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4dceb4e-87b7-4665-87cc-be76263b9d94', '罪所上御史惟則', '罪所上御史惟則', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["誤因微祿滯南昌，幽繫圜扉晝夜長。","黃鶴翅垂同燕雀，青松心在任風霜。","斗間誰與看冤氣，盆下無由見太陽。","賢達不能同感激，更於何處問蒼蒼。"]', '["誤因微祿滯南昌，幽繫圜扉晝夜长。","黄鹤翅垂同燕雀，青松心在任风霜。","斗间誰與看冤氣，盆下無由见太陽。","賢達不能同感激，更於何处问蒼蒼。"]', '诗', 'shi', '', NULL, '罪所上御史惟則 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a28d9de-0421-4fd4-802b-c4a00638d54a', '送台州李使君兼寄題國清寺', '送台州李使君兼寄題国清寺', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["露冕新承明主恩，山城別是武陵源。","花間五馬時行縣，山外千峰常在門。","晴江洲渚帶春草，古寺杉松深暮猨。","知到應真飛錫處，因君一想已忘言。"]', '["露冕新承明主恩，山城別是武陵源。","花间五马时行縣，山外千峰常在门。","晴江洲渚带春草，古寺杉松深暮猨。","知到應真飞錫处，因君一想已忘言。"]', '诗', 'shi', '', NULL, '送台州李使君兼寄題國清寺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96676df5-e945-4423-928d-d45ebaf99ed9', '獄中聞收東京有赦', '獄中闻收东京有赦', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["傳聞闕下降絲綸，爲報關東滅虜塵。","壯志已憐成白首，餘生猶待發青春。","風霜何事偏傷物，天地無情亦愛人。","持法不須張密網，恩波自解惜枯鱗。"]', '["傳闻闕下降絲綸，爲報关东滅虜塵。","壯志已怜成白首，餘生猶待發青春。","风霜何事偏傷物，天地無情亦愛人。","持法不須張密網，恩波自解惜枯鱗。"]', '诗', 'shi', '', NULL, '獄中聞收東京有赦 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aedfbefc-e345-4396-b23e-3323346f6f12', '溫湯客舍', '溫湯客舍', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["冬狩溫泉歲欲闌，宮城佳氣晚宜看。","湯熏仗裏千旗暖，雪照山邊萬井寒。","君門獻賦誰相達，客舍無錢輙自安。","且喜禮闈秦鏡在，還將妍醜付春官。"]', '["冬狩溫泉歲欲闌，宮城佳氣晚宜看。","湯熏仗裏千旗暖，雪照山邊万井寒。","君门獻賦誰相達，客舍無錢輙自安。","且喜禮闈秦镜在，還將妍醜付春官。"]', '诗', 'shi', '', NULL, '溫湯客舍 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce7b24e-e6dd-4298-8ac9-8f810b581d4a', '送孫逸歸廬山', '送孫逸归廬山', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["鑪峰絕頂楚雲銜，楚客東歸棲此巖。","彭蠡湖邊香橘柚，潯陽郭外暗楓杉。","青山不斷三湘道，飛鳥空隨萬里帆。","常愛此中多勝事，新詩他日佇開緘。"]', '["鑪峰絕頂楚云銜，楚客东归棲此巖。","彭蠡湖邊香橘柚，潯陽郭外暗楓杉。","青山不斷三湘道，飞鸟空隨万里帆。","常愛此中多勝事，新诗他日佇开緘。"]', '诗', 'shi', '', NULL, '送孫逸歸廬山 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b83c38d-6c25-4245-8a61-5be739961c66', '送馬秀才落第歸江南', '送马秀才落第归江南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南客懷歸鄉夢頻，東門悵別柳條新。","慇懃斗酒城陰暮，蕩漾孤舟楚水春。","湘竹舊斑思帝子，江蘺初綠怨騷人。","憐君此去未得意，陌上愁看淚滿巾。"]', '["南客懷归乡梦頻，东门悵別柳條新。","慇懃斗酒城陰暮，蕩漾孤舟楚水春。","湘竹旧斑思帝子，江蘺初綠怨騷人。","怜君此去未得意，陌上愁看泪满巾。"]', '诗', 'shi', '', NULL, '送馬秀才落第歸江南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c4e8dc8-3c7d-4397-a00f-dc7bb1dcc8f3', '送常十九歸嵩少故林', '送常十九归嵩少故林', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迢迢此恨杳無涯，楚澤嵩丘千里賒。","岐路別時驚一葉，雲林歸處憶三花。","秋天蒼翠寒飛鴈，古堞蕭條晚噪鵶。","他日山中逢勝事，桃源洞裏幾人家。"]', '["迢迢此恨杳無涯，楚澤嵩丘千里賒。","岐路別时驚一葉，云林归处憶三花。","秋天蒼翠寒飞鴈，古堞蕭條晚噪鵶。","他日山中逢勝事，桃源洞裏幾人家。"]', '诗', 'shi', '', NULL, '送常十九歸嵩少故林 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ff7d73-e7dd-4f9d-a422-68f21b8af488', '送宇文遷明府赴洪州張觀察追攝豐城令', '送宇文遷明府赴洪州張观察追攝豐城令', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["送君不復遠爲心，余亦扁舟湘水陰。","路逐山光何處盡，春隨草色向南深。","陳蕃待客應懸榻，宓賤之官獨抱琴。","儻見主人論謫宦，爾來空有白頭吟。"]', '["送君不复远爲心，余亦扁舟湘水陰。","路逐山光何处尽，春隨草色向南深。","陳蕃待客應懸榻，宓賤之官独抱琴。","儻见主人論謫宦，爾来空有白头吟。"]', '诗', 'shi', '', NULL, '送宇文遷明府赴洪州張觀察追攝豐城令 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b587cf7-7828-4c9f-8397-fdd063f62117', '送李將軍', '送李將軍', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["征西諸將一如君，報德誰能不顧勳。","身逐塞鴻來萬里，手披荒草看孤墳。","擒生絕漠經胡雪，懷舊長沙哭楚雲。","歸去蕭條灞陵上，幾人看葬李將軍。"]', '["征西諸將一如君，報德誰能不顧勳。","身逐塞鴻来万里，手披荒草看孤墳。","擒生絕漠經胡雪，懷旧长沙哭楚云。","归去蕭條灞陵上，幾人看葬李將軍。"]', '诗', 'shi', '', NULL, '送李將軍 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7deeb8-5c1a-4287-a752-6448e133c82e', '西陵寄一上人', '西陵寄一上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["東山訪道成開士，南渡隋陽作本師。","了義惠心能善誘，吳風越俗罷淫祠。","室中時見天人命，物外長懸海嶽期。","多謝清言異玄度，懸河高論有誰持。"]', '["东山訪道成开士，南渡隋陽作本師。","了義惠心能善誘，吳风越俗罷淫祠。","室中时见天人命，物外长懸海嶽期。","多謝清言異玄度，懸河高論有誰持。"]', '诗', 'shi', '', NULL, '西陵寄一上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d292d2-b752-4c30-8b6b-7b7380f2f9bd', '賦得', '賦得', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["鶯啼燕語報新年，馬邑龍堆路幾千。","家住層城臨漢苑，[心]隨明月到胡天。","機中錦字論長恨，樓上花枝笑獨眠。","爲問元戎竇車騎，何時返斾勒燕然。"]', '["鶯啼燕語報新年，马邑龙堆路幾千。","家住層城臨漢苑，[心]隨明月到胡天。","機中錦字論长恨，楼上花枝笑独眠。","爲问元戎竇车騎，何时返斾勒燕然。"]', '诗', 'shi', '', NULL, '賦得 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e07c10e1-d8dc-4873-90a2-c1541adafc97', '三月李明府後亭泛舟', '三月李明府後亭泛舟', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江南風景復如何，聞道新亭更欲過。","處處紉蘭春浦淥，萋萋籍草遠山多。","壺觴須就陶彭澤，時俗猶傳晉永和。","更待持橈徐轉去，微風落日水增波。"]', '["江南风景复如何，闻道新亭更欲過。","处处紉蘭春浦淥，萋萋籍草远山多。","壺觴須就陶彭澤，时俗猶傳晉永和。","更待持橈徐轉去，微风落日水增波。"]', '诗', 'shi', '', NULL, '三月李明府後亭泛舟 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8bfa420-dc17-443a-bd6a-16e605824344', '喜朱拾遺承恩拜命赴任上都', '喜朱拾遺承恩拜命赴任上都', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["詔書徵拜脫荷裳，身去東山閉草堂。","閶闔九天通奏籍，華亭一鶴在朝行。","滄洲離別風煙遠，青瑣幽深漏刻長。","今日却迴垂釣處，海鷗相見已高翔。"]', '["詔书徵拜脫荷裳，身去东山閉草堂。","閶闔九天通奏籍，华亭一鹤在朝行。","滄洲離別风煙远，青瑣幽深漏刻长。","今日却迴垂釣处，海鷗相见已高翔。"]', '诗', 'shi', '', NULL, '喜朱拾遺承恩拜命赴任上都 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99398e91-1389-4bb1-9590-0469377bf33d', '鄖上送韋司士歸上都舊業', '鄖上送韋司士归上都旧業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["前朝舊業想遺塵，今日他鄉獨爾身。","鄖地國除爲過客，杜陵家在有何人。","蒼苔白露生三徑，古木寒蟬滿四鄰。","西去茫茫問歸路，關河漸近淚盈巾。"]', '["前朝旧業想遺塵，今日他乡独爾身。","鄖地国除爲過客，杜陵家在有何人。","蒼苔白露生三徑，古木寒蟬满四鄰。","西去茫茫问归路，关河漸近泪盈巾。"]', '诗', 'shi', '', NULL, '鄖上送韋司士歸上都舊業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6411113-bf90-4d8e-8fe8-ead16b7dd596', '感懷', '感懷', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["秋風落葉正堪悲，黃菊殘花欲待誰。","水近偏逢寒氣早，山深常見日光遲。","愁中卜命看周易，夢裏招魂讀楚詞。","自笑不如湘浦鴈，飛來即是北歸時。"]', '["秋风落葉正堪悲，黄菊殘花欲待誰。","水近偏逢寒氣早，山深常见日光遲。","愁中卜命看周易，梦裏招魂读楚词。","自笑不如湘浦鴈，飞来即是北归时。"]', '诗', 'shi', '', NULL, '感懷 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7c1127-a645-49fa-9c54-e3434b7fb7b1', '送楊於陵歸宋汴州別業', '送楊於陵归宋汴州別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["半山溪雨帶斜暉，向水殘花映客衣。","旅食嗟余當歲晚，能文似汝少年稀。","新河柳色千株暗，故國雲帆萬里歸。","離亂要知君到處，寄書須及鴈南飛。"]', '["半山溪雨带斜暉，向水殘花映客衣。","旅食嗟余當歲晚，能文似汝少年稀。","新河柳色千株暗，故国云帆万里归。","離亂要知君到处，寄书須及鴈南飞。"]', '诗', 'shi', '', NULL, '送楊於陵歸宋汴州別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5945c40b-69ab-4925-ad01-a1ebb37ef3ea', '送崔使君赴壽州', '送崔使君赴壽州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["列郡專城分國憂，彤幨皂蓋古諸侯。","仲華遇主年猶少，公瑾論功位已酬。","草色青青迎建隼，蟬聲處處雜鳴騶。","千里相思如可見，淮南木葉正驚秋。"]', '["列郡專城分国憂，彤幨皂蓋古諸侯。","仲华遇主年猶少，公瑾論功位已酬。","草色青青迎建隼，蟬声处处杂鳴騶。","千里相思如可见，淮南木葉正驚秋。"]', '诗', 'shi', '', NULL, '送崔使君赴壽州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf3d96af-0a99-456a-966e-00bef5d97a6a', '上陽宮望幸', '上陽宮望幸', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["玉輦西巡久未還，春光猶入上陽間。","萬木長承新雨露，千門空對舊河山。","深花寂寂宮城閉，細草青青御路閑。","獨見彩雲飛不盡，只應來去候龍顏。"]', '["玉輦西巡久未還，春光猶入上陽间。","万木长承新雨露，千门空对旧河山。","深花寂寂宮城閉，細草青青御路闲。","独见彩云飞不尽，只應来去候龙顏。"]', '诗', 'shi', '', NULL, '上陽宮望幸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cc266d3-a598-4ead-8436-e2699bde4885', '過裴舍人故居', '過裴舍人故居', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["慘慘天寒獨掩扃，紛紛黃葉滿空庭。","孤墳何處依山木，百口無家學水萍。","籬花猶及重陽發，鄰笛那堪落日聽。","書幌無人長不捲，秋來芳草自爲螢。"]', '["慘慘天寒独掩扃，紛紛黄葉满空庭。","孤墳何处依山木，百口無家学水萍。","籬花猶及重陽發，鄰笛那堪落日听。","书幌無人长不捲，秋来芳草自爲螢。"]', '诗', 'shi', '', NULL, '過裴舍人故居 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2bc9e19-d45c-49f5-be3e-de49b001df76', '登松江驛樓北望故園', '登松江驛楼北望故园', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["淚盡江樓北望歸，田園已陷百重圍。","平蕪萬里無人去，落日千山空鳥飛。","孤舟漾漾寒潮小，極浦蒼蒼遠樹微。","白鷗漁父徒相待，未掃欃槍嬾息機。"]', '["泪尽江楼北望归，田园已陷百重圍。","平蕪万里無人去，落日千山空鸟飞。","孤舟漾漾寒潮小，極浦蒼蒼远樹微。","白鷗漁父徒相待，未掃欃槍嬾息機。"]', '诗', 'shi', '', NULL, '登松江驛樓北望故園 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f6b1aa1-f00b-4901-91cd-d55a1ede6337', '秋夜有懷高三十五適兼呈空上人', '秋夜有懷高三十五適兼呈空上人', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["晚節逢君趣道深，結茅栽樹近東林。","吾師幾度曾摩頂，高士何年遂發心。","北渚三更聞過鴈，西城萬里動寒砧。","不見支公與玄度，相思擁膝坐長吟。"]', '["晚節逢君趣道深，結茅栽樹近东林。","吾師幾度曾摩頂，高士何年遂發心。","北渚三更闻過鴈，西城万里动寒砧。","不见支公與玄度，相思擁膝坐长吟。"]', '诗', 'shi', '', NULL, '秋夜有懷高三十五適兼呈空上人 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea1c468-eee0-401e-8303-68f5bc515e62', '送孔巢父赴河南軍', '送孔巢父赴河南軍', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["江南相送隔煙波，況復新秋一鴈過。","聞道全軍征北虜，又言詩將會南河。","邊心冉冉鄉人絕，寒色青青戰馬多。","共許陳琳工奏記，知君名行未蹉跎。"]', '["江南相送隔煙波，況复新秋一鴈過。","闻道全軍征北虜，又言诗將會南河。","邊心冉冉乡人絕，寒色青青戰马多。","共許陳琳工奏記，知君名行未蹉跎。"]', '诗', 'shi', '', NULL, '送孔巢父赴河南軍 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9878f498-8dff-41c1-872f-8ae5af36dbcf', '登潤州萬歲樓', '登潤州万歲楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["高樓獨上思依依，極浦遙山合翠微。","江客不堪頻北望，寒鴻何事又南飛。","垂山古渡寒煙積，瓜步空洲遠樹稀。","聞道王師猶轉戰，更能談笑解重圍。"]', '["高楼独上思依依，極浦遙山合翠微。","江客不堪頻北望，寒鴻何事又南飞。","垂山古渡寒煙積，瓜步空洲远樹稀。","闻道王師猶轉戰，更能談笑解重圍。"]', '诗', 'shi', '', NULL, '登潤州萬歲樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc5b8457-08db-481c-b004-43e0a1adf3df', '江樓送太康郭主簿赴嶺南', '江楼送太康郭主簿赴嶺南', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["對酒憐君安可論，當官愛士如平原。","料錢用盡却爲謗，食客空多誰報恩。","萬里孤舟向南越，蒼梧雲中暮帆滅。","樹色應無江北秋，天涯尚見淮陽月。","驛路南隨桂水流，猨聲不絕到炎州。","青山落日那堪望，誰見思君江上樓。"]', '["对酒怜君安可論，當官愛士如平原。","料錢用尽却爲謗，食客空多誰報恩。","万里孤舟向南越，蒼梧云中暮帆滅。","樹色應無江北秋，天涯尚见淮陽月。","驛路南隨桂水流，猨声不絕到炎州。","青山落日那堪望，誰见思君江上楼。"]', '诗', 'shi', '', NULL, '江樓送太康郭主簿赴嶺南 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2562544c-5ab9-47f4-aa34-f4a8038cb2fa', '客舍喜鄭三見寄', '客舍喜鄭三见寄', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["客舍逢君未換衣，閉門愁見桃花飛。","遙想故園今已爾，家人應念行人歸。","寂寞垂楊映深曲，長安日暮靈臺宿。","窮巷無人鳥雀閑，空庭新雨莓苔綠。","北中分與故交疎，何幸仍迴長者車。","十年未稱平生意，好得辛勤謾讀書。"]', '["客舍逢君未換衣，閉门愁见桃花飞。","遙想故园今已爾，家人應念行人归。","寂寞垂楊映深曲，长安日暮靈台宿。","窮巷無人鸟雀闲，空庭新雨莓苔綠。","北中分與故交疎，何幸仍迴长者车。","十年未稱平生意，好得辛勤謾读书。"]', '诗', 'shi', '', NULL, '客舍喜鄭三見寄 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d3e30d-97a9-48e3-a6c8-47a6e581d379', '送賈三北遊', '送賈三北游', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["賈生未達猶窘迫，身馳匹馬邯鄲陌。","片雲郊外遙送人，斗酒城邊暮留客。","顧予他日仰時髦，不堪此別相思勞。","雨色新添漳水綠，夕陽遠照蘇門高。","把袂相看衣共緇，窮愁只是惜良時。","亦知到處逢下榻，莫滯秋風西上期。"]', '["賈生未達猶窘迫，身驰匹马邯鄲陌。","片云郊外遙送人，斗酒城邊暮留客。","顧予他日仰时髦，不堪此別相思勞。","雨色新添漳水綠，夕陽远照蘇门高。","把袂相看衣共緇，窮愁只是惜良时。","亦知到处逢下榻，莫滯秋风西上期。"]', '诗', 'shi', '', NULL, '送賈三北遊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ab90a9-bba5-40f3-b16c-1f0ab0f55278', '齊一和尚影堂', '齊一和尚影堂', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["一公住世忘世紛，暫來復去誰能分。","身寄虛空如過客，心將生滅是浮雲。","蕭散浮雲往不還，淒涼遺教歿仍傳。","舊地愁看雙樹在，空堂只是一燈懸。","一燈長照恆河沙，雙樹猶落諸天花。","天花寂寂香深殿，苔蘚蒼蒼閟虛院。","昔余精念訪禪扉，常接微言清道機。","今來寂寞無所得，唯共門人淚滿衣。"]', '["一公住世忘世紛，暫来复去誰能分。","身寄虛空如過客，心將生滅是浮云。","蕭散浮云往不還，淒涼遺教歿仍傳。","旧地愁看雙樹在，空堂只是一灯懸。","一灯长照恆河沙，雙樹猶落諸天花。","天花寂寂香深殿，苔蘚蒼蒼閟虛院。","昔余精念訪禪扉，常接微言清道機。","今来寂寞無所得，唯共门人泪满衣。"]', '诗', 'shi', '', NULL, '齊一和尚影堂 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab2a6dc6-6806-4667-8fe5-032dae7c481e', '潁川留別司倉李萬', '潁川留別司倉李万', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["故人早負干將器，誰言未展平生意。","想君疇昔高步時，肯料如今折腰事。","且知投刃皆若虛，日揮案牘常有餘。","槐暗公庭趨小吏，荷香陂水膾鱸魚。","客裏相逢款話深，如何岐路剩霑襟。","白雲西上催歸念，潁水東流是別心。","落日征驂隨去塵，含情揮手背城闉。","已恨良時空此別，不堪秋草更愁人。"]', '["故人早負干將器，誰言未展平生意。","想君疇昔高步时，肯料如今折腰事。","且知投刃皆若虛，日揮案牘常有餘。","槐暗公庭趨小吏，荷香陂水膾鱸鱼。","客裏相逢款話深，如何岐路剩霑襟。","白云西上催归念，潁水东流是別心。","落日征驂隨去塵，含情揮手背城闉。","已恨良时空此別，不堪秋草更愁人。"]', '诗', 'shi', '', NULL, '潁川留別司倉李萬 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e81b01a-81f5-42bd-8dba-9382999257b5', '聽笛歌', '听笛歌', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["舊遊憐我長沙謫，載酒沙頭送遷客。","天涯望月自霑衣，江上何人復吹笛。","橫笛能令孤客愁，淥波淡淡如不流。","商聲寥亮羽聲苦，江天寂歷江楓秋。","靜聽關山聞一叫，三湘月色悲猨嘯。","又吹楊柳激繁音，千里春色傷人心。","隨風飄向何處落，唯見曲盡平湖深。","明發與君離別後，馬上一聲堪白首。"]', '["旧游怜我长沙謫，載酒沙头送遷客。","天涯望月自霑衣，江上何人复吹笛。","橫笛能令孤客愁，淥波淡淡如不流。","商声寥亮羽声苦，江天寂歷江楓秋。","静听关山闻一叫，三湘月色悲猨嘯。","又吹楊柳激繁音，千里春色傷人心。","隨风飄向何处落，唯见曲尽平湖深。","明發與君離別後，马上一声堪白首。"]', '诗', 'shi', '', NULL, '聽笛歌 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4b3d8a-b7a0-4d97-af64-a68b4514b2be', '時平後送范倫歸安州', '时平後送范倫归安州', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["昨聞戰罷圖麟閣，破虜收兵卷戎幕。","滄海初看漢月明，紫微已見胡星落。","憶昔扁舟此南渡，荆棘煙塵滿歸路。","與君攜手姑蘇臺，望鄉一日登幾迴。","白雲飛鳥去寂寞，吳山楚岫空崔嵬。","事往時平還舊丘，青青春草近家愁。","洛陽舉目今誰在，潁水無情應自流。","吳苑西人去欲稀，留連一日空知非。","江潭歲盡愁不盡，鴻鴈春歸身未歸。","萬里遙懸帝鄉憶，五年空帶風塵色。","却到長安逢故人，不道姓名應不識。"]', '["昨闻戰罷圖麟閣，破虜收兵卷戎幕。","滄海初看漢月明，紫微已见胡星落。","憶昔扁舟此南渡，荆棘煙塵满归路。","與君携手姑蘇台，望乡一日登幾迴。","白云飞鸟去寂寞，吳山楚岫空崔嵬。","事往时平還旧丘，青青春草近家愁。","洛陽舉目今誰在，潁水無情應自流。","吳苑西人去欲稀，留連一日空知非。","江潭歲尽愁不尽，鴻鴈春归身未归。","万里遙懸帝乡憶，五年空带风塵色。","却到长安逢故人，不道姓名應不識。"]', '诗', 'shi', '', NULL, '時平後送范倫歸安州 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45bc67b6-c251-4afb-b3ac-931fc35cc499', '小鳥篇上裴尹', '小鸟篇上裴尹', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["藩籬小鳥何甚微，翩翩日夕空此飛。","只緣六翮不自致，長似孤雲無所依。","西城黯黯斜暉落，衆鳥紛紛皆有託。","獨立雖輕燕雀羣，孤飛遠懼鷹鸇搏。","自憐天上青雲路，弔影徘徊獨愁暮。","銜花縱有報恩時，擇木誰容托身處。","歲月蹉跎飛不進，羽毛鷦顇何人問。","遶樹空隨烏鵲驚，巢林只有鷦鷯分。","主人庭中蔭喬木，愛此清陰欲棲宿。","少年挾彈遙相猜，遂使驚飛往復迴。","不辭奮翼向君去，唯怕金丸隨後來。"]', '["藩籬小鸟何甚微，翩翩日夕空此飞。","只緣六翮不自致，长似孤云無所依。","西城黯黯斜暉落，衆鸟紛紛皆有託。","独立雖轻燕雀羣，孤飞远懼鷹鸇搏。","自怜天上青云路，弔影徘徊独愁暮。","銜花縱有報恩时，擇木誰容托身处。","歲月蹉跎飞不進，羽毛鷦顇何人问。","遶樹空隨烏鵲驚，巢林只有鷦鷯分。","主人庭中蔭喬木，愛此清陰欲棲宿。","少年挾彈遙相猜，遂使驚飞往复迴。","不辞奮翼向君去，唯怕金丸隨後来。"]', '诗', 'shi', '', NULL, '小鳥篇上裴尹 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9982930-a653-46df-9fe4-1d007f9c0f3e', '登吳古城歌', '登吳古城歌', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["登古城兮思古人，感賢達兮同埃塵。","望平原兮寄遠目，歎姑蘇兮聚麋鹿。","黃池高會事未終，滄海橫流人蕩覆。","伍員殺身誰不冤，竟看墓樹如所言。","越王嘗膽安可敵，遠取石田何所益。","一朝空謝會稽人，萬古猶傷甬東客。","黍離離兮城坡坨，牛羊踐兮牧豎歌。","野無人兮秋草綠，園爲墟兮古木多。","白楊蕭蕭悲故柯，黃雀啾啾爭晚禾。","荒阡斷兮誰重過，孤舟逝兮愁若何。","天寒日暮江楓落，葉去辭風水自波。"]', '["登古城兮思古人，感賢達兮同埃塵。","望平原兮寄远目，歎姑蘇兮聚麋鹿。","黄池高會事未終，滄海橫流人蕩覆。","伍員殺身誰不冤，竟看墓樹如所言。","越王嘗膽安可敵，远取石田何所益。","一朝空謝會稽人，万古猶傷甬东客。","黍離離兮城坡坨，牛羊踐兮牧豎歌。","野無人兮秋草綠，园爲墟兮古木多。","白楊蕭蕭悲故柯，黄雀啾啾爭晚禾。","荒阡斷兮誰重過，孤舟逝兮愁若何。","天寒日暮江楓落，葉去辞风水自波。"]', '诗', 'shi', '', NULL, '登吳古城歌 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43fbf223-5b50-4248-b7d2-3087b1c75909', '疲兵篇', '疲兵篇', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["驕虜乘秋下薊門，陰山日夕煙塵昏。","三軍疲馬力已盡，百戰殘兵功未論。","陣雲泱漭屯塞北，羽書紛紛來不息。","孤城望處增斷腸，折劍看時可霑臆。","元戎日夕且歌舞，不念關山久辛苦。","自矜倚劍氣凌雲，却笑聞笳淚如雨。","萬里飄颻空此身，十年征戰老胡塵。","赤心報國無片賞，白首還家有幾人。","朔風蕭蕭動枯草，旌旗獵獵榆關道。","漢月何曾照客心，胡笳只解催人老。","軍前仍欲破重圍，閨裏猶應愁未歸。","小婦十年啼夜織，行人九月憶寒衣。","飲馬滹河晚更清，行吹羗笛遠歸營。","只恨漢家多苦戰，徒遺金鏃滿長城。"]', '["驕虜乘秋下薊门，陰山日夕煙塵昏。","三軍疲马力已尽，百戰殘兵功未論。","陣云泱漭屯塞北，羽书紛紛来不息。","孤城望处增斷腸，折劍看时可霑臆。","元戎日夕且歌舞，不念关山久辛苦。","自矜倚劍氣凌云，却笑闻笳泪如雨。","万里飄颻空此身，十年征戰老胡塵。","赤心報国無片賞，白首還家有幾人。","朔风蕭蕭动枯草，旌旗獵獵榆关道。","漢月何曾照客心，胡笳只解催人老。","軍前仍欲破重圍，閨裏猶應愁未归。","小婦十年啼夜织，行人九月憶寒衣。","饮马滹河晚更清，行吹羗笛远归營。","只恨漢家多苦戰，徒遺金鏃满长城。"]', '诗', 'shi', '', NULL, '疲兵篇 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e558a7b7-7fd0-4b33-97e5-8bf2a9f37bd2', '新安送陸[澧]歸江陰', '新安送陸[澧]归江陰', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["新安路，人來去。","早潮復晚潮，明日知何處。","潮水無情亦解歸，自憐長在新安住。"]', '["新安路，人来去。","早潮复晚潮，明日知何处。","潮水無情亦解归，自怜长在新安住。"]', '诗', 'shi', '', NULL, '新安送陸[澧]歸江陰 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb9a70e-157d-443b-b978-cc723b5786b0', '弄白鷗歌', '弄白鷗歌', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["泛泛江上鷗，毛衣皓如雪。","朝飛瀟湘水，夜宿洞庭月。","歸客正夷猶，愛此滄江閑白鷗。"]', '["泛泛江上鷗，毛衣皓如雪。","朝飞瀟湘水，夜宿洞庭月。","归客正夷猶，愛此滄江闲白鷗。"]', '诗', 'shi', '', NULL, '弄白鷗歌 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aca36692-0e5b-444f-9abc-3b1a1916b2dc', '長沙贈衡岳祝融峰般若禪師', '长沙贈衡岳祝融峰般若禪師', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["般若公，般若公，負鉢何時下祝融。","歸路却看飛鳥外，禪房空掩白雲中。","桂花寥寥閑自落，流水無心西復東。"]', '["般若公，般若公，負鉢何时下祝融。","归路却看飞鸟外，禪房空掩白云中。","桂花寥寥闲自落，流水無心西复东。"]', '诗', 'shi', '', NULL, '長沙贈衡岳祝融峰般若禪師 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b5c07e-de40-4cfa-ab6f-03e2e361b3f6', '贈湘南漁父', '贈湘南漁父', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["聞君何所適，暮暮逢煙水。","獨與不繫舟，往來楚雲裏。","釣魚非一歲，終日只如此。","日落江清桂檝遲，纖鱗百尺深可窺。","沈鉤垂餌不在得，白首滄浪空自知。"]', '["闻君何所適，暮暮逢煙水。","独與不繫舟，往来楚云裏。","釣鱼非一歲，終日只如此。","日落江清桂檝遲，纖鱗百尺深可窺。","沈鉤垂餌不在得，白首滄浪空自知。"]', '诗', 'shi', '', NULL, '贈湘南漁父 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4714311-5f29-4d71-9013-2e3bc1167142', '明月灣尋賀九不遇', '明月灣尋賀九不遇', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["楚水日夜綠，傍江春草滋。","青青遙滿目，萬里傷心歸。","故人川上復何之，明月灣南空所思。","故人不在明月在，誰見孤舟來去時。"]', '["楚水日夜綠，傍江春草滋。","青青遙满目，万里傷心归。","故人川上复何之，明月灣南空所思。","故人不在明月在，誰见孤舟来去时。"]', '诗', 'shi', '', NULL, '明月灣尋賀九不遇 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0735f62f-1da0-4fad-988a-16b031265468', '題曲阿三昧王佛殿前孤石', '題曲阿三昧王佛殿前孤石', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["孤石自何處，對之疑舊遊。","氛氳峴首夕，蒼翠剡中秋。","迥出羣峰當殿前，雪山靈鷲慙貞堅。","一片孤雲長不去，莓苔古色空蒼然。"]', '["孤石自何处，对之疑旧游。","氛氳峴首夕，蒼翠剡中秋。","迥出羣峰當殿前，雪山靈鷲慙貞堅。","一片孤云长不去，莓苔古色空蒼然。"]', '诗', 'shi', '', NULL, '題曲阿三昧王佛殿前孤石 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32854806-3d64-426b-a1f1-1d461e19503e', '送友人東歸', '送友人东归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["對酒灞亭暮，相看愁自深。","河邊草已綠，此別難爲心。","關路迢迢匹馬歸，垂楊寂寂數鶯飛。","憐君獻策十餘載，今日猶爲一布衣。"]', '["对酒灞亭暮，相看愁自深。","河邊草已綠，此別难爲心。","关路迢迢匹马归，垂楊寂寂數鶯飞。","怜君獻策十餘載，今日猶爲一布衣。"]', '诗', 'shi', '', NULL, '送友人東歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57f94ccb-ffbe-4a70-b0e1-388a7100a468', '入桂渚次砂牛石穴', '入桂渚次砂牛石穴', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["扁舟傍歸路，日暮瀟湘深。","湘水清見底，楚雲淡無心。","片帆落桂渚，獨夜依楓林。","楓林月出猨聲苦，桂渚天寒桂花吐。","此中無處不堪愁，江客相看淚如雨。"]', '["扁舟傍归路，日暮瀟湘深。","湘水清见底，楚云淡無心。","片帆落桂渚，独夜依楓林。","楓林月出猨声苦，桂渚天寒桂花吐。","此中無处不堪愁，江客相看泪如雨。"]', '诗', 'shi', '', NULL, '入桂渚次砂牛石穴 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8554bd4-482b-4d28-b579-d2d5a6a4c530', '嚴陵釣臺送李康成赴江東使', '嚴陵釣台送李康成赴江东使', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["潺湲子陵瀨，髣髴如在目。","七里人已非，千年水空綠。","新安江上孤帆遠，應逐楓林萬餘轉。","古臺落日共蕭條，寒水無波更清淺。","臺上漁竿不復持，却令猨鳥向人悲。","灘聲山翠至今在，遲爾行舟晚泊時。"]', '["潺湲子陵瀨，髣髴如在目。","七里人已非，千年水空綠。","新安江上孤帆远，應逐楓林万餘轉。","古台落日共蕭條，寒水無波更清淺。","台上漁竿不复持，却令猨鸟向人悲。","灘声山翠至今在，遲爾行舟晚泊时。"]', '诗', 'shi', '', NULL, '嚴陵釣臺送李康成赴江東使 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eaa9ab7-0a57-41a1-9db9-c59a8fb4af94', '送姨子弟往南郊', '送姨子弟往南郊', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["一展慰久闊，寸心仍未伸。","別時兩童稚，及此俱成人。","那堪適會面，遽已悲分首。","客路向楚雲，河橋對衰柳。","送君匹馬別河橋，汝南山郭寒蕭條。","今我單車復西上，郎去灞陵轉惆悵。","何處共傷離別心，明月亭亭兩鄉望。"]', '["一展慰久闊，寸心仍未伸。","別时兩童稚，及此俱成人。","那堪適會面，遽已悲分首。","客路向楚云，河橋对衰柳。","送君匹马別河橋，汝南山郭寒蕭條。","今我單车复西上，郎去灞陵轉惆悵。","何处共傷離別心，明月亭亭兩乡望。"]', '诗', 'shi', '', NULL, '送姨子弟往南郊 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94fc48c7-b281-4472-bf6b-31e3134a4bd0', '銅雀臺', '銅雀台', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["嬌愛更何日，高臺空數層。","含啼映雙袖，不忍看西陵。","漳河東流無復來，百花輦路爲蒼苔。","[青]樓月夜長寂寞，碧雲日暮空徘徊。","君不見鄴中萬事非昔時，古人不在今人悲。","春風不逐君王去，草色年年舊宮路。","宮中歌舞已浮雲，空指行人往來處。"]', '["嬌愛更何日，高台空數層。","含啼映雙袖，不忍看西陵。","漳河东流無复来，百花輦路爲蒼苔。","[青]楼月夜长寂寞，碧云日暮空徘徊。","君不见鄴中万事非昔时，古人不在今人悲。","春风不逐君王去，草色年年旧宮路。","宮中歌舞已浮云，空指行人往来处。"]', '诗', 'shi', '', NULL, '銅雀臺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370f10de-cf10-42b7-a058-aab0a42817eb', '王昭君歌', '王昭君歌', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["自矜嬌豔色，不顧丹青人。","那知粉繪能相負，却使容華翻誤身。","上馬辭君嫁驕虜，玉顏對人啼不語。","北風鴈急浮雲秋，萬里獨見黃河流。","纖腰不復漢宮寵，雙蛾長向胡天愁。","琵琶弦中苦調多，蕭蕭羌笛聲相和。","誰憐一曲傳樂府，能使千秋傷綺羅。"]', '["自矜嬌豔色，不顧丹青人。","那知粉繪能相負，却使容华翻誤身。","上马辞君嫁驕虜，玉顏对人啼不語。","北风鴈急浮云秋，万里独见黄河流。","纖腰不复漢宮寵，雙蛾长向胡天愁。","琵琶弦中苦調多，蕭蕭羌笛声相和。","誰怜一曲傳乐府，能使千秋傷綺羅。"]', '诗', 'shi', '', NULL, '王昭君歌 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed45702-6381-4819-bbfb-282184753777', '送杜越江佐覲省往新安江', '送杜越江佐覲省往新安江', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["去帆楚天外，望遠愁復積。","想見新安江，扁舟一行客。","清流數千丈，底下看白石。","色混元氣深，波連洞庭碧。","鳴桹去未已，前路行可覿。","猨鳥悲啾啾，杉松雨聲夕。","送君東赴歸寧期，新安江水遠相隨。","見說江中孤嶼在，此行應賦謝公詩。"]', '["去帆楚天外，望远愁复積。","想见新安江，扁舟一行客。","清流數千丈，底下看白石。","色混元氣深，波連洞庭碧。","鳴桹去未已，前路行可覿。","猨鸟悲啾啾，杉松雨声夕。","送君东赴归寧期，新安江水远相隨。","见说江中孤嶼在，此行應賦謝公诗。"]', '诗', 'shi', '', NULL, '送杜越江佐覲省往新安江 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f81c89-f23d-4079-bf05-c2be5b20fca1', '湘中憶歸', '湘中憶归', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["終日空理棹，經年猶別家。","頃來行已遠，彌覺天無涯。","白雲意自深，滄海夢難隔。","迢遞萬里帆，飄颻一行客。","獨憐西江外，遠寄風波裏。","平湖流楚天，孤鴈渡湘水。","湘流澹澹空愁予，猨啼啾啾滿南楚。","扁舟泊處聞此聲，江客相看淚如雨。"]', '["終日空理棹，經年猶別家。","頃来行已远，彌覺天無涯。","白云意自深，滄海梦难隔。","迢遞万里帆，飄颻一行客。","独怜西江外，远寄风波裏。","平湖流楚天，孤鴈渡湘水。","湘流澹澹空愁予，猨啼啾啾满南楚。","扁舟泊处闻此声，江客相看泪如雨。"]', '诗', 'shi', '', NULL, '湘中憶歸 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3cb1b34-5cbf-4975-8f20-6ed06da1b491', '送郭六侍從之武陵郡', '送郭六侍從之武陵郡', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["常愛武陵郡，羨君將遠尋。","空憐世界迫，孤負桃源心。","洛陽遙想桃源隔，野水閑流春自碧。","花下常迷楚客船，洞中時見秦人宅。","落日相看斗酒前，送君南望但依然。","河梁馬首隨春草，江路猨聲愁暮天。","丈人別乘佐分憂，才子趨庭兼勝遊。","澧浦荆門行可見，知君詩興滿滄洲。"]', '["常愛武陵郡，羨君將远尋。","空怜世界迫，孤負桃源心。","洛陽遙想桃源隔，野水闲流春自碧。","花下常迷楚客船，洞中时见秦人宅。","落日相看斗酒前，送君南望但依然。","河梁马首隨春草，江路猨声愁暮天。","丈人別乘佐分憂，才子趨庭兼勝游。","澧浦荆门行可见，知君诗兴满滄洲。"]', '诗', 'shi', '', NULL, '送郭六侍從之武陵郡 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55e7eb2-5814-4a6f-9293-695f6520a538', '山鸜鵒歌', '山鸜鵒歌', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["山鸜鵒，長在此山吟古木。","嘲唽相呼響空谷，哀鳴萬變如成曲。","江南逐臣悲放逐，倚樹聽之心斷續。","巴人峽裏自聞猨，燕客水頭空擊筑。","山鸜鵒，一生不及雙黃鵠。","朝去秋田啄殘粟，暮入寒林嘯羣族。","鳴相逐，啄殘粟，食不足。","青雲杳杳無力飛，白露蒼蒼抱枝宿。","不知何事守空山，萬壑千峰自愁獨。"]', '["山鸜鵒，长在此山吟古木。","嘲唽相呼响空谷，哀鳴万变如成曲。","江南逐臣悲放逐，倚樹听之心斷續。","巴人峽裏自闻猨，燕客水头空擊筑。","山鸜鵒，一生不及雙黄鵠。","朝去秋田啄殘粟，暮入寒林嘯羣族。","鳴相逐，啄殘粟，食不足。","青云杳杳無力飞，白露蒼蒼抱枝宿。","不知何事守空山，万壑千峰自愁独。"]', '诗', 'shi', '', NULL, '山鸜鵒歌 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e6a2d0d-7127-4871-a8e6-779d87d6454b', '望龍山懷道士許法稜', '望龙山懷道士許法稜', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["心惆悵，望龍山。","雲之際，鳥獨還。","懸崖絕壁幾千丈，綠蘿嫋嫋不可攀。","龍山高，誰能踐。","靈原中，蒼翠晚。","嵐煙瀑水如向人，終日迢迢空在眼。","中有一人披霓裳，誦經山頂飧瓊漿。","空林閑坐獨焚香，真官列侍儼成行。","朝入青霄禮玉堂，夜掃白雲眠石牀。","桃花洞裏居人滿，桂樹山中住日長，龍山高高遙相望。"]', '["心惆悵，望龙山。","云之際，鸟独還。","懸崖絕壁幾千丈，綠蘿嫋嫋不可攀。","龙山高，誰能踐。","靈原中，蒼翠晚。","嵐煙瀑水如向人，終日迢迢空在眼。","中有一人披霓裳，誦經山頂飧瓊漿。","空林闲坐独焚香，真官列侍儼成行。","朝入青霄禮玉堂，夜掃白云眠石牀。","桃花洞裏居人满，桂樹山中住日长，龙山高高遙相望。"]', '诗', 'shi', '', NULL, '望龍山懷道士許法稜 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8438bae5-696d-403e-a24d-0ab37248db5e', '戲贈干越尼子歌', '戲贈干越尼子歌', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["鄱陽女子年十五，家本秦人今在楚。","厭向春江空浣沙，龍宮落髮披袈裟。","五年持戒長一食，至今猶自顏如花。","亭亭獨立青蓮下，忍草禪枝繞精舍。","自用黃金買地居，能嫌碧玉隨人嫁。","北客相逢疑姓秦，鉛花拋却仍青春。","一花一竹如有意，不語不笑能留人。","黃鸝欲棲白日暮，天香未散經行處。","却對香爐閑誦經，春泉漱玉寒泠泠。","雲房寂寂夜鐘後，吳音清切令人聽。","人聽吳音歌一曲，杳然如在諸天宿。","誰堪世事更相牽，惆悵迴船江水淥。"]', '["鄱陽女子年十五，家本秦人今在楚。","厭向春江空浣沙，龙宮落髮披袈裟。","五年持戒长一食，至今猶自顏如花。","亭亭独立青蓮下，忍草禪枝繞精舍。","自用黄金買地居，能嫌碧玉隨人嫁。","北客相逢疑姓秦，鉛花拋却仍青春。","一花一竹如有意，不語不笑能留人。","黄鸝欲棲白日暮，天香未散經行处。","却对香爐闲誦經，春泉漱玉寒泠泠。","云房寂寂夜鐘後，吳音清切令人听。","人听吳音歌一曲，杳然如在諸天宿。","誰堪世事更相牽，惆悵迴船江水淥。"]', '诗', 'shi', '', NULL, '戲贈干越尼子歌 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d9c24f-f6f8-4687-9766-75a5274b9292', '游四窗', '游四窗', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["四明山絕奇，自古說登陸。","蒼崖倚天立，覆石如覆屋。","玲瓏開戶牖，落落明四目。","箕星分南野，有斗挂簷北。","日月居東西，朝昏互出沒。","我來游其間，寄傲巾半幅。","白雲本無心，悠然伴幽獨。","對此脫塵鞅，頓忘榮與辱。","長笑天地寬，仙風吹佩玉。"]', '["四明山絕奇，自古说登陸。","蒼崖倚天立，覆石如覆屋。","玲瓏开戶牖，落落明四目。","箕星分南野，有斗挂簷北。","日月居东西，朝昏互出沒。","我来游其间，寄傲巾半幅。","白云本無心，悠然伴幽独。","对此脫塵鞅，頓忘榮與辱。","长笑天地寬，仙风吹佩玉。"]', '诗', 'shi', '', NULL, '游四窗 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('815159c5-8a9a-4668-b05f-b48b2033876e', '和中丞出使恩命過終南別業', '和中丞出使恩命過終南別業', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["不過林園久，多因寵遇偏。","故山長寂寂，春草過年年。","花待朝衣間，雲迎驛騎連。","松蘿深舊閤，樵木散閑田。","拜闕貪搖珮，看琴懶更弦。","君恩催早入，已夢[傅]巖邊。"]', '["不過林园久，多因寵遇偏。","故山长寂寂，春草過年年。","花待朝衣间，云迎驛騎連。","松蘿深旧閤，樵木散闲田。","拜闕貪搖珮，看琴懶更弦。","君恩催早入，已梦[傅]巖邊。"]', '诗', 'shi', '', NULL, '和中丞出使恩命過終南別業 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f5625a-ef7b-48bd-99fe-2bbb5d416c9f', '岳陽樓', '岳陽楼', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["行盡清溪日已蹉，雲容山影兩嵯峨。","樓前歸客怨秋夢，湖上美人疑夜歌。","獨坐高高風勢急，平湖渺渺月明多。","終期一艇載樵去，來往片帆愁白波。"]', '["行尽清溪日已蹉，云容山影兩嵯峨。","楼前归客怨秋梦，湖上美人疑夜歌。","独坐高高风勢急，平湖渺渺月明多。","終期一艇載樵去，来往片帆愁白波。"]', '诗', 'shi', '', NULL, '岳陽樓 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83581f16-b9b7-4586-b001-1642edcf2db3', '春望寄王涔陽', '春望寄王涔陽', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["清明別後雨晴時，極浦空顰一望眉。","湖畔春山煙點點，雲中遠樹墨離離。","依微水戍聞鉦鼓，掩映沙村見酒旗。","風煖草長愁自醉，行吟無處寄相思。"]', '["清明別後雨晴时，極浦空顰一望眉。","湖畔春山煙点点，云中远樹墨離離。","依微水戍闻鉦鼓，掩映沙村见酒旗。","风煖草长愁自醉，行吟無处寄相思。"]', '诗', 'shi', '', NULL, '春望寄王涔陽 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae4ea64b-635e-4857-94eb-ea37d612dc7f', '留辭', '留辞', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["南楚迢迢通漢口，西江淼淼去揚州。","春風已遣歸心促，縱復芳菲不可留。"]', '["南楚迢迢通漢口，西江淼淼去揚州。","春风已遣归心促，縱复芳菲不可留。"]', '诗', 'shi', '', NULL, '留辭 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531c8893-705d-4365-8c15-266806af5b87', '題杼山癸亭得暮字', '題杼山癸亭得暮字', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["杼山多幽絕，勝事盈跬步。","前者雖登攀，淹留恨晨暮。","及茲紆勝引，曾是美無度。","歘構三癸亭，實爲陸生故。","高賢能剏物，疏鑿皆有趣。","不越方丈間，居然雲霄遇。","巍峨倚脩岫，曠望臨古渡。","左右苔石攢，低昂桂枝蠹。","山僧狎猨狖，巢鳥來枳椇。","俯視何楷臺，傍瞻戴顒路。","遲迴未能下，夕照明村樹。"]', '["杼山多幽絕，勝事盈跬步。","前者雖登攀，淹留恨晨暮。","及茲紆勝引，曾是美無度。","歘構三癸亭，實爲陸生故。","高賢能剏物，疏鑿皆有趣。","不越方丈间，居然云霄遇。","巍峨倚脩岫，曠望臨古渡。","左右苔石攢，低昂桂枝蠹。","山僧狎猨狖，巢鸟来枳椇。","俯視何楷台，傍瞻戴顒路。","遲迴未能下，夕照明村樹。"]', '诗', 'shi', '', NULL, '題杼山癸亭得暮字 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9807035e-5bcc-4180-a831-9f8f17ca0589', '謝陸處士杼山折青桂花見寄之什', '謝陸处士杼山折青桂花见寄之什', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["羣子遊杼山，山寒桂花白。","綠荑含素蕚，采折自逋客。","忽枉巖中詩，芳香潤金石。","全高南越蠹，豈謝東堂策。","會愜名山期，從君恣幽覿。"]', '["羣子游杼山，山寒桂花白。","綠荑含素蕚，采折自逋客。","忽枉巖中诗，芳香潤金石。","全高南越蠹，豈謝东堂策。","會愜名山期，從君恣幽覿。"]', '诗', 'shi', '', NULL, '謝陸處士杼山折青桂花見寄之什 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4741cd-b7ee-4d1f-aa46-330d1fdb3de9', '贈裴將軍', '贈裴將軍', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["大君制六合，猛將清九垓。","戰馬若龍虎，騰凌何壯哉。","將軍臨八荒，烜赫耀英材。","劒舞若游電，隨風縈且迴。","登高望天山，白雲正崔巍。","入陣破驕虜，威名雄震雷。","一射百馬倒，再射萬夫開。","匈奴不敢敵，相呼歸去來。","功成報天子，可以畫麟臺。"]', '["大君制六合，猛將清九垓。","戰马若龙虎，腾凌何壯哉。","將軍臨八荒，烜赫耀英材。","劒舞若游電，隨风縈且迴。","登高望天山，白云正崔巍。","入陣破驕虜，威名雄震雷。","一射百马倒，再射万夫开。","匈奴不敢敵，相呼归去来。","功成報天子，可以畫麟台。"]', '诗', 'shi', '', NULL, '贈裴將軍 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958f2bc8-62f2-4ab8-96e5-285dc93fb775', '贈僧皎然', '贈僧皎然', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["秋意西山多，別岑縈左次。","繕亭歷三癸，趾趾鄰什寺。","元化隱靈蹤，始君啓高致。","誅榛養翹楚，鞭草理芳穗。","俯砌披水容，逼天掃峰翠。","境新耳目換，物遠風塵異。","倚石忘世情，援雲得真意。","嘉林幸勿剪，禪侶欣可庇。","衛法大臣過，佐遊羣英萃。","龍池護清激，虎節到深邃。","徒想嵊頂期，于今沒遺記。"]', '["秋意西山多，別岑縈左次。","繕亭歷三癸，趾趾鄰什寺。","元化隐靈蹤，始君啓高致。","誅榛養翹楚，鞭草理芳穗。","俯砌披水容，逼天掃峰翠。","境新耳目換，物远风塵異。","倚石忘世情，援云得真意。","嘉林幸勿剪，禪侶欣可庇。","衛法大臣過，佐游羣英萃。","龙池護清激，虎節到深邃。","徒想嵊頂期，于今沒遺記。"]', '诗', 'shi', '', NULL, '贈僧皎然 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c624f4-7c97-44ab-a244-0473f8ee277a', '詠陶淵明', '詠陶淵明', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["張良思報韓，龔勝恥事新。","狙擊不肯就，舍生悲縉紳。","嗚呼陶淵明，奕葉爲晉臣。","自以公相後，每懷宗國屯。","題詩庚子歲，自謂羲皇人。","手持山海經，頭戴漉酒巾。","興逐孤雲外，心隨還鳥泯。"]', '["張良思報韓，龔勝恥事新。","狙擊不肯就，舍生悲縉紳。","嗚呼陶淵明，奕葉爲晉臣。","自以公相後，每懷宗国屯。","題诗庚子歲，自謂羲皇人。","手持山海經，头戴漉酒巾。","兴逐孤云外，心隨還鸟泯。"]', '诗', 'shi', '', NULL, '詠陶淵明 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49549441-a732-4154-a315-93be06c236ba', '三言擬五雜組二首 一', '三言擬五杂組二首 一', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["五雜組，繡與錦。","往復還，興又寢。","不得已，病伏枕。"]', '["五杂組，繡與錦。","往复還，兴又寢。","不得已，病伏枕。"]', '诗', 'shi', '', NULL, '三言擬五雜組二首 一 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9fc2bc-180d-4ddb-af8b-662b760d2a51', '三言擬五雜組二首 二', '三言擬五杂組二首 二', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["五雜組，甘鹹醋。","往復還，烏與兔。","不得已，韶光度。"]', '["五杂組，甘鹹醋。","往复還，烏與兔。","不得已，韶光度。"]', '诗', 'shi', '', NULL, '三言擬五雜組二首 二 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b842cbd-4e97-47ab-9823-19d3daba3add', '使過瑤臺寺有懷圓寂上人', '使過瑤台寺有懷圓寂上人', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["上人居此寺，不出三十年。","萬法元無著，一心唯趣禪。","忽紆塵外軫，遠訪區中緣。","及爾不復見，支提猶岌然。"]', '["上人居此寺，不出三十年。","万法元無著，一心唯趣禪。","忽紆塵外軫，远訪區中緣。","及爾不复见，支提猶岌然。"]', '诗', 'shi', '', NULL, '使過瑤臺寺有懷圓寂上人 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f3b97a9-7740-4508-ae92-ec4cdd1f0fd2', '登平望橋下作', '登平望橋下作', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["登橋試長望，望極與天平。","際海蒹葭色，終朝鳧鴈聲。","近山猶髣髴，遠水忽微明。","更覽諸公作，知高題柱名。"]', '["登橋試长望，望極與天平。","際海蒹葭色，終朝鳧鴈声。","近山猶髣髴，远水忽微明。","更覽諸公作，知高題柱名。"]', '诗', 'shi', '', NULL, '登平望橋下作 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff35f1c3-1423-40ce-9474-690d7a177fba', '刻清遠道士詩因而繼作', '刻清远道士诗因而繼作', '79f1eda7-aada-4077-9067-96198b1cca50', '唐', '["不到東西寺，于今五十春。","朅來從舊賞，林壑宛相親。","吳子多藏日，秦王厭勝辰。","劒池穿萬仞，盤石坐千人。","金氣騰爲虎，琴臺化若神。","登壇仰生一，捨宅歎珣珉。","中嶺分雙樹，迴巒絕四鄰。","窺臨江海接，崇飾四時新。","客有神仙者，於茲雅麗陳。","名高清遠峽，文聚斗牛津。","跡異心寧間，聲同質豈均。","悠然千載後，知我揖光塵。"]', '["不到东西寺，于今五十春。","朅来從旧賞，林壑宛相親。","吳子多藏日，秦王厭勝辰。","劒池穿万仞，盤石坐千人。","金氣腾爲虎，琴台化若神。","登壇仰生一，捨宅歎珣珉。","中嶺分雙樹，迴巒絕四鄰。","窺臨江海接，崇飾四时新。","客有神仙者，於茲雅丽陳。","名高清远峽，文聚斗牛津。","跡異心寧间，声同質豈均。","悠然千載後，知我揖光塵。"]', '诗', 'shi', '', NULL, '刻清遠道士詩因而繼作 顏真卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930b7864-749c-4dfb-bb67-d9362a5b127f', '雜詩六首 一', '杂诗六首 一', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["黃鍾扣元音，律呂更循環。","邪氣悖正聲，鄭衛生其間。","典樂忽涓微，波浪與天渾。","嘈嘈鴟梟動，好鳥徒緜蠻。","王吉歸鄉里，甘心長閉關。"]', '["黄鍾扣元音，律呂更循环。","邪氣悖正声，鄭衛生其间。","典乐忽涓微，波浪與天渾。","嘈嘈鴟梟动，好鸟徒緜蠻。","王吉归乡里，甘心长閉关。"]', '诗', 'shi', '', NULL, '雜詩六首 一 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('098954de-58f8-4d53-9ac6-68e96b4da5bc', '雜詩六首 二', '杂诗六首 二', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["玄黃與丹青，五氣之正色。","聖人端其源，上下皆有則。","齊侯好紫衣，魏帝婦人飾。","女奴厭金翠，傾海未滿臆。","何忍嚴子陵，羊裘死荆棘。"]', '["玄黄與丹青，五氣之正色。","聖人端其源，上下皆有則。","齊侯好紫衣，魏帝婦人飾。","女奴厭金翠，傾海未满臆。","何忍嚴子陵，羊裘死荆棘。"]', '诗', 'shi', '', NULL, '雜詩六首 二 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846e8c71-76a5-4b36-b956-dfd78de9fe52', '雜詩六首 三', '杂诗六首 三', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["甘酸不私人，元和運五行。","生人受其用，味正心亦平。","爪牙相踐傷，日與性命爭。","聖人不能絕，鑽燧與炮烹。","嗜慾乘此熾，百金資一傾。","正銷神耗衰，邪勝體充盈。","顏子有餘樂，瓢中寒水清。"]', '["甘酸不私人，元和運五行。","生人受其用，味正心亦平。","爪牙相踐傷，日與性命爭。","聖人不能絕，鑽燧與炮烹。","嗜慾乘此熾，百金資一傾。","正銷神耗衰，邪勝體充盈。","顏子有餘乐，瓢中寒水清。"]', '诗', 'shi', '', NULL, '雜詩六首 三 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('514a3560-e3b3-4c53-9a81-7b43013e5b55', '雜詩六首 四', '杂诗六首 四', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["陰魄淪宇宙，太陽假其明。","臣道不敢專，由此見虧盈。","未聞東菑稼，一氣嘉穀成。","上天降寒暑，地利乃可生。","葛藟附柔木，繁陰蔽曾原。","風霜摧枝幹，不復庇本根。","女蘿依松柏，然後得長存。"]', '["陰魄淪宇宙，太陽假其明。","臣道不敢專，由此见虧盈。","未闻东菑稼，一氣嘉穀成。","上天降寒暑，地利乃可生。","葛藟附柔木，繁陰蔽曾原。","风霜摧枝幹，不复庇本根。","女蘿依松柏，然後得长存。"]', '诗', 'shi', '', NULL, '雜詩六首 四 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1ac423-a541-4ae6-b229-3b668ca8933e', '雜詩六首 五', '杂诗六首 五', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["孔光尊董賢，胡廣慚李固。","儒風冠天下，而乃敗王度。","絳侯與愽陸，忠朴受遺顧。","求名不考實，文弊反成蠹。"]', '["孔光尊董賢，胡廣慚李固。","儒风冠天下，而乃敗王度。","絳侯與愽陸，忠朴受遺顧。","求名不考實，文弊反成蠹。"]', '诗', 'shi', '', NULL, '雜詩六首 五 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96d2e744-49f9-47c0-8e2a-98eb302c8010', '雜詩六首 六', '杂诗六首 六', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["結交得書生，書生鈍且直。","爭權復爭利，終不得其力。","我逢縱橫者，是我牙與翼。","相旋如疾風，竝命趨紫極。","奔車得停軌，風火何相逼。","仁義豈有常，肝膽反爲賊。","勿嫌書生直，鈍直深可憶。"]', '["結交得书生，书生鈍且直。","爭權复爭利，終不得其力。","我逢縱橫者，是我牙與翼。","相旋如疾风，竝命趨紫極。","奔车得停軌，风火何相逼。","仁義豈有常，肝膽反爲賊。","勿嫌书生直，鈍直深可憶。"]', '诗', 'shi', '', NULL, '雜詩六首 六 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd29f16-7699-416c-99c1-2889a86b1a08', '詠史十一首 一', '詠史十一首 一', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["昂藏獬豸獸，出自太平年。","亂代乃潛伏，縱人爲禍愆。","嘗聞斷馬劒，每壯朱雲賢。","身死名不滅，寒風吹[墓]田。","精靈如有在，幽憤滿松煙。"]', '["昂藏獬豸獸，出自太平年。","亂代乃潛伏，縱人爲禍愆。","嘗闻斷马劒，每壯朱云賢。","身死名不滅，寒风吹[墓]田。","精靈如有在，幽憤满松煙。"]', '诗', 'shi', '', NULL, '詠史十一首 一 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6fc679-0c7d-4a0d-bb00-0f267cbb2024', '詠史十一首 二', '詠史十一首 二', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["漢皇修雅樂，乘輿臨太學。","三老與五更，天王親割牲。","一人調風俗，萬國和且平。","單于驟款塞，武庫欲銷兵。","文物此朝盛，君臣何穆清。","至今壝壇下，如有簫韶聲。"]', '["漢皇修雅乐，乘輿臨太学。","三老與五更，天王親割牲。","一人調风俗，万国和且平。","單于驟款塞，武庫欲銷兵。","文物此朝盛，君臣何穆清。","至今壝壇下，如有簫韶声。"]', '诗', 'shi', '', NULL, '詠史十一首 二 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400e8b32-e77d-4aa8-a6d6-3cd536afe277', '詠史十一首 三', '詠史十一首 三', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["巢許在嵩潁，陶唐不得臣。","九州尚洗耳，一命安能親。","緜邈數千祀，丘中誰隱淪。","朝遊公卿府，夕是山林人。","蒲帛揚側陋，薜蘿爲縉紳。","九重念入夢，三事思降神。","且設庭中燎，寧窺泉下鱗。"]', '["巢許在嵩潁，陶唐不得臣。","九州尚洗耳，一命安能親。","緜邈數千祀，丘中誰隐淪。","朝游公卿府，夕是山林人。","蒲帛揚側陋，薜蘿爲縉紳。","九重念入梦，三事思降神。","且設庭中燎，寧窺泉下鱗。"]', '诗', 'shi', '', NULL, '詠史十一首 三 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1096f49c-cb1f-4321-9e8e-e608f69bec0c', '詠史十一首 四', '詠史十一首 四', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["漢時征百粵，楊僕將樓船。","幕府功未立，江湖已騷然。","島夷非敢亂，政暴地仍偏。","得罪因懷璧，防身輒控弦。","三軍求裂土，萬里詎聞天。","魏闕心猶在，旗門首已懸。","如何得良吏，一爲制方圓。"]', '["漢时征百粵，楊僕將楼船。","幕府功未立，江湖已騷然。","島夷非敢亂，政暴地仍偏。","得罪因懷璧，防身輒控弦。","三軍求裂土，万里詎闻天。","魏闕心猶在，旗门首已懸。","如何得良吏，一爲制方圓。"]', '诗', 'shi', '', NULL, '詠史十一首 四 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1291a9d-45de-4f6b-b26d-df8c1a511ec6', '詠史十一首 五', '詠史十一首 五', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["秦滅漢帝興，南山有遺老。","危冠揖萬乘，幸得厭征討。","當君逐鹿時，臣等已枯槁。","寧知市朝變，但覺林泉好。","高臥三十年，相看成四皓。","帝言翁甚善，見顧何不早。","咸稱太子仁，重義亦尊道。","側聞驪姬事，申生不自保。","暫出商山雲，朅來趨灑掃。","東宮成羽翼，楚舞傷懷抱。","後代無其人，戾園滿秋草。"]', '["秦滅漢帝兴，南山有遺老。","危冠揖万乘，幸得厭征討。","當君逐鹿时，臣等已枯槁。","寧知市朝变，但覺林泉好。","高臥三十年，相看成四皓。","帝言翁甚善，见顧何不早。","咸稱太子仁，重義亦尊道。","側闻驪姬事，申生不自保。","暫出商山云，朅来趨灑掃。","东宮成羽翼，楚舞傷懷抱。","後代無其人，戾园满秋草。"]', '诗', 'shi', '', NULL, '詠史十一首 五 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b07fa27-ac03-4a4a-a486-da0f236e280e', '詠史十一首 六', '詠史十一首 六', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["日照崑崙上，羽人披羽衣。","乘龍駕雲霧，欲往心無違。","此山在西北，乃是神仙國。","靈氣皆自然，求之不可得。","何爲漢武帝，精思徧羣山。","糜費巨萬計，宮車終不還。","蒼蒼茂陵樹，足以戒人間。"]', '["日照崑崙上，羽人披羽衣。","乘龙駕云霧，欲往心無違。","此山在西北，乃是神仙国。","靈氣皆自然，求之不可得。","何爲漢武帝，精思徧羣山。","糜費巨万計，宮车終不還。","蒼蒼茂陵樹，足以戒人间。"]', '诗', 'shi', '', NULL, '詠史十一首 六 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849a2d8e-b5c7-4b47-a662-fef1f4590356', '詠史十一首 七', '詠史十一首 七', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["天生忠與義，本以佐雍熙。","何意李司隸，而當昏亂時。","古墳襄城野，斜徑橫秋陂。","況不禁樵采，茅莎無孑遺。","高標尚可仰，精爽今何之。","一忤中常侍，銜冤誰見知。","嘗觀黨錮傳，撫卷不勝悲。"]', '["天生忠與義，本以佐雍熙。","何意李司隸，而當昏亂时。","古墳襄城野，斜徑橫秋陂。","況不禁樵采，茅莎無孑遺。","高標尚可仰，精爽今何之。","一忤中常侍，銜冤誰见知。","嘗观黨錮傳，撫卷不勝悲。"]', '诗', 'shi', '', NULL, '詠史十一首 七 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3026d9c2-2490-4302-829d-42c98b7f6845', '詠史十一首 八', '詠史十一首 八', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["文侯耽鄭衛，一聽一忘餐。","白雪燕姬舞，朱弦趙女彈。","淫聲流不返，慆蕩日無端。","獻歲受朝時，鳴鐘讌百官。","兩牀陳管磬，九奏殊未闌。","對此唯恐臥，更能整衣冠。"]', '["文侯耽鄭衛，一听一忘餐。","白雪燕姬舞，朱弦趙女彈。","淫声流不返，慆蕩日無端。","獻歲受朝时，鳴鐘讌百官。","兩牀陳管磬，九奏殊未闌。","对此唯恐臥，更能整衣冠。"]', '诗', 'shi', '', NULL, '詠史十一首 八 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bd5abc-cb8e-4326-8418-169ea68a008c', '詠史十一首 九', '詠史十一首 九', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["蜀主相諸葛，功高名亦尊。","驅馳千萬衆，怒目瞰中原。","曹伯任公孫，國亡身不存。","社宮久蕪沒，白鴈猶飛翻。","勿言君臣合，可以濟黎元。","爲蜀諒不易，如曹難復論。"]', '["蜀主相諸葛，功高名亦尊。","驱驰千万衆，怒目瞰中原。","曹伯任公孫，国亡身不存。","社宮久蕪沒，白鴈猶飞翻。","勿言君臣合，可以濟黎元。","爲蜀諒不易，如曹难复論。"]', '诗', 'shi', '', NULL, '詠史十一首 九 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd96c6b2-8e1e-44c5-989a-d1e8eda25d86', '詠史十一首 十', '詠史十一首 十', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["六國韓最弱，末年尤畏秦。","鄭生爲韓計，且欲疲秦人。","利物可分社，原情堪滅身。","咸陽古城下，萬頃稻苗新。"]', '["六国韓最弱，末年尤畏秦。","鄭生爲韓計，且欲疲秦人。","利物可分社，原情堪滅身。","咸陽古城下，万頃稻苗新。"]', '诗', 'shi', '', NULL, '詠史十一首 十 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa07344-86bd-4631-9cb9-70a506e52241', '詠史十一首 十一', '詠史十一首 十一', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["沂水春可涉，泮宮映楊葉。","麗色異人間，珊珊搖珮環。","展禽恆獨處，深巷生禾黍。","城上飛海雲，城中暗春雨。","適來鳴珮者，復是誰家女。","泥沾珠綴履，雨濕翠毛簪。","電影開蓮臉，雷聲飛蕙心。","自言沂水曲，采萍兼采菉。","歸逕雖可尋，天陰光景促。","憐君貞且獨，願許君家宿。","徒勞惜衾枕，了不顧雙蛾。","豔質誠可重，淫風如禮何。","周王惑襃姒，城闕成陂陁。"]', '["沂水春可涉，泮宮映楊葉。","丽色異人间，珊珊搖珮环。","展禽恆独处，深巷生禾黍。","城上飞海云，城中暗春雨。","適来鳴珮者，复是誰家女。","泥沾珠綴履，雨濕翠毛簪。","電影开蓮臉，雷声飞蕙心。","自言沂水曲，采萍兼采菉。","归逕雖可尋，天陰光景促。","怜君貞且独，願許君家宿。","徒勞惜衾枕，了不顧雙蛾。","豔質誠可重，淫风如禮何。","周王惑襃姒，城闕成陂陁。"]', '诗', 'shi', '', NULL, '詠史十一首 十一 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18dcf48-594b-4293-a324-ccd46562dae9', '雲母泉詩', '云母泉诗', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["晨登玄石嶺，嶺上寒松聲。","朗日風雨霽，高秋天地清。","山門開古寺，石竇含純精。","洞徹淨金界，夤緣流玉英。","澤藥滋畦茂，氣染茶甌馨。","飲液盡眉壽，飡和皆體平。","瓊漿駐容髮，甘露瑩心靈。","岱谷謝巧妙，匡山徒有名。","願言構蓬蓽，荷鍤引泠泠。","訪道出人世，招賢依福庭。","此心不能已，寤寐見吾兄。","曾結潁陽契，窮年無所成。","東西同放逐，蛇豕尚縱橫。","江漢阻攜手，天涯萬里情。","恩光起憔悴，西上謁承明。","秋色變江樹，相思紛以盈。","猨啼巴丘戍，月上武陵城。","共恨川路永，無由會友生。","雲泉不可忘，何日遂躬耕。"]', '["晨登玄石嶺，嶺上寒松声。","朗日风雨霽，高秋天地清。","山门开古寺，石竇含純精。","洞徹淨金界，夤緣流玉英。","澤藥滋畦茂，氣染茶甌馨。","饮液尽眉壽，飡和皆體平。","瓊漿駐容髮，甘露瑩心靈。","岱谷謝巧妙，匡山徒有名。","願言構蓬蓽，荷鍤引泠泠。","訪道出人世，招賢依福庭。","此心不能已，寤寐见吾兄。","曾結潁陽契，窮年無所成。","东西同放逐，蛇豕尚縱橫。","江漢阻携手，天涯万里情。","恩光起憔悴，西上謁承明。","秋色变江樹，相思紛以盈。","猨啼巴丘戍，月上武陵城。","共恨川路永，無由會友生。","云泉不可忘，何日遂躬耕。"]', '诗', 'shi', '', NULL, '雲母泉詩 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e898b27-d1ec-4ff1-95b8-0461e652b18a', '寄趙七侍御', '寄趙七侍御', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["搖槳曙江流，江清山復重。","心愜賞未足，川迥失前峰。","淩灘出極浦，曠若天池通。","君陽青嵯峨，開拆混元中。","九潭魚龍窟，仙成羽人宮。","陰奧潛鬼物，精光動煙空。","玄猨啼深蘢，白鳥戲葱蒙。","飛湍鳴金石，激溜鼓雷風。","雨濯萬木鮮，霞照千山濃。","草閑長餘綠，花靜落幽紅。","渚煙見晨釣，山月聞夜舂。","覆溪窈窕波，涵石淘溶溶。","丹丘忽聚散，素壁相奔衝。","白日破昏靄，靈山出其東。","勢排昊蒼上，氣壓吳越雄。","迴頭望雲卿，此恨發吾衷。","昔日蕭邵遊，四人纔成童。","屬詞慕孔門，入仕希上公。","緯卿陷非罪，折我昆吾鋒。","茂挺獨先覺，拔身渡京虹。","斯人謝明代，百代墜鵷鴻。","世故墜橫流，與君哀路窮。","相顧無死節，蒙恩逐殊封。","天波洗其瑕，朱衣備朝容。","一別凡十年，豈期復相從。","餘生得攜手，遺此兩孱翁。","羣遷失鶯羽，後凋惜長松。","衰旅難重別，悽悽滿心胸。","遇勝悲獨遊，貪奇悵孤逢。","禽尚彼何人，胡爲束樊籠。","吾師度門教，投弁躡遐蹤。"]', '["搖槳曙江流，江清山复重。","心愜賞未足，川迥失前峰。","淩灘出極浦，曠若天池通。","君陽青嵯峨，开拆混元中。","九潭鱼龙窟，仙成羽人宮。","陰奧潛鬼物，精光动煙空。","玄猨啼深蘢，白鸟戲葱蒙。","飞湍鳴金石，激溜鼓雷风。","雨濯万木鲜，霞照千山濃。","草闲长餘綠，花静落幽紅。","渚煙见晨釣，山月闻夜舂。","覆溪窈窕波，涵石淘溶溶。","丹丘忽聚散，素壁相奔衝。","白日破昏靄，靈山出其东。","勢排昊蒼上，氣壓吳越雄。","迴头望云卿，此恨發吾衷。","昔日蕭邵游，四人纔成童。","屬词慕孔门，入仕希上公。","緯卿陷非罪，折我昆吾鋒。","茂挺独先覺，拔身渡京虹。","斯人謝明代，百代墜鵷鴻。","世故墜橫流，與君哀路窮。","相顧無死節，蒙恩逐殊封。","天波洗其瑕，朱衣備朝容。","一別凡十年，豈期复相從。","餘生得携手，遺此兩孱翁。","羣遷失鶯羽，後凋惜长松。","衰旅难重別，悽悽满心胸。","遇勝悲独游，貪奇悵孤逢。","禽尚彼何人，胡爲束樊籠。","吾師度门教，投弁躡遐蹤。"]', '诗', 'shi', '', NULL, '寄趙七侍御 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69cda70d-9494-4392-b189-2cbb39e2ba69', '仙遊寺', '仙游寺', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["捨事入樵逕，雲木深谷口。","萬壑移晦明，千峰轉前後。","嶷然龍潭上，石勢若奔走。","開拆秋天光，崩騰夏雷吼。","靈谿自茲去，紆直互紛糾。","聽聲靜復喧，望色無更有。","冥冥翠微下，高殿映杉柳。","滴滴洞穴中，懸泉響相扣。","昔時秦王女，羽化年代久。","日暮松風來，簫聲生左右。","早窺神仙籙，願結芝朮友。","安得羨門方，青囊繫吾肘。"]', '["捨事入樵逕，云木深谷口。","万壑移晦明，千峰轉前後。","嶷然龙潭上，石勢若奔走。","开拆秋天光，崩腾夏雷吼。","靈谿自茲去，紆直互紛糾。","听声静复喧，望色無更有。","冥冥翠微下，高殿映杉柳。","滴滴洞穴中，懸泉响相扣。","昔时秦王女，羽化年代久。","日暮松风来，簫声生左右。","早窺神仙籙，願結芝朮友。","安得羨门方，青囊繫吾肘。"]', '诗', 'shi', '', NULL, '仙遊寺 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de5c1eb6-0200-41ee-8db9-cf66ffde46bb', '春遊吟', '春游吟', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["初春遍芳甸，千里藹盈矚。","美人摘新英，步步翫春綠。","所思杳何處，宛在吳江曲。","可憐不得共芳菲，日暮歸來淚滿衣。"]', '["初春遍芳甸，千里藹盈矚。","美人摘新英，步步翫春綠。","所思杳何处，宛在吳江曲。","可怜不得共芳菲，日暮归来泪满衣。"]', '诗', 'shi', '', NULL, '春遊吟 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179a6adb-d7a7-48c7-a629-98f6fc151235', '長門怨', '长门怨', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["弱體鴛鴦薦，啼妝翡翠衾。","鴉鳴秋殿曉，人靜禁門深。","每憶椒房寵，那堪永巷陰。","自驚羅帶緩，非復舊來心。"]', '["弱體鴛鴦薦，啼妝翡翠衾。","鴉鳴秋殿晓，人静禁门深。","每憶椒房寵，那堪永巷陰。","自驚羅带緩，非复旧来心。"]', '诗', 'shi', '', NULL, '長門怨 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c338f61-1381-4fb0-be26-3973b70c3065', '奉使朔方贈郭都護', '奉使朔方贈郭都護', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["絕塞臨光祿，孤營佐貳師。","鐵衣山月冷，金鼓朔風悲。","都護徵兵日，將軍破虜時。","揚鞭玉關道，回首望旌旗。"]', '["絕塞臨光祿，孤營佐貳師。","鐵衣山月冷，金鼓朔风悲。","都護徵兵日，將軍破虜时。","揚鞭玉关道，回首望旌旗。"]', '诗', 'shi', '', NULL, '奉使朔方贈郭都護 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cddacbb0-624e-498c-b134-e2260dfc45d6', '尚書都堂瓦松', '尚书都堂瓦松', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["華省祕仙蹤，高堂露瓦松。","葉因春後長，花爲雨來濃。","影混鴛鴦色，光含翡翠容。","天然斯所寄，地勢太無從。","接棟臨雙闕，連甍近九重。","寧知深澗底，霜雪歲兼封。"]', '["华省祕仙蹤，高堂露瓦松。","葉因春後长，花爲雨来濃。","影混鴛鴦色，光含翡翠容。","天然斯所寄，地勢太無從。","接棟臨雙闕，連甍近九重。","寧知深澗底，霜雪歲兼封。"]', '诗', 'shi', '', NULL, '尚書都堂瓦松 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8810763-ae84-41aa-9dd7-fff0f5081624', '海上生明月', '海上生明月', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["皎皎秋中月，團團海上生。","影開金鏡滿，輪抱玉壺清。","漸出三山岊，將凌一漢橫。","素娥嘗藥去，烏鵲遶枝驚。","照水光偏白，浮雲色最明。","此時堯砌下，蓂莢自將榮。"]', '["皎皎秋中月，團團海上生。","影开金镜满，輪抱玉壺清。","漸出三山岊，將凌一漢橫。","素娥嘗藥去，烏鵲遶枝驚。","照水光偏白，浮云色最明。","此时堯砌下，蓂莢自將榮。"]', '诗', 'shi', '', NULL, '海上生明月 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c320cbaa-89ab-4ef7-8096-9e736a8347f8', '晚日湖上寄所思', '晚日湖上寄所思', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["與君爲近別，不啻遠相思。","落日平湖上，看山對此時。"]', '["與君爲近別，不啻远相思。","落日平湖上，看山对此时。"]', '诗', 'shi', '', NULL, '晚日湖上寄所思 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f010433e-6ddd-4be5-a98b-4119038bb7df', '寄從弟', '寄從弟', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["眼病身亦病，浮生已半空。","迢迢千里月，應與惠連同。"]', '["眼病身亦病，浮生已半空。","迢迢千里月，應與惠連同。"]', '诗', 'shi', '', NULL, '寄從弟 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020e67e0-f7b4-4f36-8277-004b92ea77af', '奉寄彭城公', '奉寄彭城公', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["公子三千客，人人願報恩。","應憐抱關者，貧病老夷門。"]', '["公子三千客，人人願報恩。","應怜抱关者，貧病老夷门。"]', '诗', 'shi', '', NULL, '奉寄彭城公 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed8f172-406c-40a5-ae5d-0b1c2290eca6', '春行寄興', '春行寄兴', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["宜陽城下草萋萋，澗水東流復向西。","芳樹無人花自落，春山一路鳥空啼。"]', '["宜陽城下草萋萋，澗水东流复向西。","芳樹無人花自落，春山一路鸟空啼。"]', '诗', 'shi', '', NULL, '春行寄興 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94d61054-d280-46a9-8894-bf068aa0a900', '江有楓一篇十章 一', '江有楓一篇十章 一', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["江有楓，其葉蒙蒙。","我友自東，于以遊從。"]', '["江有楓，其葉蒙蒙。","我友自东，于以游從。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 一 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85868ac-6915-478d-9b8f-75f3f8254654', '江有楓一篇十章 二', '江有楓一篇十章 二', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["山有槭，其葉漠漠。","我友徂北，于以休息。"]', '["山有槭，其葉漠漠。","我友徂北，于以休息。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 二 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b7e90e0-426e-4f88-9d65-bfed619cf8ea', '江有楓一篇十章 三', '江有楓一篇十章 三', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["想彼槭矣，亦類其楓。","矧伊懷人，而忘其東。"]', '["想彼槭矣，亦類其楓。","矧伊懷人，而忘其东。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 三 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b20402c-4823-4330-b54d-88147a1a3fc5', '江有楓一篇十章 四', '江有楓一篇十章 四', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["東可遊矣，會之丘矣。","于山于水，于廟于寺。","于亭于里，君子遊焉。","于以宴喜，其樂亹亹。"]', '["东可游矣，會之丘矣。","于山于水，于廟于寺。","于亭于里，君子游焉。","于以宴喜，其乐亹亹。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 四 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb047209-77a1-44d4-9690-a6ba5a8f52e2', '江有楓一篇十章 五', '江有楓一篇十章 五', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["粵東可居，彼吳之墟。","有田有庭，有朋有書。","有蓴有魚，君子居焉。","惟以宴醑，其樂徐徐。"]', '["粵东可居，彼吳之墟。","有田有庭，有朋有书。","有蓴有鱼，君子居焉。","惟以宴醑，其乐徐徐。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 五 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa986a33-2414-4c5a-894a-1312bf0d1a4b', '江有楓一篇十章 六', '江有楓一篇十章 六', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["我朋在矣，彼陸之子。","如松如杞，淑問不已。"]', '["我朋在矣，彼陸之子。","如松如杞，淑问不已。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 六 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0575edd-5f4e-4a8e-9323-6c352f9b4a47', '江有楓一篇十章 七', '江有楓一篇十章 七', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["我友于征，彼鄭之子。","如琇如英，德音孔明。"]', '["我友于征，彼鄭之子。","如琇如英，德音孔明。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 七 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db51f017-bb54-4054-a9c9-7ab2c42303d5', '江有楓一篇十章 八', '江有楓一篇十章 八', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["我思震澤，菱芡幕幕。","寤寐如覿，我思剡谿。","杉篠萋萋，寤寐無迷。"]', '["我思震澤，菱芡幕幕。","寤寐如覿，我思剡谿。","杉篠萋萋，寤寐無迷。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 八 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0223b12b-6e1b-47bd-a8ab-3ba123bcf93b', '江有楓一篇十章 九', '江有楓一篇十章 九', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["有鳥有鳥，粵鷗與鷺。","浮湍戲渚，皓然潔素。","忘其猜妒，彼何人斯，曾足傷懼。"]', '["有鸟有鸟，粵鷗與鷺。","浮湍戲渚，皓然潔素。","忘其猜妒，彼何人斯，曾足傷懼。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 九 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dac1225-1872-4da4-a929-44f28900bd98', '江有楓一篇十章 十', '江有楓一篇十章 十', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["此懼惟何，懼寘于羅。","彼驕者子，讒言孔多。","我聞先師，體命委和。","公伯之愬，則如予何。","悵然山河，惟以嘯歌，其憂也哉。"]', '["此懼惟何，懼寘于羅。","彼驕者子，讒言孔多。","我闻先師，體命委和。","公伯之愬，則如予何。","悵然山河，惟以嘯歌，其憂也哉。"]', '诗', 'shi', '', NULL, '江有楓一篇十章 十 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82974f04-09c3-493b-8e4d-5d8cf5a6b610', '菊榮一篇五章 一', '菊榮一篇五章 一', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["采采者菊，芬其榮斯。","紫英黃萼，照灼丹墀。","愷悌君子，佩服攸宜。","王國是維，大君是毗。","貽爾子孫，百祿萃之。"]', '["采采者菊，芬其榮斯。","紫英黄萼，照灼丹墀。","愷悌君子，佩服攸宜。","王国是維，大君是毗。","貽爾子孫，百祿萃之。"]', '诗', 'shi', '', NULL, '菊榮一篇五章 一 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf843715-ea79-469b-adec-c14de2346d5d', '菊榮一篇五章 二', '菊榮一篇五章 二', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["采采者菊，于邑之城。","舊根新莖，布葉垂英。","彼美淑人，應家之禎。","有弦既鳴，我政則平。","宜爾棟崇，必復其慶。"]', '["采采者菊，于邑之城。","旧根新莖，布葉垂英。","彼美淑人，應家之禎。","有弦既鳴，我政則平。","宜爾棟崇，必复其慶。"]', '诗', 'shi', '', NULL, '菊榮一篇五章 二 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27cd298-6c2d-4bf0-a54c-140104265ce1', '菊榮一篇五章 三', '菊榮一篇五章 三', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["采采者菊，于邦之府。","陰槐翳柳，邇楹近宇。","彼勞者子，喧卑是處。","慨其莫知，蘊結誰語。","企彼高人，色斯遐舉。"]', '["采采者菊，于邦之府。","陰槐翳柳，邇楹近宇。","彼勞者子，喧卑是处。","慨其莫知，蘊結誰語。","企彼高人，色斯遐舉。"]', '诗', 'shi', '', NULL, '菊榮一篇五章 三 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df762f3-0519-4321-979b-867871f44371', '菊榮一篇五章 四', '菊榮一篇五章 四', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["采采者菊，于賓之館。","既低其枝，又弱其幹。","有斐君子，是焉披翫。","良辰旨酒，宴飲無算。","愴其仳別，終然永歎。"]', '["采采者菊，于賓之館。","既低其枝，又弱其幹。","有斐君子，是焉披翫。","良辰旨酒，宴饮無算。","愴其仳別，終然永歎。"]', '诗', 'shi', '', NULL, '菊榮一篇五章 四 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2900bc66-bc71-44b6-99b4-8f65afe92fbe', '菊榮一篇五章 五', '菊榮一篇五章 五', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["歲方晏矣，霜露殘促。","誰其榮斯，有英者菊。","豈微春華，懿此貞色。","人之侮我，混于薪棘。","詩人有言，好是正直。"]', '["歲方晏矣，霜露殘促。","誰其榮斯，有英者菊。","豈微春华，懿此貞色。","人之侮我，混于薪棘。","诗人有言，好是正直。"]', '诗', 'shi', '', NULL, '菊榮一篇五章 五 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6993739-4600-4f15-9835-c784f432ba0b', '涼雨一章', '涼雨一章', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["習習涼風，泠泠浮飆。","君子樂胥，于其賓僚。","有女斯夭，式歌且謠。","欲言終宥，惟以招邀，于胥樂兮。"]', '["習習涼风，泠泠浮飆。","君子乐胥，于其賓僚。","有女斯夭，式歌且謠。","欲言終宥，惟以招邀，于胥乐兮。"]', '诗', 'shi', '', NULL, '涼雨一章 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3181e8d5-a187-4328-97b1-189ddedfa2af', '有竹一篇七章', '有竹一篇七章', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["有竹斯竿，于閣之前。","君子秉心，惟其貞堅兮。","有竿斯竹，于閣之側。","君子秉操，惟其正直兮。","彼蔚者竹，蕭其森矣。","有開者閤，宛其深矣。","迴簷幽砌，如翼如齒。","冬之霄，霰雪斯瀌。","我有金鑪，熺其以歊。","夏之日，炎景斯鬱。","我有珍簟，淒其以栗。","彼紛者務，體其豫矣。","有旨者酒，歡其且矣。","友僚萃止，跗蕚載韡。","彼美公之姓兮，那歟應積慶兮，期子惟去之柄兮。"]', '["有竹斯竿，于閣之前。","君子秉心，惟其貞堅兮。","有竿斯竹，于閣之側。","君子秉操，惟其正直兮。","彼蔚者竹，蕭其森矣。","有开者閤，宛其深矣。","迴簷幽砌，如翼如齒。","冬之霄，霰雪斯瀌。","我有金鑪，熺其以歊。","夏之日，炎景斯鬱。","我有珍簟，淒其以栗。","彼紛者務，體其豫矣。","有旨者酒，歡其且矣。","友僚萃止，跗蕚載韡。","彼美公之姓兮，那歟應積慶兮，期子惟去之柄兮。"]', '诗', 'shi', '', NULL, '有竹一篇七章 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56232b75-2409-4b3c-a341-cc2f668f69a9', '有竹一篇七章 一', '有竹一篇七章 一', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["有竹斯竿，于閣之前。","君子秉心，惟其貞堅兮。"]', '["有竹斯竿，于閣之前。","君子秉心，惟其貞堅兮。"]', '诗', 'shi', '', NULL, '有竹一篇七章 一 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c792590a-599f-46cf-b882-5b504c95cebf', '有竹一篇七章 二', '有竹一篇七章 二', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["有竿斯竹，于閣之側。","君子秉操，惟其正直兮。"]', '["有竿斯竹，于閣之側。","君子秉操，惟其正直兮。"]', '诗', 'shi', '', NULL, '有竹一篇七章 二 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccb49f44-0495-4a5a-be73-a31997b47a42', '有竹一篇七章 三', '有竹一篇七章 三', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["彼蔚者竹，蕭其森矣。","有開者閤，宛其深矣。","迴簷幽砌，如翼如齒。"]', '["彼蔚者竹，蕭其森矣。","有开者閤，宛其深矣。","迴簷幽砌，如翼如齒。"]', '诗', 'shi', '', NULL, '有竹一篇七章 三 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf76dcf-0833-42df-bb98-3d02e628d72b', '有竹一篇七章 四', '有竹一篇七章 四', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["冬之霄，霰雪斯瀌。","我有金鑪，熺其以歊。"]', '["冬之霄，霰雪斯瀌。","我有金鑪，熺其以歊。"]', '诗', 'shi', '', NULL, '有竹一篇七章 四 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2790fed0-2956-4a02-8973-83a3325efb2c', '有竹一篇七章 五', '有竹一篇七章 五', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["夏之日，炎景斯鬱。","我有珍簟，淒其以栗。"]', '["夏之日，炎景斯鬱。","我有珍簟，淒其以栗。"]', '诗', 'shi', '', NULL, '有竹一篇七章 五 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eac2430-c28d-4873-b13f-60de470ee779', '有竹一篇七章 六', '有竹一篇七章 六', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["彼紛者務，體其豫矣。","有旨者酒，歡其且矣。","友僚萃止，跗蕚載韡。"]', '["彼紛者務，體其豫矣。","有旨者酒，歡其且矣。","友僚萃止，跗蕚載韡。"]', '诗', 'shi', '', NULL, '有竹一篇七章 六 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228cb24a-d906-4365-a3e7-6958711dc087', '有竹一篇七章 七', '有竹一篇七章 七', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["彼美公之姓兮，那歟應積慶兮，期子惟去之柄兮。"]', '["彼美公之姓兮，那歟應積慶兮，期子惟去之柄兮。"]', '诗', 'shi', '', NULL, '有竹一篇七章 七 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40557e94-3c29-4668-b046-bbc15e2fe71e', '江有歸舟三章 一', '江有归舟三章 一', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["江有歸舟，亦亂其流。","之子言旋，嘉名孔修。","揚于王庭，允焯其休。"]', '["江有归舟，亦亂其流。","之子言旋，嘉名孔修。","揚于王庭，允焯其休。"]', '诗', 'shi', '', NULL, '江有歸舟三章 一 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb1ba66d-3252-4b58-b68b-5f516b270406', '江有歸舟三章 二', '江有归舟三章 二', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["舟既歸止，人亦榮止。","兄矣弟矣，孝斯踐矣。","稱觴燕喜，于岵于屺。"]', '["舟既归止，人亦榮止。","兄矣弟矣，孝斯踐矣。","稱觴燕喜，于岵于屺。"]', '诗', 'shi', '', NULL, '江有歸舟三章 二 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d94ef38b-0534-4c03-adbd-1c7b931ee610', '江有歸舟三章 三', '江有归舟三章 三', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["彼遊惟帆，匪風不揚。","有彬伊父，匪學不彰。","予其懷而，勉爾無忘。"]', '["彼游惟帆，匪风不揚。","有彬伊父，匪学不彰。","予其懷而，勉爾無忘。"]', '诗', 'shi', '', NULL, '江有歸舟三章 三 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47e3ff1-8601-4476-becb-b51b7f233003', '過河濱和文學張志尹', '過河濱和文学張志尹', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["隆古日以遠，舉世喪其淳。","慷慨懷黃虞，化理何由臻。","步出城西門，裴回見河濱。","當其側陋時，河水清且潾。","滄桑一以變，莽然翳荆榛。","至化無苦窳，宇宙將陶甄。","太息感悲泉，人往跡未湮。","瑟瑟寒原暮，冷風吹衣巾。","顧我譾劣質，希聖杳無因。","且盡登臨意，斗酒歡相親。"]', '["隆古日以远，舉世喪其淳。","慷慨懷黄虞，化理何由臻。","步出城西门，裴回见河濱。","當其側陋时，河水清且潾。","滄桑一以变，莽然翳荆榛。","至化無苦窳，宇宙將陶甄。","太息感悲泉，人往跡未湮。","瑟瑟寒原暮，冷风吹衣巾。","顧我譾劣質，希聖杳無因。","且尽登臨意，斗酒歡相親。"]', '诗', 'shi', '', NULL, '過河濱和文學張志尹 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de48ce53-1660-45f3-9281-fc8b1cceeb74', '舟中遇陸棣兄西歸數日得廣陵二三子書知遲晚次沙墊西岸作', '舟中遇陸棣兄西归數日得廣陵二三子书知遲晚次沙墊西岸作', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["林烏遙岸鳴，早知東方曙。","波上風雨歇，舟人叫將去。","蒼蒼前洲日，的的回沙鷺。","水氣清曉陰，灘聲隱川霧。","舊山勞魂想，憶人阻洄泝。","信宿千里餘，佳期曷由遇。","前程入楚鄉，弭棹問維揚。","但見土音異，始知程路長。","寥寥晚空靜，漫漫風淮涼。","雲景信可美，風潮殊未央。","故人江臯上，永日念容光。","中路枉尺書，謂余瓊樹芳。","深期結晤語，竟夕恨相望。","冀願崇朝霽，吾其一葦航。"]', '["林烏遙岸鳴，早知东方曙。","波上风雨歇，舟人叫將去。","蒼蒼前洲日，的的回沙鷺。","水氣清晓陰，灘声隐川霧。","旧山勞魂想，憶人阻洄泝。","信宿千里餘，佳期曷由遇。","前程入楚乡，弭棹问維揚。","但见土音異，始知程路长。","寥寥晚空静，漫漫风淮涼。","云景信可美，风潮殊未央。","故人江臯上，永日念容光。","中路枉尺书，謂余瓊樹芳。","深期結晤語，竟夕恨相望。","冀願崇朝霽，吾其一葦航。"]', '诗', 'shi', '', NULL, '舟中遇陸棣兄西歸數日得廣陵二三子書知遲晚次沙墊西岸作 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29c83696-8b87-47dc-841c-4c6f790b10c0', '重陽日陪元魯山德秀登北城矚對新霽因以贈別', '重陽日陪元魯山德秀登北城矚对新霽因以贈別', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["山縣遶古堞，悠悠快登望。","雨餘秋天高，目盡無隱狀。","綿連滍川迴，杳渺鴉路深。","彭澤興不淺，臨風動歸心。","賴茲琴堂暇，傲睨傾菊酒。","人和歲已登，從政復何有。","遠山十里碧，一道銜長雲。","青霞半落日，混合疑晴曛。","漸聞驚栖羽，坐歎清夜月。","中歡愴有違，行子念明發。","僅能泯寵辱，未免傷別離。","江湖不可忘，風雨勞相思。","明時當盛才，短伎安所設。","何日謝百里，從君漢之澨。"]', '["山縣遶古堞，悠悠快登望。","雨餘秋天高，目尽無隐狀。","綿連滍川迴，杳渺鴉路深。","彭澤兴不淺，臨风动归心。","賴茲琴堂暇，傲睨傾菊酒。","人和歲已登，從政复何有。","远山十里碧，一道銜长云。","青霞半落日，混合疑晴曛。","漸闻驚栖羽，坐歎清夜月。","中歡愴有違，行子念明發。","僅能泯寵辱，未免傷別離。","江湖不可忘，风雨勞相思。","明时當盛才，短伎安所設。","何日謝百里，從君漢之澨。"]', '诗', 'shi', '', NULL, '重陽日陪元魯山德秀登北城矚對新霽因以贈別 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14cd929a-3532-4d36-a2d1-17f3cc1cf24f', '留別二三子得韻字', '留別二三子得韻字', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["二紀尚雌伏，徒然忝先進。","英英爾衆賢，名實鬱雙振。","殘春惜將別，清洛行不近。","相與愛後時，無令孤逸韻。"]', '["二紀尚雌伏，徒然忝先進。","英英爾衆賢，名實鬱雙振。","殘春惜將別，清洛行不近。","相與愛後时，無令孤逸韻。"]', '诗', 'shi', '', NULL, '留別二三子得韻字 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34deac87-ef32-4def-88ba-c28428ea91c5', '仰荅韋司業垂訪五首 一', '仰荅韋司業垂訪五首 一', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["呦呦食苹鹿，常飲清泠川。","但悅豐草美，寧知牢饌鮮。","主人有幽意，將以充林泉。","羅網幸免傷，蒙君復羈牽。","高堂列衆賓，廣座鳴清絃。","俯仰轉驚惕，裴回獨憂煎。","緬懷雲巖路，欲往無由緣。","物各有所好，違之傷自然。"]', '["呦呦食苹鹿，常饮清泠川。","但悅豐草美，寧知牢饌鲜。","主人有幽意，將以充林泉。","羅網幸免傷，蒙君复羈牽。","高堂列衆賓，廣座鳴清絃。","俯仰轉驚惕，裴回独憂煎。","緬懷云巖路，欲往無由緣。","物各有所好，違之傷自然。"]', '诗', 'shi', '', NULL, '仰荅韋司業垂訪五首 一 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c99a08-18ed-4cf7-9760-9c90b11ba950', '仰荅韋司業垂訪五首 二', '仰荅韋司業垂訪五首 二', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["神龜在南國，緬邈湘川陰。","遊止蓮葉上，歲時嘉樹林。","毒蟲且不近，斤斧何由尋。","錯落負奇文，熒煌耀丹金。","江山萬里餘，淮海阻且深。","獨保貞素質，不爲寒暑侵。","一逢盛明代，應見通靈心。"]', '["神龟在南国，緬邈湘川陰。","游止蓮葉上，歲时嘉樹林。","毒蟲且不近，斤斧何由尋。","錯落負奇文，熒煌耀丹金。","江山万里餘，淮海阻且深。","独保貞素質，不爲寒暑侵。","一逢盛明代，應见通靈心。"]', '诗', 'shi', '', NULL, '仰荅韋司業垂訪五首 二 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9bf909f-abbd-4fa8-b14b-8ace03c17a0c', '仰荅韋司業垂訪五首 三', '仰荅韋司業垂訪五首 三', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["晉代有儒臣，當年富詞藻。","立言寄青史，將以贊王道。","遼落緬歲時，辛勤歷江島。","且言風波倦，探涉豈爲寶。","不遇庾征西，云誰展懷抱。","士貧乏知己，安得成所好。"]', '["晉代有儒臣，當年富词藻。","立言寄青史，將以贊王道。","遼落緬歲时，辛勤歷江島。","且言风波倦，探涉豈爲寶。","不遇庾征西，云誰展懷抱。","士貧乏知己，安得成所好。"]', '诗', 'shi', '', NULL, '仰荅韋司業垂訪五首 三 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2000eb66-9670-4e20-b8a0-f7ab308108b2', '仰荅韋司業垂訪五首 四', '仰荅韋司業垂訪五首 四', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["彭陽昔遊說，願謁南郢都。","王果尚未達，況從夷節謨。","豈知晉叔向，無罪嬰囚拘。","臨難俟解紛，獨知[祁]大夫。","舉讐且不棄，何必論親疎。","夫子覺者也，其能遺我乎。"]', '["彭陽昔游说，願謁南郢都。","王果尚未達，況從夷節謨。","豈知晉叔向，無罪嬰囚拘。","臨难俟解紛，独知[祁]大夫。","舉讐且不棄，何必論親疎。","夫子覺者也，其能遺我乎。"]', '诗', 'shi', '', NULL, '仰荅韋司業垂訪五首 四 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfbd201-1374-47b5-99a5-8fb5a95a2ea3', '仰荅韋司業垂訪五首 五', '仰荅韋司業垂訪五首 五', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["關西一公子，年貌獨青春。","被褐來上京，翳然聲未振。","中郎何爲者，倒屣驚座賓。","詞賦豈不佳，盛名亦相因。","爲君奏此曲，此曲多苦辛。","千載不可誣，孰言今無人。"]', '["关西一公子，年貌独青春。","被褐来上京，翳然声未振。","中郎何爲者，倒屣驚座賓。","词賦豈不佳，盛名亦相因。","爲君奏此曲，此曲多苦辛。","千載不可誣，孰言今無人。"]', '诗', 'shi', '', NULL, '仰荅韋司業垂訪五首 五 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891222e7-ee6e-4881-97a2-c31055317363', '答鄒象先', '答鄒象先', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["桂枝常共擢，茅茨冀同薦。","一命何阻脩，載馳各川縣。","壯圖悲歲月，明代恥貧賤。","回首無津梁，祗令二毛變。"]', '["桂枝常共擢，茅茨冀同薦。","一命何阻脩，載驰各川縣。","壯圖悲歲月，明代恥貧賤。","回首無津梁，祗令二毛变。"]', '诗', 'shi', '', NULL, '答鄒象先 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37cd5393-d24a-426a-9c53-a774251bd650', '蒙山作', '蒙山作', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["東蒙鎮海沂，合沓餘百里。","清秋淨氛靄，崖崿隱天起。","于役勞往還，息徒暫攀躋。","將窮絕迹處，偶得冥心理。","雲氣雜虹霓，松聲亂風水。","微明綠林際，杳窱丹洞裏。","仙鳥時可聞，羽人邈難視。","此焉多深邃，賢達昔所止。","子尚捐俗紛，季隨躡遐軌。","蘊真道彌曠，懷古情未已。","白鹿凡幾遊，黃精復奚似。","顧予尚牽纏，家業重書史。","少學務從師，壯年貴趨仕。","方馳桂林譽，未暇桃源美。","歲暮期再尋，幽哉羨門子。"]', '["东蒙鎮海沂，合沓餘百里。","清秋淨氛靄，崖崿隐天起。","于役勞往還，息徒暫攀躋。","將窮絕迹处，偶得冥心理。","云氣杂虹霓，松声亂风水。","微明綠林際，杳窱丹洞裏。","仙鸟时可闻，羽人邈难視。","此焉多深邃，賢達昔所止。","子尚捐俗紛，季隨躡遐軌。","蘊真道彌曠，懷古情未已。","白鹿凡幾游，黄精复奚似。","顧予尚牽纏，家業重书史。","少学務從師，壯年貴趨仕。","方驰桂林譽，未暇桃源美。","歲暮期再尋，幽哉羨门子。"]', '诗', 'shi', '', NULL, '蒙山作 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fe9c185-de0e-40f6-a3a2-27fa03cb0ac8', '早春過七嶺寄題硤石裴丞廳壁', '早春過七嶺寄題硤石裴丞廳壁', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["出硤寄趣少，晚行偏憶君。","依然向來處，官路谿邊雲。","茲路豈不劇，能無俗累紛。","槐陰永未合，泉聲細猶聞。","彌歎春罷酒，牽卑從此分。","登高望城入，斜影半風薰。"]', '["出硤寄趣少，晚行偏憶君。","依然向来处，官路谿邊云。","茲路豈不劇，能無俗累紛。","槐陰永未合，泉声細猶闻。","彌歎春罷酒，牽卑從此分。","登高望城入，斜影半风薰。"]', '诗', 'shi', '', NULL, '早春過七嶺寄題硤石裴丞廳壁 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43299da8-2c0d-499a-8dfd-913f3e01d0d2', '送張翬下第歸江東', '送張翬下第归江东', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["俱飛仍失路，綵服邇清波。","地積東南美，朝遺甲乙科。","客愁千里別，春色五湖多。","明日舊山去，其如相望何。"]', '["俱飞仍失路，綵服邇清波。","地積东南美，朝遺甲乙科。","客愁千里別，春色五湖多。","明日旧山去，其如相望何。"]', '诗', 'shi', '', NULL, '送張翬下第歸江東 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c80ee4-da68-4098-8ac1-403819eae07d', '越江秋曙', '越江秋曙', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["扁舟東路遠，曉月下江濆。","瀲灩信潮上，蒼茫孤嶼分。","林聲寒動葉，水氣曙連雲。","暾日浪中出，榜歌天際聞。","伯鸞常去國，安道惜離羣。","延首剡谿近，詠言懷數君。"]', '["扁舟东路远，晓月下江濆。","瀲灩信潮上，蒼茫孤嶼分。","林声寒动葉，水氣曙連云。","暾日浪中出，榜歌天際闻。","伯鸾常去国，安道惜離羣。","延首剡谿近，詠言懷數君。"]', '诗', 'shi', '', NULL, '越江秋曙 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c00e43d-6a89-435a-9be6-f0420b615698', '山莊月夜作', '山莊月夜作', '4904bf36-5948-4623-9754-9fbd5bdd0b8f', '唐', '["獻書嗟棄置，疲拙歸田園。","且事計然策，將符公冶言。","桑榆清暮景，雞犬應遙村。","蠶罷里閭晏，麥秋田野喧。","澗聲連枕簟，峯勢入階軒。","未奏東山妓，先傾北海尊。","隴瓜香早熟，庭果落初繁。","更愜野人意，農談朝竟昏。"]', '["獻书嗟棄置，疲拙归田园。","且事計然策，將符公冶言。","桑榆清暮景，雞犬應遙村。","蠶罷里閭晏，麦秋田野喧。","澗声連枕簟，峯勢入階軒。","未奏东山妓，先傾北海尊。","隴瓜香早熟，庭果落初繁。","更愜野人意，農談朝竟昏。"]', '诗', 'shi', '', NULL, '山莊月夜作 蕭穎士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5b68e17-6380-472f-8ab4-553d2ac9d2bc', '古意', '古意', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["綠筍總成竹，紅花亦成子。","能當此時好，獨自幽閨裏。","夜夜苦更長，愁來不如死。"]', '["綠筍總成竹，紅花亦成子。","能當此时好，独自幽閨裏。","夜夜苦更长，愁来不如死。"]', '诗', 'shi', '', NULL, '古意 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f4fd23-1f91-4da9-88ef-785b1690dc80', '宿大通和尚塔敬贈如上人兼呈常孫二山人', '宿大通和尚塔敬贈如上人兼呈常孫二山人', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["支公已寂滅，影塔山上古。","更有真僧來，道場救諸苦。","一承微妙法，寓宿清淨土。","身心能自觀，色相了無取。","森森松映月，漠漠雲近戶。","嶺外飛電明，夜來前山雨。","然燈見栖鴿，作禮聞信鼓。","曉霽南軒開，秋華淨天宇。","願言出世塵，謝爾申及甫。"]', '["支公已寂滅，影塔山上古。","更有真僧来，道場救諸苦。","一承微妙法，寓宿清淨土。","身心能自观，色相了無取。","森森松映月，漠漠云近戶。","嶺外飞電明，夜来前山雨。","然灯见栖鴿，作禮闻信鼓。","晓霽南軒开，秋华淨天宇。","願言出世塵，謝爾申及甫。"]', '诗', 'shi', '', NULL, '宿大通和尚塔敬贈如上人兼呈常孫二山人 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad5c16d6-cff3-4035-b338-9704f8f5ffea', '送薛據之宋州', '送薛據之宋州', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["無媒嗟失路，有道亦乘流。","客處不堪別，異鄉應共愁。","我生早孤賤，淪落居此州。","風土至今憶，山河皆昔遊。","一從文章事，兩京春復秋。","君去問相識，幾人今白頭。"]', '["無媒嗟失路，有道亦乘流。","客处不堪別，異乡應共愁。","我生早孤賤，淪落居此州。","风土至今憶，山河皆昔游。","一從文章事，兩京春复秋。","君去问相識，幾人今白头。"]', '诗', 'shi', '', NULL, '送薛據之宋州 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e94c1fc4-e2f5-4640-8b14-38a4b0fef786', '山下晚晴', '山下晚晴', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["寥寥遠天淨，谿路何空濛。","斜光照疎雨，秋氣生白虹。","雲盡山色暝，蕭條西北風。","故林歸宿處，一葉下梧桐。"]', '["寥寥远天淨，谿路何空濛。","斜光照疎雨，秋氣生白虹。","云尽山色暝，蕭條西北风。","故林归宿处，一葉下梧桐。"]', '诗', 'shi', '', NULL, '山下晚晴 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7425804-a6da-42c7-9e0a-bc12a48bbf78', '潁陽東溪懷古', '潁陽东溪懷古', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["靈溪氛霧歇，皎鏡清心顏。","空色不映水，秋聲多在山。","世人久疎曠，萬物皆自閑。","白鷺寒更浴，孤雲晴未還。","昔時讓王者，此地閉玄關。","無以躡高步，淒涼岑壑間。"]', '["靈溪氛霧歇，皎镜清心顏。","空色不映水，秋声多在山。","世人久疎曠，万物皆自闲。","白鷺寒更浴，孤云晴未還。","昔时讓王者，此地閉玄关。","無以躡高步，淒涼岑壑间。"]', '诗', 'shi', '', NULL, '潁陽東溪懷古 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f690d2c-30f7-4813-a32f-e78c2ff0e39d', '早發交崖山還太室作', '早發交崖山還太室作', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["東林氣微白，寒鳥急高翔。","吾亦自茲去，北山歸草堂。","仲冬正三五，日月遙相望。","蕭蕭過潁上，曨曨辨少陽。","川冰生積雪，野火出枯桑。","獨往路難盡，窮陰人易傷。","傷此無衣客，如何蒙雪霜。"]', '["东林氣微白，寒鸟急高翔。","吾亦自茲去，北山归草堂。","仲冬正三五，日月遙相望。","蕭蕭過潁上，曨曨辨少陽。","川冰生積雪，野火出枯桑。","独往路难尽，窮陰人易傷。","傷此無衣客，如何蒙雪霜。"]', '诗', 'shi', '', NULL, '早發交崖山還太室作 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd77a627-ff6a-4e92-a9d7-ed882a4cf979', '奉試明堂火珠', '奉試明堂火珠', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["正位開重屋，凌空出火珠。","夜來雙月滿，曙後一星孤。","天淨光難滅，雲生望欲無。","遙知太平代，國寶在名都。"]', '["正位开重屋，凌空出火珠。","夜来雙月满，曙後一星孤。","天淨光难滅，云生望欲無。","遙知太平代，国寶在名都。"]', '诗', 'shi', '', NULL, '奉試明堂火珠 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c631e1-3f98-4c76-9b80-30cd40017982', '途中曉發', '途中晓發', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["曉霽長風裏，勞歌赴遠期。","雲輕歸海疾，月滿下山遲。","旅望因高盡，鄉心遇物悲。","故林遙不見，況在落花時。"]', '["晓霽长风裏，勞歌赴远期。","云轻归海疾，月满下山遲。","旅望因高尽，乡心遇物悲。","故林遙不见，況在落花时。"]', '诗', 'shi', '', NULL, '途中曉發 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7cc2b53-bf50-4166-9133-c27a4df28790', '緱山廟', '緱山廟', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["遺廟宿陰陰，孤峰映綠林。","步隨仙路遠，意入道門深。","澗水流年月，山雲變古今。","祗聞風竹裏，猶有鳳笙音。"]', '["遺廟宿陰陰，孤峰映綠林。","步隨仙路远，意入道门深。","澗水流年月，山云变古今。","祗闻风竹裏，猶有鳳笙音。"]', '诗', 'shi', '', NULL, '緱山廟 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edb61e96-1ead-4897-8dc0-951a7ac9f9cc', '同諸公謁啓母祠', '同諸公謁啓母祠', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["閟宮凌紫微，芳草閉閑扉。","帝子復何在，王孫遊不歸。","春風鳴玉珮，暮雨拂靈衣。","豈但湘江口，能令懷二妃。"]', '["閟宮凌紫微，芳草閉闲扉。","帝子复何在，王孫游不归。","春风鳴玉珮，暮雨拂靈衣。","豈但湘江口，能令懷二妃。"]', '诗', 'shi', '', NULL, '同諸公謁啓母祠 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c1d545e-07a1-46a9-bb76-b7473c1fde43', '九日登望仙臺呈劉明府容', '九日登望仙台呈劉明府容', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["漢文皇帝有高臺，此日登臨曙色開。","三晉雲山皆北向，二陵風雨自東來。","關門令尹誰能識，河上仙翁去不回。","且欲近尋彭澤宰，陶然共醉菊花杯。"]', '["漢文皇帝有高台，此日登臨曙色开。","三晉云山皆北向，二陵风雨自东来。","关门令尹誰能識，河上仙翁去不回。","且欲近尋彭澤宰，陶然共醉菊花杯。"]', '诗', 'shi', '', NULL, '九日登望仙臺呈劉明府容 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c4604a8-beff-415e-b150-daa58ba9ee1d', '奉酬中書相公至日圓丘攝事合於中書後閣宿齋移止于集賢院敘懷見寄之作', '奉酬中书相公至日圓丘攝事合於中书後閣宿斋移止于集賢院敘懷见寄之作', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["典籍開書府，恩榮避鼎司。","郊丘資有事，齋戒守無爲。","宿霧蒙瓊樹，餘香覆玉墀。","進經逢乙夜，展禮值明時。","勳共山河列，名同竹帛垂。","年年佐堯舜，相與致雍熙。"]', '["典籍开书府，恩榮避鼎司。","郊丘資有事，斋戒守無爲。","宿霧蒙瓊樹，餘香覆玉墀。","進經逢乙夜，展禮值明时。","勳共山河列，名同竹帛垂。","年年佐堯舜，相與致雍熙。"]', '诗', 'shi', '', NULL, '奉酬中書相公至日圓丘攝事合於中書後閣宿齋移止于集賢院敘懷見寄之作 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08548e78-98b8-4fec-83fe-eefedf6d9615', '登水門樓見亡友張貞期題望黃河詩因以感興', '登水门楼见亡友張貞期題望黄河诗因以感兴', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["吾友東南美，昔聞登此樓。","人隨川上逝，書向壁中留。","嚴子好真隱，謝公耽遠遊。","清風初作頌，暇日復銷憂。","時與文字古，跡將山水幽。","已孤蒼生望，空見黃河流。","流落年將晚，悲涼物已秋。","天高不可問，掩泣赴行舟。"]', '["吾友东南美，昔闻登此楼。","人隨川上逝，书向壁中留。","嚴子好真隐，謝公耽远游。","清风初作頌，暇日复銷憂。","时與文字古，跡將山水幽。","已孤蒼生望，空见黄河流。","流落年將晚，悲涼物已秋。","天高不可问，掩泣赴行舟。"]', '诗', 'shi', '', NULL, '登水門樓見亡友張貞期題望黃河詩因以感興 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e676e2a-b562-4437-a8b6-2fc58e7556a2', '對雨送鄭陵', '对雨送鄭陵', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["別愁復經雨，別淚還如霰。","寄心海上雲，千里常相見。"]', '["別愁复經雨，別泪還如霰。","寄心海上云，千里常相见。"]', '诗', 'shi', '', NULL, '對雨送鄭陵 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('485ba22a-9f18-4dba-9d39-5c295a9b96d1', '嵩山尋馮鍊師不遇', '嵩山尋馮鍊師不遇', '6cba0d46-8e07-41cf-abfd-e2e6e8dd5dc1', '唐', '["青溪訪道凌煙曙，王子仙成已飛去。","更值空山雷雨時，雲林薄暮歸何處。"]', '["青溪訪道凌煙曙，王子仙成已飞去。","更值空山雷雨时，云林薄暮归何处。"]', '诗', 'shi', '', NULL, '嵩山尋馮鍊師不遇 崔曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03d66f2-b572-48b6-b048-a2bb781bc8b3', '贈唐祖二子', '贈唐祖二子', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["鴻飛遵枉渚，鹿鳴思故羣。","物情尚勞愛，況乃予別君。","別時花始發，別後蘭再薰。","瑤觴滋白露，寶瑟凝涼氛。","裴徊北林月，悵望南山雲。","雲月渺千里，音徽不可聞。"]', '["鴻飞遵枉渚，鹿鳴思故羣。","物情尚勞愛，況乃予別君。","別时花始發，別後蘭再薰。","瑤觴滋白露，寶瑟凝涼氛。","裴徊北林月，悵望南山云。","云月渺千里，音徽不可闻。"]', '诗', 'shi', '', NULL, '贈唐祖二子 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd374be-35e5-45da-a300-9c8ef608005b', '飛燕篇', '飞燕篇', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["孝成皇帝本嬌奢，行幸平陽公主家。","可憐女兒三五許，䒠茸惜是一園花。","歌舞向來人不貴，一旦逢君感君意。","君心見賞不見忘，姊妹雙飛入紫房。","紫房綵女不得見，專榮固寵昭陽殿。","紅妝寶鏡珊瑚臺，青瑣銀簧雲母扇。","日夕風傳歌舞聲，祗擾長信憂人情。","長信憂人氣欲絕，君王歌吹終不歇。","朝弄瓊簫下綵雲，夜踏金梯上明月。","明月薄蝕陽精昏，嬌妬傾城惑至尊。","已見白虹橫紫極，復聞飛燕啄皇孫。","皇孫不死燕啄折，女弟一朝如火絕。","明明天子咸戒之，赫赫宗周襃姒滅。","古來賢聖歎狐裘，一國荒淫萬國羞。","安得上方斷馬劒，斬取朱門公子頭。"]', '["孝成皇帝本嬌奢，行幸平陽公主家。","可怜女兒三五許，䒠茸惜是一园花。","歌舞向来人不貴，一旦逢君感君意。","君心见賞不见忘，姊妹雙飞入紫房。","紫房綵女不得见，專榮固寵昭陽殿。","紅妝寶镜珊瑚台，青瑣銀簧云母扇。","日夕风傳歌舞声，祗擾长信憂人情。","长信憂人氣欲絕，君王歌吹終不歇。","朝弄瓊簫下綵云，夜踏金梯上明月。","明月薄蝕陽精昏，嬌妬傾城惑至尊。","已见白虹橫紫極，复闻飞燕啄皇孫。","皇孫不死燕啄折，女弟一朝如火絕。","明明天子咸戒之，赫赫宗周襃姒滅。","古来賢聖歎狐裘，一国荒淫万国羞。","安得上方斷马劒，斬取朱门公子头。"]', '诗', 'shi', '', NULL, '飛燕篇 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df299f8-0563-4612-9b09-65bc84221874', '飲馬長城窟行', '饮马长城窟行', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["長安少年無遠圖，一生惟羨執金吾。","麒麟前殿拜天子，走馬西擊長城胡。","胡沙獵獵吹人面，漢虜相逢不相見。","遙聞鼙鼓動地來，傳道單于夜猶戰。","此時顧恩寧顧身，爲君一行摧萬人。","壯士揮戈迴白日，單于濺血染朱輪。","歸來飲馬長城窟，長城道傍多白骨。","問之耆老何代人，云是秦王築城卒。","黃昏塞北無人煙，鬼哭啾啾聲沸天。","無罪見誅功不賞，孤魂流落此城邊。","當昔秦王按劒起，諸侯膝行不敢視。","富國强兵二十年，築怨興徭九千里。","秦王築城何太愚，天實亡秦非北胡。","一朝禍起蕭墻內，渭水咸陽不復都。"]', '["长安少年無远圖，一生惟羨執金吾。","麒麟前殿拜天子，走马西擊长城胡。","胡沙獵獵吹人面，漢虜相逢不相见。","遙闻鼙鼓动地来，傳道單于夜猶戰。","此时顧恩寧顧身，爲君一行摧万人。","壯士揮戈迴白日，單于濺血染朱輪。","归来饮马长城窟，长城道傍多白骨。","问之耆老何代人，云是秦王築城卒。","黄昏塞北無人煙，鬼哭啾啾声沸天。","無罪见誅功不賞，孤魂流落此城邊。","當昔秦王按劒起，諸侯膝行不敢視。","富国强兵二十年，築怨兴徭九千里。","秦王築城何太愚，天實亡秦非北胡。","一朝禍起蕭墻內，渭水咸陽不复都。"]', '诗', 'shi', '', NULL, '飲馬長城窟行 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a831474d-8c73-428b-9057-2c153a7111e1', '賦得明星玉女壇送廉察尉華陰', '賦得明星玉女壇送廉察尉华陰', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["洪河之南曰秦鎮，發地削成五千仞。","三峰離地皆倚天，唯獨中峰特修峻。","上有明星玉女祠，祠壇高眇路逶迤。","三十六梯入河漢，樵人往往見蛾眉。","蛾眉嬋娟又宜笑，一見樵人下靈廟。","仙車欲駕五雲飛，香扇斜開九華照。","含情遲佇惜韶年，願侍君邊復中旋。","江妃玉佩留爲念，嬴女銀簫空自憐。","仙俗途殊兩情遽，感君無盡辭君去。","遙見明星是妾家，風飄雪散不知處。","故人家在西長安，賣藥往來投此山。","綵雲蕩漾不可見，綠蘿蒙茸鳥綿蠻。","欲求玉女長生法，日夜燒香應自還。"]', '["洪河之南曰秦鎮，發地削成五千仞。","三峰離地皆倚天，唯独中峰特修峻。","上有明星玉女祠，祠壇高眇路逶迤。","三十六梯入河漢，樵人往往见蛾眉。","蛾眉嬋娟又宜笑，一见樵人下靈廟。","仙车欲駕五云飞，香扇斜开九华照。","含情遲佇惜韶年，願侍君邊复中旋。","江妃玉佩留爲念，嬴女銀簫空自怜。","仙俗途殊兩情遽，感君無尽辞君去。","遙见明星是妾家，风飄雪散不知处。","故人家在西长安，賣藥往来投此山。","綵云蕩漾不可见，綠蘿蒙茸鸟綿蠻。","欲求玉女长生法，日夜燒香應自還。"]', '诗', 'shi', '', NULL, '賦得明星玉女壇送廉察尉華陰 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf841960-0678-4df4-bae7-88c855490346', '春女行', '春女行', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["紫臺穹跨連綠波，紅軒鉿匝垂纖羅。","中有一人金作面，隔幌玲瓏遙可見。","忽聞黃鳥鳴且悲，鏡邊含笑著春衣。","羅袖嬋娟似無力，行拾落花比容色。","落花一度無再春，人生作樂須及辰。","君不見楚王臺上紅顏子，今日皆成狐兔塵。"]', '["紫台穹跨連綠波，紅軒鉿匝垂纖羅。","中有一人金作面，隔幌玲瓏遙可见。","忽闻黄鸟鳴且悲，镜邊含笑著春衣。","羅袖嬋娟似無力，行拾落花比容色。","落花一度無再春，人生作乐須及辰。","君不见楚王台上紅顏子，今日皆成狐兔塵。"]', '诗', 'shi', '', NULL, '春女行 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dff6090-a3e1-4305-a186-fad81d1900a1', '古娥眉怨', '古娥眉怨', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["君不見宜春苑中九華殿，飛閣連連直如髮。","白日全含朱鳥窓，流雲半入蒼龍闕。","宮中綵女夜無事，學鳳吹簫弄清越。","珠簾北卷待涼風，繡戶南開向明月。","忽聞天子憶蛾眉，寶鳳銜花揲兩螭。","傳聲走馬開金屋，夾路鳴環上玉墀。","長樂彤庭宴華寢，三千美人曳花錦。","燈前含笑更羅衣，帳裏承恩薦瑤枕。","不意君心半路迴，求仙別作望仙臺。","琳琅禁闥遙相憶，紫翠巖房晝不開。","欲向人間種桃實，先從海底覓蓬萊。","蓬來可求不可上，孤舟飄緲知何往。","黃金作盤銅作莖，青天白露掌中擎。","王母嫣然感君意，雲車羽斾欲相迎。","飛廉觀前空怨慕，少君何事須相誤。","一朝埋沒茂陵田，賤妾蛾眉不重顧。","宮車晚出向南山，仙衛逶迤去不還。","朝晡泣對麒麟樹，樹下蒼苔日漸斑。","人生百年夜將半，對酒長歌莫長歎。","情知白日不可私，一死一生何足筭。"]', '["君不见宜春苑中九华殿，飞閣連連直如髮。","白日全含朱鸟窓，流云半入蒼龙闕。","宮中綵女夜無事，学鳳吹簫弄清越。","珠簾北卷待涼风，繡戶南开向明月。","忽闻天子憶蛾眉，寶鳳銜花揲兩螭。","傳声走马开金屋，夾路鳴环上玉墀。","长乐彤庭宴华寢，三千美人曳花錦。","灯前含笑更羅衣，帳裏承恩薦瑤枕。","不意君心半路迴，求仙別作望仙台。","琳琅禁闥遙相憶，紫翠巖房晝不开。","欲向人间種桃實，先從海底覓蓬萊。","蓬来可求不可上，孤舟飄緲知何往。","黄金作盤銅作莖，青天白露掌中擎。","王母嫣然感君意，云车羽斾欲相迎。","飞廉观前空怨慕，少君何事須相誤。","一朝埋沒茂陵田，賤妾蛾眉不重顧。","宮车晚出向南山，仙衛逶迤去不還。","朝晡泣对麒麟樹，樹下蒼苔日漸斑。","人生百年夜將半，对酒长歌莫长歎。","情知白日不可私，一死一生何足筭。"]', '诗', 'shi', '', NULL, '古娥眉怨 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dfd427-2780-4ac6-bb44-3cc39dc202c4', '子夜春歌', '子夜春歌', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["春氣滿林香，春遊不可忘。","落花吹欲盡，垂柳折還長。","桑女淮南曲，金鞍塞北裝。","行行小垂手，日暮渭川陽。"]', '["春氣满林香，春游不可忘。","落花吹欲尽，垂柳折還长。","桑女淮南曲，金鞍塞北裝。","行行小垂手，日暮渭川陽。"]', '诗', 'shi', '', NULL, '子夜春歌 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f816fb7e-029f-4c24-a1e2-37adee7fc431', '奉和聖製同二相已下羣官樂遊園宴', '奉和聖製同二相已下羣官乐游园宴', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["未極人心暢，如何帝道明。","仍嫌酺宴促，復寵樂遊行。","陸海披珍藏，天河直斗城。","四關青靄合，數處白雲生。","飪餗調元氣，歌鐘溢雅聲。","空慚堯舜日，至德杳難名。"]', '["未極人心暢，如何帝道明。","仍嫌酺宴促，复寵乐游行。","陸海披珍藏，天河直斗城。","四关青靄合，數处白云生。","飪餗調元氣，歌鐘溢雅声。","空慚堯舜日，至德杳难名。"]', '诗', 'shi', '', NULL, '奉和聖製同二相已下羣官樂遊園宴 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a8ecd8-09e9-42c3-98c0-015f1d2a7460', '奉和聖製送張說上集賢院學士賜宴得筵字', '奉和聖製送張说上集賢院学士賜宴得筵字', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["東堂起集賢，貴得從神仙。","首命台階老，將崇御府員。","送人鏘玉佩，中使拂瓊筵。","和樂薰風解，湛恩時雨連。","長材成磊落，短翮強翩翾。","徒仰蓬萊地，何階不讓緣。"]', '["东堂起集賢，貴得從神仙。","首命台階老，將崇御府員。","送人鏘玉佩，中使拂瓊筵。","和乐薰风解，湛恩时雨連。","长材成磊落，短翮強翩翾。","徒仰蓬萊地，何階不讓緣。"]', '诗', 'shi', '', NULL, '奉和聖製送張說上集賢院學士賜宴得筵字 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c72ad2-c3e0-4f21-a419-af79d6dd0f42', '奉和聖製送張尚書巡邊', '奉和聖製送張尚书巡邊', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["紫綬尚書印，朱軿丞相車。","登朝身許國，出閫將辭家。","不憚炎蒸苦，親嘗走集賒。","選徒軍有政，誓卒爾無譁。","帝樂風初起，王城日半斜。","寵行流聖作，寅餞照台華。","騎歷河南樹，旌搖塞北沙。","榮懷應盡服，嚴殺已先加。","業峻靈祇保，功成道路嗟。","寧如鑿空使，遠致石榴花。"]', '["紫綬尚书印，朱軿丞相车。","登朝身許国，出閫將辞家。","不憚炎蒸苦，親嘗走集賒。","選徒軍有政，誓卒爾無譁。","帝乐风初起，王城日半斜。","寵行流聖作，寅餞照台华。","騎歷河南樹，旌搖塞北沙。","榮懷應尽服，嚴殺已先加。","業峻靈祇保，功成道路嗟。","寧如鑿空使，远致石榴花。"]', '诗', 'shi', '', NULL, '奉和聖製送張尚書巡邊 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0445f296-5816-4ab9-a617-7d8ed29088ea', '涼州詞二首 一', '涼州词二首 一', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["葡萄美酒夜光杯，欲飲琵琶馬上催。","醉臥沙場君莫笑，古來征戰幾人回。"]', '["葡萄美酒夜光杯，欲饮琵琶马上催。","醉臥沙場君莫笑，古来征戰幾人回。"]', '诗', 'shi', '', NULL, '涼州詞二首 一 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1b5f1d-d2f5-4a30-afd6-993138cf3d99', '涼州詞二首 二', '涼州词二首 二', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["秦中花鳥已應闌，塞外風沙猶自寒。","夜聽胡笳折楊柳，教人意氣憶長安。"]', '["秦中花鸟已應闌，塞外风沙猶自寒。","夜听胡笳折楊柳，教人意氣憶长安。"]', '诗', 'shi', '', NULL, '涼州詞二首 二 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32d6625b-267a-4a59-8f76-14a4dc97d81f', '春日歸思', '春日归思', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["楊柳青青杏發花，年光誤客轉思家。","不知湖上菱歌女，幾箇春舟在若耶。"]', '["楊柳青青杏發花，年光誤客轉思家。","不知湖上菱歌女，幾箇春舟在若耶。"]', '诗', 'shi', '', NULL, '春日歸思 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36517bbc-becc-468f-a76c-082916a9a54c', '觀蠻童爲伎之作', '观蠻童爲伎之作', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["長裙錦帶還留客，廣額青蛾亦效嚬。","共惜不成金谷妓，虛令看殺玉車人。"]', '["长裙錦带還留客，廣額青蛾亦效嚬。","共惜不成金谷妓，虛令看殺玉车人。"]', '诗', 'shi', '', NULL, '觀蠻童爲伎之作 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b25786a-bf83-4daf-b91a-2c7cb81a2bbf', '古別離', '古別離', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["朝日上高臺，離人怨秋草。","但見萬里天，不見萬里道。","君行本迢遠，苦樂良難保。","宿昔夢同衾，憂心常傾倒。","含酸欲誰訴，展轉傷懷抱。","結髮年已遲，征行去何早。","寒暄有時謝，憔悴難再好。","人皆算年壽，死者何曾老。","少壯無見期，水深風浩浩。"]', '["朝日上高台，離人怨秋草。","但见万里天，不见万里道。","君行本迢远，苦乐良难保。","宿昔梦同衾，憂心常傾倒。","含酸欲誰訴，展轉傷懷抱。","結髮年已遲，征行去何早。","寒暄有时謝，憔悴难再好。","人皆算年壽，死者何曾老。","少壯無见期，水深风浩浩。"]', '诗', 'shi', '', NULL, '古別離 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd79b598-a286-4537-86aa-567050db4b32', '今別離', '今別離', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["結髮生別離，相思復相保。","如何日已久，五變庭中草。","渺渺大海途，悠悠吳江島。","但恐不出門，出門無遠道。","遠道行既難，家貧衣復單。","嚴風吹積雪，晨起鼻何酸。","人生各有志，豈不懷所安。","分明天上日，生死願同歡。"]', '["結髮生別離，相思复相保。","如何日已久，五变庭中草。","渺渺大海途，悠悠吳江島。","但恐不出门，出门無远道。","远道行既难，家貧衣复單。","嚴风吹積雪，晨起鼻何酸。","人生各有志，豈不懷所安。","分明天上日，生死願同歡。"]', '诗', 'shi', '', NULL, '今別離 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d050f7f-de64-400b-bec5-9240432d51ea', '悲哉行', '悲哉行', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["孤兒去慈親，遠客喪主人。","莫吟苦辛曲，此曲誰忍聞。","可聞不可說，去去無期別。","行人念前程，不待參辰沒。","朝亦常苦饑，暮亦常苦饑。","飄飄萬餘里，貧賤多是非。","少年莫遠遊，遠遊多不歸。"]', '["孤兒去慈親，远客喪主人。","莫吟苦辛曲，此曲誰忍闻。","可闻不可说，去去無期別。","行人念前程，不待參辰沒。","朝亦常苦饑，暮亦常苦饑。","飄飄万餘里，貧賤多是非。","少年莫远游，远游多不归。"]', '诗', 'shi', '', NULL, '悲哉行 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b56a6d9-e90b-4091-8bdb-5529af3b238b', '行行且遊獵篇', '行行且游獵篇', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["少年多武力，勇氣冠幽州。","何以縱心賞，馬啼春草頭。","遲遲平原上，狐兔奔林丘。","猛虎忽前逝，俊鷹連下韝。","俯身逐南北，輕捷固難儔。","所發無不中，失之如我讐。","豈唯務馳騁，猗爾暴田疇。","殘殺非不痛，古來良有由。"]', '["少年多武力，勇氣冠幽州。","何以縱心賞，马啼春草头。","遲遲平原上，狐兔奔林丘。","猛虎忽前逝，俊鷹連下韝。","俯身逐南北，轻捷固难儔。","所發無不中，失之如我讐。","豈唯務驰騁，猗爾暴田疇。","殘殺非不痛，古来良有由。"]', '诗', 'shi', '', NULL, '行行且遊獵篇 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba56c4b7-e9a9-4a72-8ddd-dc34ea1e1961', '古挽歌', '古挽歌', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["草草閭巷喧，塗車儼成位。","冥冥何所須，盡我生人意。","北邙路非遠，此別終天地。","臨穴頻撫棺，至哀反無淚。","爾形未衰老，爾息纔童稚。","骨肉安可離，皇天若容易。","房帷即靈帳，庭宇爲哀次。","薤露歌若斯，人生盡如寄。"]', '["草草閭巷喧，塗车儼成位。","冥冥何所須，尽我生人意。","北邙路非远，此別終天地。","臨穴頻撫棺，至哀反無泪。","爾形未衰老，爾息纔童稚。","骨肉安可離，皇天若容易。","房帷即靈帳，庭宇爲哀次。","薤露歌若斯，人生尽如寄。"]', '诗', 'shi', '', NULL, '古挽歌 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e638e332-fb02-4328-9c30-c3f581dfa454', '放歌行', '放歌行', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["吾觀天地圖，世界亦可小。","落落大海中，飄浮數洲島。","賢愚與蟻蝨，一種同草草。","地脉日夜流，天衣有時掃。","東山謁居士，了我生死道。","目見難噬臍，心通可親腦。","軒皇竟磨滅，周孔亦衰老。","永謝當時人，吾將寶非寶。"]', '["吾观天地圖，世界亦可小。","落落大海中，飄浮數洲島。","賢愚與蟻蝨，一種同草草。","地脉日夜流，天衣有时掃。","东山謁居士，了我生死道。","目见难噬臍，心通可親腦。","軒皇竟磨滅，周孔亦衰老。","永謝當时人，吾將寶非寶。"]', '诗', 'shi', '', NULL, '放歌行 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c419cafd-6b8b-4ebe-8e3a-eb3d9c300e89', '傷懷贈故人', '傷懷贈故人', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["稍稍晨鳥翔，淅淅草上霜。","人生早罹苦，壽命恐不長。","二十學已成，三十名不彰。","豈無同門友，貴賤易中腸。","驅馬行萬里，悠悠過帝鄉。","幸因弦歌末，得上君子堂。","衆樂互喧奏，獨子備笙簧。","坐中無知音，安得神揚揚。","願因高風起，上感白日光。"]', '["稍稍晨鸟翔，淅淅草上霜。","人生早罹苦，壽命恐不长。","二十学已成，三十名不彰。","豈無同门友，貴賤易中腸。","驱马行万里，悠悠過帝乡。","幸因弦歌末，得上君子堂。","衆乐互喧奏，独子備笙簧。","坐中無知音，安得神揚揚。","願因高风起，上感白日光。"]', '诗', 'shi', '', NULL, '傷懷贈故人 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c452f516-2d49-4161-b25c-16be79f1ced1', '鄴城懷古', '鄴城懷古', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["朝發淇水南，將尋北燕路。","魏家舊城闕，寥落無人住。","伊昔天地屯，曹公獨中據。","羣臣將北面，白日忽西暮。","三臺竟寂寞，萬事良難固。","雄圖安在哉？衰草霑霜露。","崔嵬長河北，尚見應劉墓。","古樹藏龍蛇，荒茅伏狐兔。","永懷故池館，數子連章句。","逸興驅山河，雄詞變雲霧。","我行覩遺跡，精爽如可遇。","斗酒將酹君，悲風白楊樹。"]', '["朝發淇水南，將尋北燕路。","魏家旧城闕，寥落無人住。","伊昔天地屯，曹公独中據。","羣臣將北面，白日忽西暮。","三台竟寂寞，万事良难固。","雄圖安在哉？衰草霑霜露。","崔嵬长河北，尚见應劉墓。","古樹藏龙蛇，荒茅伏狐兔。","永懷故池館，數子連章句。","逸兴驱山河，雄词变云霧。","我行覩遺跡，精爽如可遇。","斗酒將酹君，悲风白楊樹。"]', '诗', 'shi', '', NULL, '鄴城懷古 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9826bcc6-6fe2-40c9-b66a-6ce210b19d28', '傷情', '傷情', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["爲長心易憂，早孤意常傷。","出門先躊躇，入戶亦彷徨。","此生一何苦，前事安可忘。","兄弟先我沒，孤幼盈我傍。","舊居近東南，河水新爲梁。","松柏今在茲，安忍思故鄉。","四時與日月，萬物各有常。","秋風已一起，草木無不霜。","行行當自勉，不忍再思量。"]', '["爲长心易憂，早孤意常傷。","出门先躊躇，入戶亦彷徨。","此生一何苦，前事安可忘。","兄弟先我沒，孤幼盈我傍。","旧居近东南，河水新爲梁。","松柏今在茲，安忍思故乡。","四时與日月，万物各有常。","秋风已一起，草木無不霜。","行行當自勉，不忍再思量。"]', '诗', 'shi', '', NULL, '傷情 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80047e73-5f6d-4e7e-928c-568f73f57ef7', '傷時二首 一', '傷时二首 一', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["徘回宋郊上，不覩平生親。","獨立正傷心，悲風來孟津。","大方載羣物，生死有常倫。","虎豹不相食，哀哉人食人。","豈伊逢世運，天道亮云云。"]', '["徘回宋郊上，不覩平生親。","独立正傷心，悲风来孟津。","大方載羣物，生死有常倫。","虎豹不相食，哀哉人食人。","豈伊逢世運，天道亮云云。"]', '诗', 'shi', '', NULL, '傷時二首 一 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455b06e6-ffa2-4cca-a754-32053f519790', '傷時二首 二', '傷时二首 二', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["太空流素月，三五何明明。","光耀侵白日，賢愚迷至精。","四時更變化，天道有虧盈。","常恐今夜沒，須臾還復生。"]', '["太空流素月，三五何明明。","光耀侵白日，賢愚迷至精。","四时更变化，天道有虧盈。","常恐今夜沒，須臾還复生。"]', '诗', 'shi', '', NULL, '傷時二首 二 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c978518f-34af-4bf0-b02d-77117a93b41b', '田園觀雨兼晴後作', '田园观雨兼晴後作', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["貧賤少情欲，借荒種南陂。","我非老農圃，安得良土宜。","秋成不廉儉，歲餘多餒飢。","顧視倉廩間，有糧不成炊。","晨登南園上，暮歇清蟬悲。","早苗既芃芃，晚田尚離離。","五行孰堪廢，萬物當及時。","賢哉數夫子，開翅慎勿遲。"]', '["貧賤少情欲，借荒種南陂。","我非老農圃，安得良土宜。","秋成不廉儉，歲餘多餒飢。","顧視倉廩间，有糧不成炊。","晨登南园上，暮歇清蟬悲。","早苗既芃芃，晚田尚離離。","五行孰堪廢，万物當及时。","賢哉數夫子，开翅慎勿遲。"]', '诗', 'shi', '', NULL, '田園觀雨兼晴後作 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5ec906-b520-4e83-a9ce-e2187e78aaf1', '汴河阻風', '汴河阻风', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["清晨自梁宋，挂席之楚荆。","出浦風漸惡，傍灘舟欲橫。","大河噴東注，羣動皆窅冥。","白霧魚龍氣，黑雲牛馬形。","蒼茫迷所適，危安懼暫寧。","信此天地內，孰爲身命輕。","丈夫苟未達，所向須存誠。","前路捨舟去，東南仍曉晴。"]', '["清晨自梁宋，挂席之楚荆。","出浦风漸惡，傍灘舟欲橫。","大河噴东注，羣动皆窅冥。","白霧鱼龙氣，黑云牛马形。","蒼茫迷所適，危安懼暫寧。","信此天地內，孰爲身命轻。","丈夫苟未達，所向須存誠。","前路捨舟去，东南仍晓晴。"]', '诗', 'shi', '', NULL, '汴河阻風 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb137725-18d9-4ebc-b1e5-4d31b7f1c6f5', '行路難', '行路难', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["君不見高山萬仞連蒼旻，天長地久成埃塵。","君不見長松百尺多勁節，狂風暴雨終摧折。","古今何事無聖賢，吾愛伯陽真乃天。","金堂玉闕朝羣仙，拍手東海成桑田。","海中之水慎勿枯，烏鳶啄蚌傷明珠。","行路難，艱險莫踟躕。"]', '["君不见高山万仞連蒼旻，天长地久成埃塵。","君不见长松百尺多勁節，狂风暴雨終摧折。","古今何事無聖賢，吾愛伯陽真乃天。","金堂玉闕朝羣仙，拍手东海成桑田。","海中之水慎勿枯，烏鳶啄蚌傷明珠。","行路难，艱險莫踟躕。"]', '诗', 'shi', '', NULL, '行路難 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2b9b23-4d14-49e9-974f-21f7d2ec4eb8', '途中寄友人', '途中寄友人', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["昔時聞遠路，謂是等閑行。","及到求人地，始知爲客情。","事將公道背，塵遶馬蹄生。","儻使長如此，便堪休去程。"]', '["昔时闻远路，謂是等闲行。","及到求人地，始知爲客情。","事將公道背，塵遶马蹄生。","儻使长如此，便堪休去程。"]', '诗', 'shi', '', NULL, '途中寄友人 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27cb30cd-7b65-4922-8262-40dec810f252', '寒食', '寒食', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["二月江南花滿枝，他鄉寒食遠堪悲。","貧居往往無煙火，不獨明朝爲子推。"]', '["二月江南花满枝，他乡寒食远堪悲。","貧居往往無煙火，不独明朝爲子推。"]', '诗', 'shi', '', NULL, '寒食 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0c912ba-782a-41a0-a759-20475a8c900e', '新安江上寄處士', '新安江上寄处士', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["深潭與淺灘，萬轉出新安。","人遠禽魚靜，山空水木寒。","嘯起青蘋末，吟矚白雲端。","即事遂幽賞，何必挂儒冠。"]', '["深潭與淺灘，万轉出新安。","人远禽鱼静，山空水木寒。","嘯起青蘋末，吟矚白云端。","即事遂幽賞，何必挂儒冠。"]', '诗', 'shi', '', NULL, '新安江上寄處士 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7babe6fc-4b31-4d3e-a946-eb2a178aab48', '句', '句', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["羣物歸大化，六龍頹西荒。","安知浮雲外，日月不運行。"]', '["羣物归大化，六龙頹西荒。","安知浮云外，日月不運行。"]', '诗', 'shi', '', NULL, '句 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f1a2ad-96f1-4a34-81d8-d6f6aa802ca8', '聞笛', '闻笛', '134facea-f346-487b-a0fc-d3d8d032e787', '唐', '["岧嶤試一臨，虜騎附城陰。","不辨風塵色，安知天地心。","營開邊月近，戰苦陣雲深。","旦夕更樓上，遙聞橫笛音。"]', '["岧嶤試一臨，虜騎附城陰。","不辨风塵色，安知天地心。","營开邊月近，戰苦陣云深。","旦夕更楼上，遙闻橫笛音。"]', '诗', 'shi', '', NULL, '聞笛 張巡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbf07e9-1484-408d-aa48-108b34d89d3f', '守睢陽作', '守睢陽作', '134facea-f346-487b-a0fc-d3d8d032e787', '唐', '["接戰春來苦，孤城日漸危。","合圍侔月暈，分守若魚麗。","屢厭黃塵起，時將白羽揮。","裹瘡猶出陣，飲血更登陴。","忠信應難敵，堅貞諒不移。","無人報天子，心計欲何施。"]', '["接戰春来苦，孤城日漸危。","合圍侔月暈，分守若鱼丽。","屢厭黄塵起，时將白羽揮。","裹瘡猶出陣，饮血更登陴。","忠信應难敵，堅貞諒不移。","無人報天子，心計欲何施。"]', '诗', 'shi', '', NULL, '守睢陽作 張巡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d83271c-bc30-44a1-9826-964884c42856', '題衡陽泗州寺', '題衡陽泗州寺', '5d2dbbe4-b273-4d35-8dcc-5e630a2ac9cd', '唐', '["一水悠悠百粵通，片帆無奈信秋風。","幾層峽浪寒舂月，盡日江天雨打篷。","漂泊漸搖青草外，鄉關誰念雪園東。","未知今夜依何處，一點漁燈出葦叢。"]', '["一水悠悠百粵通，片帆無奈信秋风。","幾層峽浪寒舂月，尽日江天雨打篷。","漂泊漸搖青草外，乡关誰念雪园东。","未知今夜依何处，一点漁灯出葦叢。"]', '诗', 'shi', '', NULL, '題衡陽泗州寺 張抃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a987fa09-4041-457f-9d3e-d9fd4b064c27', '古意二首 一', '古意二首 一', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["秦庭初指鹿，羣盜滿山東。","忤意皆誅死，所言誰肯忠。","武關猶未啓，兵入望夷宮。","爲祟非涇水，人君道自窮。"]', '["秦庭初指鹿，羣盜满山东。","忤意皆誅死，所言誰肯忠。","武关猶未啓，兵入望夷宮。","爲祟非涇水，人君道自窮。"]', '诗', 'shi', '', NULL, '古意二首 一 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88cb82da-e206-4a9c-a216-6de0aae0d585', '古意二首 二', '古意二首 二', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["崇蘭生澗底，香氣滿幽林。","采采欲爲贈，何人是同心。","日暮徙盈把，裴回憂思深。","慨然紉雜佩，重奏丘中琴。"]', '["崇蘭生澗底，香氣满幽林。","采采欲爲贈，何人是同心。","日暮徙盈把，裴回憂思深。","慨然紉杂佩，重奏丘中琴。"]', '诗', 'shi', '', NULL, '古意二首 二 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7eb0ae68-c481-4148-a41a-a9f82ba0fd75', '行路難五首 一', '行路难五首 一', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見巖下井，百尺不及泉。","君不見山上苗，數寸凌雲煙。","人生賦命亦如此，何苦太息自憂煎。","但願親友長含笑，相逢不乏杖頭錢。","寒夜邀歡須秉燭，豈得常思花柳年。"]', '["君不见巖下井，百尺不及泉。","君不见山上苗，數寸凌云煙。","人生賦命亦如此，何苦太息自憂煎。","但願親友长含笑，相逢不乏杖头錢。","寒夜邀歡須秉燭，豈得常思花柳年。"]', '诗', 'shi', '', NULL, '行路難五首 一 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74cc8a9-b5d5-4fb8-8856-d67dc95efea5', '行路難五首 二', '行路难五首 二', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見門前柳，榮耀暫時蕭索久。","君不見陌上花，狂風吹去落誰家。","鄰家思婦見之歎，蓬首不梳心歷亂。","盛年夫壻長別離，歲暮相逢色已換。"]', '["君不见门前柳，榮耀暫时蕭索久。","君不见陌上花，狂风吹去落誰家。","鄰家思婦见之歎，蓬首不梳心歷亂。","盛年夫壻长別離，歲暮相逢色已換。"]', '诗', 'shi', '', NULL, '行路難五首 二 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff6eeeae-4e01-426e-90b8-98391b05ec77', '行路難五首 三', '行路难五首 三', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見芳樹枝，春花落盡蜂不窺。","君不見梁上泥，秋風始高燕不棲。","蕩子從軍事征戰，[蛾]眉嬋娟守空閨。","獨宿自然堪下淚，況復時聞烏夜啼。"]', '["君不见芳樹枝，春花落尽蜂不窺。","君不见梁上泥，秋风始高燕不棲。","蕩子從軍事征戰，[蛾]眉嬋娟守空閨。","独宿自然堪下泪，況复时闻烏夜啼。"]', '诗', 'shi', '', NULL, '行路難五首 三 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c72c21de-0a00-4df5-816a-6972aefbb823', '行路難五首 四', '行路难五首 四', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見雲中月，暫盈還復缺。","君不見林下風，聲遠意難窮。","親故平生或聚散，歡娛未盡尊酒空。","歎息青青陵上柏，歲寒能有幾人同。"]', '["君不见云中月，暫盈還复缺。","君不见林下风，声远意难窮。","親故平生或聚散，歡娛未尽尊酒空。","歎息青青陵上柏，歲寒能有幾人同。"]', '诗', 'shi', '', NULL, '行路難五首 四 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31391108-7664-4329-8f46-3e5c3b1cf7f7', '行路難五首 五', '行路难五首 五', '26b83258-6111-419d-be94-30ed576cfe23', '唐', '["君不見東流水，一去無窮已。","君不見西郊雲，日夕空氛氳。","羣鴈裴回不能去，一鴈悲鳴復失羣。","人生結交在終始，莫以升沈中路分。"]', '["君不见东流水，一去無窮已。","君不见西郊云，日夕空氛氳。","羣鴈裴回不能去，一鴈悲鳴复失羣。","人生結交在終始，莫以升沈中路分。"]', '诗', 'shi', '', NULL, '行路難五首 五 賀蘭進明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdce47b-964e-4ec9-96e3-5bee4552ab64', '夜渡江', '夜渡江', '505fee69-5a33-4344-88b8-ba789fec4cf5', '唐', '["舟人自相報，落日下芳潭。","夜火連淮市，春風滿客帆。","水窮滄海畔，路盡小山南。","且喜鄉園近，言榮意未甘。"]', '["舟人自相報，落日下芳潭。","夜火連淮市，春风满客帆。","水窮滄海畔，路尽小山南。","且喜乡园近，言榮意未甘。"]', '诗', 'shi', '', NULL, '夜渡江 閭丘曉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a84422b-f228-4263-8d6f-281b1606d605', '奉和劉採訪縉雲南嶺作', '奉和劉採訪縉云南嶺作', '01ffa906-a1f8-4592-8d9c-7c1be9b9723f', '唐', '["百越城池枕海圻，永嘉山水復相依。","懸蘿弱篠垂清淺，宿雨朝暾和翠微。","鳥訝山經傳不盡，花隨月令數仍稀。","幸陪謝客題詩句，誰與王孫此地歸。"]', '["百越城池枕海圻，永嘉山水复相依。","懸蘿弱篠垂清淺，宿雨朝暾和翠微。","鸟訝山經傳不尽，花隨月令數仍稀。","幸陪謝客題诗句，誰與王孫此地归。"]', '诗', 'shi', '', NULL, '奉和劉採訪縉雲南嶺作 庾光先 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052679c2-9971-417f-b6d9-368e9c711569', '思歸寄東林澈上人', '思归寄东林澈上人', '9cf009ef-1752-43f9-94ad-edc14bb66de5', '唐', '["王事紛紛無暇日，浮生冉冉只如雲。","已爲平子歸休計，五老巖前必共聞。"]', '["王事紛紛無暇日，浮生冉冉只如云。","已爲平子归休計，五老巖前必共闻。"]', '诗', 'shi', '', NULL, '思歸寄東林澈上人 韋丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c53bea4-f8a0-44f0-8447-e82dfded884b', '荅澈公', '荅澈公', '9cf009ef-1752-43f9-94ad-edc14bb66de5', '唐', '["空山泉落松窗靜，閑地草生春日遲。","白髮漸多身未退，依依常在永禪師。"]', '["空山泉落松窗静，闲地草生春日遲。","白髮漸多身未退，依依常在永禪師。"]', '诗', 'shi', '', NULL, '荅澈公 韋丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a9c38f-b828-4040-9171-69df1e94080c', '洛出書', '洛出书', '754fad08-b154-45db-b210-a42efe31fe5a', '唐', '["海內昔凋瘵，天網斯浡潏。","龜靈啓聖圖，龍馬負書出。","大哉明德盛，遠矣彝倫秩。","地敷作乂功，人免爲魚恤。","既彰千國理，豈止百川溢。","永賴至於今，疇庸未云畢。"]', '["海內昔凋瘵，天網斯浡潏。","龟靈啓聖圖，龙马負书出。","大哉明德盛，远矣彝倫秩。","地敷作乂功，人免爲鱼恤。","既彰千国理，豈止百川溢。","永賴至於今，疇庸未云畢。"]', '诗', 'shi', '', NULL, '洛出書 蕭昕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04fa3d61-2d66-45a5-82a5-44c92cdf29e8', '臨風舒錦', '臨风舒錦', '754fad08-b154-45db-b210-a42efe31fe5a', '唐', '["麗錦疋云終，襜襜展向風。","花開翻覆翠，色亂動搖紅。","縷散悠揚裏，文迴照灼中。","低垂疑步障，吹起作晴虹。","既與丘遲夢，深知卓氏功。","還鄉將製服，從此表亨通。"]', '["丽錦疋云終，襜襜展向风。","花开翻覆翠，色亂动搖紅。","縷散悠揚裏，文迴照灼中。","低垂疑步障，吹起作晴虹。","既與丘遲梦，深知卓氏功。","還乡將製服，從此表亨通。"]', '诗', 'shi', '', NULL, '臨風舒錦 蕭昕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62405264-e6cd-4af8-acd5-a576adb5c5c5', '東皇太一詞', '东皇太一词', '4954b3c6-757a-44f4-9f1e-a3693107a677', '唐', '["吉日初齊戒，靈巫穆上皇。","焚香布瑤席，鳴珮奠椒漿。","緩舞花飛滿，清歌水去長。","迴波送神曲，雲雨滿瀟湘。"]', '["吉日初齊戒，靈巫穆上皇。","焚香布瑤席，鳴珮奠椒漿。","緩舞花飞满，清歌水去长。","迴波送神曲，云雨满瀟湘。"]', '诗', 'shi', '', NULL, '東皇太一詞 李希仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057ba7ec-5fc3-4658-bba5-26bcb9a0965e', '薊北行二首 一', '薊北行二首 一', '4954b3c6-757a-44f4-9f1e-a3693107a677', '唐', '["旄頭有精芒，胡騎獵秋草。","羽檄南渡河，邊庭用兵早。","漢家愛征戰，宿將今已老。","辛苦羽林兒，從戎榆關道。"]', '["旄头有精芒，胡騎獵秋草。","羽檄南渡河，邊庭用兵早。","漢家愛征戰，宿將今已老。","辛苦羽林兒，從戎榆关道。"]', '诗', 'shi', '', NULL, '薊北行二首 一 李希仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6627f06-2bc8-4e07-8a10-6c989f81bb40', '薊北行二首 二', '薊北行二首 二', '4954b3c6-757a-44f4-9f1e-a3693107a677', '唐', '["一身救邊速，烽火通薊門。","前軍飛鳥斷，格鬬塵沙昏。","寒日鼓聲急，單于夜將奔。","當須徇忠義，身死報國恩。"]', '["一身救邊速，烽火通薊门。","前軍飞鸟斷，格鬬塵沙昏。","寒日鼓声急，單于夜將奔。","當須徇忠義，身死報国恩。"]', '诗', 'shi', '', NULL, '薊北行二首 二 李希仲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e32ab473-2cd8-4fd9-b525-da7826d7f2dd', '送妻', '送妻', 'a530f004-bac7-4e3f-bcf6-3a23b2cbc793', '唐', '["平生志業在琴詩，頭上如今有二絲。","漁父尚知谿谷暗，山妻不信出身遲。","荆釵任意撩新鬢，明鏡從他別畫眉。","今日便同行路客，相逢即是下山時。"]', '["平生志業在琴诗，头上如今有二絲。","漁父尚知谿谷暗，山妻不信出身遲。","荆釵任意撩新鬢，明镜從他別畫眉。","今日便同行路客，相逢即是下山时。"]', '诗', 'shi', '', NULL, '送妻 楊志堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a7c9f6-9d7f-4558-9d78-c525c98d2737', '從張丞相遊南紀城獵戲贈裴迪張參軍', '從張丞相游南紀城獵戲贈裴迪張參軍', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["從禽非吾樂，不好雲夢田。","歲暮登城望，偏令相思懸。","公卿有幾幾，車騎何翩翩。","世祿金張貴，官曹幕府賢。","順時行殺氣，飛刃爭割鮮。","十里屆賓館，徵聲匝妓筵。","高標回落日，平楚散芳煙。","何意狂歌客，從公亦在旃。"]', '["從禽非吾乐，不好云梦田。","歲暮登城望，偏令相思懸。","公卿有幾幾，车騎何翩翩。","世祿金張貴，官曹幕府賢。","順时行殺氣，飞刃爭割鲜。","十里屆賓館，徵声匝妓筵。","高標回落日，平楚散芳煙。","何意狂歌客，從公亦在旃。"]', '诗', 'shi', '', NULL, '從張丞相遊南紀城獵戲贈裴迪張參軍 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5d1b3e-cadf-4c86-8b44-10dba65534cc', '登江中孤嶼贈白雲先生王迥', '登江中孤嶼贈白云先生王迥', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["悠悠清水江，水落沙嶼出。","回潭石下深，綠篠岸傍密。","鮫人潛不見，漁父歌自逸。","憶與君別時，泛舟如昨日。","夕陽開返照，中坐興非一。","南望鹿門山，歸來恨如失。"]', '["悠悠清水江，水落沙嶼出。","回潭石下深，綠篠岸傍密。","鮫人潛不见，漁父歌自逸。","憶與君別时，泛舟如昨日。","夕陽开返照，中坐兴非一。","南望鹿门山，归来恨如失。"]', '诗', 'shi', '', NULL, '登江中孤嶼贈白雲先生王迥 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d85327f-5d8a-476e-a7cd-5bac1bbb8039', '晚春臥病寄張八', '晚春臥病寄張八', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["南陌春將晚，北窗猶臥病。","林園久不遊，草木一何盛。","狹逕花障迷，閑庭竹掃淨。","翠羽戲蘭苕，赬鱗動荷柄。","念我平生好，江鄉遠從政。","雲山阻夢思，衾枕勞歌詠。","歌詠復何爲，同心恨別離。","世途皆自媚，流俗寡相知。","賈誼才空逸，安仁鬢欲絲。","遙情每東注，奔晷復西馳。","常恐填溝壑，無由振羽儀。","窮通若有命，欲向論中推。"]', '["南陌春將晚，北窗猶臥病。","林园久不游，草木一何盛。","狹逕花障迷，闲庭竹掃淨。","翠羽戲蘭苕，赬鱗动荷柄。","念我平生好，江乡远從政。","云山阻梦思，衾枕勞歌詠。","歌詠复何爲，同心恨別離。","世途皆自媚，流俗寡相知。","賈誼才空逸，安仁鬢欲絲。","遙情每东注，奔晷复西驰。","常恐填溝壑，無由振羽儀。","窮通若有命，欲向論中推。"]', '诗', 'shi', '', NULL, '晚春臥病寄張八 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56ca5b29-4bb9-4f12-9200-6bc7c72e4e47', '秋登蘭山寄張五', '秋登蘭山寄張五', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["北山白雲裏，隱者自怡悅。","相望試登高，心飛逐鳥滅。","愁因薄暮起，興是清秋發。","時見歸村人，沙行渡頭歇。","天邊樹若薺，江畔舟如月。","何當載酒來，共醉重陽節。"]', '["北山白云裏，隐者自怡悅。","相望試登高，心飞逐鸟滅。","愁因薄暮起，兴是清秋發。","时见归村人，沙行渡头歇。","天邊樹若薺，江畔舟如月。","何當載酒来，共醉重陽節。"]', '诗', 'shi', '', NULL, '秋登蘭山寄張五 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e7848e-5480-4646-ac7c-f9c90208c7d0', '入峽寄弟', '入峽寄弟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["吾昔與爾輩，讀書常閉門。","未嘗冒湍險，豈顧垂堂言。","自此歷江湖，辛勤難具論。","往來行旅弊，開鑿禹功存。","壁立千峰峻，潨流萬壑奔。","我來凡幾宿，無夕不聞猿。","浦上搖歸戀，舟中失夢魂。","淚沾明月峽，心斷鶺鴒原。","離闊星難聚，秋深露已繁。","因君下南楚，書此示鄉園。"]', '["吾昔與爾輩，读书常閉门。","未嘗冒湍險，豈顧垂堂言。","自此歷江湖，辛勤难具論。","往来行旅弊，开鑿禹功存。","壁立千峰峻，潨流万壑奔。","我来凡幾宿，無夕不闻猿。","浦上搖归戀，舟中失梦魂。","泪沾明月峽，心斷鶺鴒原。","離闊星难聚，秋深露已繁。","因君下南楚，书此示乡园。"]', '诗', 'shi', '', NULL, '入峽寄弟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88603c8f-ebce-4856-989e-d2b8e174f8a3', '湖中旅泊寄閻九司戶防', '湖中旅泊寄閻九司戶防', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["桂水通百越，扁舟期曉發。","荆雲蔽三巴，夕望不見家。","襄王夢行雨，才子謫長沙。","長沙饒瘴癘，胡爲苦留滯。","久別思款顏，承歡懷接袂。","接袂杳無由，徒增旅泊愁。","清猿不可聽，沿月下湘流。"]', '["桂水通百越，扁舟期晓發。","荆云蔽三巴，夕望不见家。","襄王梦行雨，才子謫长沙。","长沙饒瘴癘，胡爲苦留滯。","久別思款顏，承歡懷接袂。","接袂杳無由，徒增旅泊愁。","清猿不可听，沿月下湘流。"]', '诗', 'shi', '', NULL, '湖中旅泊寄閻九司戶防 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d320825-392a-4e4a-b045-dbe21c7f48cb', '大堤行寄萬七', '大堤行寄万七', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["大堤行樂處，車馬相馳突。","歲歲春草生，踏青二三月。","王孫挾珠彈，遊女矜羅襪。","攜手今莫同，江花爲誰發。"]', '["大堤行乐处，车马相驰突。","歲歲春草生，踏青二三月。","王孫挾珠彈，游女矜羅襪。","携手今莫同，江花爲誰發。"]', '诗', 'shi', '', NULL, '大堤行寄萬七 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d166f6-4858-4516-b4c7-339c6fc620ac', '仲夏歸漢南園寄京邑耆舊', '仲夏归漢南园寄京邑耆旧', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["嘗讀高士傳，最嘉陶徵君。","日耽田園趣，自謂羲皇人。","予復何爲者，棲棲徒問津。","中年廢丘壑，上國旅風塵。","忠欲事明主，孝思侍老親。","歸來當炎夏，耕稼不及春。","扇枕北窗下，采芝南澗濱。","因聲謝同列，吾慕潁陽真。"]', '["嘗读高士傳，最嘉陶徵君。","日耽田园趣，自謂羲皇人。","予复何爲者，棲棲徒问津。","中年廢丘壑，上国旅风塵。","忠欲事明主，孝思侍老親。","归来當炎夏，耕稼不及春。","扇枕北窗下，采芝南澗濱。","因声謝同列，吾慕潁陽真。"]', '诗', 'shi', '', NULL, '仲夏歸漢南園寄京邑耆舊 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524f2729-a82a-4f6b-af71-910e6b1c3c34', '題雲門山寄越府包戶曹徐起居', '題云门山寄越府包戶曹徐起居', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["我行適諸越，夢寐懷所歡。","久負獨往願，今來恣遊盤。","台嶺踐磴石，耶溪泝林湍。","捨舟入香界，登閣憩旃檀。","晴山秦望近，春水鏡湖寬。","遠懷佇應接，卑位徒勞安。","白雲日夕滯，滄海去來觀。","故國眇天末，良朋在朝端。"]', '["我行適諸越，梦寐懷所歡。","久負独往願，今来恣游盤。","台嶺踐磴石，耶溪泝林湍。","捨舟入香界，登閣憩旃檀。","晴山秦望近，春水镜湖寬。","远懷佇應接，卑位徒勞安。","白云日夕滯，滄海去来观。","故国眇天末，良朋在朝端。"]', '诗', 'shi', '', NULL, '題雲門山寄越府包戶曹徐起居 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f49fec29-bba8-41d0-b9d8-d0105982586e', '宿揚子津寄潤州長山劉隱士', '宿揚子津寄潤州长山劉隐士', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["所思在建業，欲往大江深。","日夕望京口，煙波愁我心。","心馳茅山洞，目極楓樹林。","不見少微星，星霜勞夜吟。"]', '["所思在建業，欲往大江深。","日夕望京口，煙波愁我心。","心驰茅山洞，目極楓樹林。","不见少微星，星霜勞夜吟。"]', '诗', 'shi', '', NULL, '宿揚子津寄潤州長山劉隱士 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e20f3d71-054e-48f2-a8ac-080abfe3ac85', '書懷貽京邑同好', '书懷貽京邑同好', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["維先自鄒魯，家世重儒風。","詩體襲遺訓，趨庭霑末躬。","晝夜常自强，詞翰頗亦工。","三十既成立，嗟吁命不通。","慈親向羸老，喜懼在深衷。","甘脆朝不足，簞瓢夕屢空。","執鞭慕夫子，捧檄懷毛公。","感激遂彈冠，安能守固窮。","當途訴知己，投剌匪求蒙。","秦楚邈離異，飜飛何日同。"]', '["維先自鄒魯，家世重儒风。","诗體襲遺訓，趨庭霑末躬。","晝夜常自强，词翰頗亦工。","三十既成立，嗟吁命不通。","慈親向羸老，喜懼在深衷。","甘脆朝不足，簞瓢夕屢空。","執鞭慕夫子，捧檄懷毛公。","感激遂彈冠，安能守固窮。","當途訴知己，投剌匪求蒙。","秦楚邈離異，飜飞何日同。"]', '诗', 'shi', '', NULL, '書懷貽京邑同好 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c066e0-890f-4eda-9447-f87cc29bff0c', '還山貽湛法師', '還山貽湛法師', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["幼聞無生理，常欲觀此身。","心跡罕兼遂，[崎嶇]多在塵。","晚途歸舊壑，偶與支公鄰。","導以微妙法，結爲清淨因。","煩惱業頓捨，山林情轉殷。","朝來問疑義，夕話得清真。","墨妙稱古絕，詞華驚世人。","禪房閉虛靜，花藥連冬春。","平石籍琴硯，落泉灑衣巾。","欲知冥滅意，朝夕海鷗馴。"]', '["幼闻無生理，常欲观此身。","心跡罕兼遂，[崎嶇]多在塵。","晚途归旧壑，偶與支公鄰。","導以微妙法，結爲清淨因。","煩惱業頓捨，山林情轉殷。","朝来问疑義，夕話得清真。","墨妙稱古絕，词华驚世人。","禪房閉虛静，花藥連冬春。","平石籍琴硯，落泉灑衣巾。","欲知冥滅意，朝夕海鷗馴。"]', '诗', 'shi', '', NULL, '還山貽湛法師 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8afed4e-e8cd-467f-afae-51dc149921f7', '夏日南亭懷辛大', '夏日南亭懷辛大', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["山光忽西落，池月漸東上。","散髮乘夕涼，開軒臥閑敞。","荷風送香氣，竹露滴清響。","欲取鳴琴彈，恨無知音賞。","感此懷故人，中宵勞夢想。"]', '["山光忽西落，池月漸东上。","散髮乘夕涼，开軒臥闲敞。","荷风送香氣，竹露滴清响。","欲取鳴琴彈，恨無知音賞。","感此懷故人，中宵勞梦想。"]', '诗', 'shi', '', NULL, '夏日南亭懷辛大 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0490b5-2c0b-4ce1-b9f8-ca1b553f662c', '秋宵月下有懷', '秋宵月下有懷', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["秋空明月懸，光彩露霑濕。","驚鵲棲未定，飛螢捲簾入。","庭槐寒影疎，鄰杵夜聲急。","佳期曠何許，望望空佇立。"]', '["秋空明月懸，光彩露霑濕。","驚鵲棲未定，飞螢捲簾入。","庭槐寒影疎，鄰杵夜声急。","佳期曠何許，望望空佇立。"]', '诗', 'shi', '', NULL, '秋宵月下有懷 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b6d7b6f-7371-4aad-842a-abf3d4537946', '將適天台留別臨安李主簿', '將適天台留別臨安李主簿', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["枳棘君尚棲，匏瓜吾豈繫。","念離當夏首，漂泊指炎裔。","江海非墮遊，田園失歸計。","定山既早發，漁浦亦宵濟。","泛泛隨波瀾，行行任艫枻。","故林日已遠，羣木坐成翳。","羽人在丹丘，吾亦從此逝。"]', '["枳棘君尚棲，匏瓜吾豈繫。","念離當夏首，漂泊指炎裔。","江海非墮游，田园失归計。","定山既早發，漁浦亦宵濟。","泛泛隨波瀾，行行任艫枻。","故林日已远，羣木坐成翳。","羽人在丹丘，吾亦從此逝。"]', '诗', 'shi', '', NULL, '將適天台留別臨安李主簿 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed6173a-e61e-4a96-a35e-5fe7f9c73cb4', '送丁大鳳進士赴舉呈張九齡', '送丁大鳳進士赴舉呈張九齡', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["吾觀鷦鷯賦，君負王佐才。","惜無金張援，十上空歸來。","棄置鄉園老，翻飛羽翼摧。","故人今在位，歧路莫遲回。"]', '["吾观鷦鷯賦，君負王佐才。","惜無金張援，十上空归来。","棄置乡园老，翻飞羽翼摧。","故人今在位，歧路莫遲回。"]', '诗', 'shi', '', NULL, '送丁大鳳進士赴舉呈張九齡 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f660513-b195-4797-96a7-408b446e263b', '送吳悅遊韶陽', '送吳悅游韶陽', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["五色憐鳳雛，南飛適鷓鴣。","楚人不相識，何處求椅梧。","去去日千里，茫茫天一隅。","安能與斥鷃，決起但槍榆。"]', '["五色怜鳳雛，南飞適鷓鴣。","楚人不相識，何处求椅梧。","去去日千里，茫茫天一隅。","安能與斥鷃，決起但槍榆。"]', '诗', 'shi', '', NULL, '送吳悅遊韶陽 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52873722-b3bf-4aa5-be7f-07f82986ec61', '適越留別譙縣張主簿申屠少府', '適越留別譙縣張主簿申屠少府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["朝乘汴河流，夕次譙縣界。","幸值西風吹，得與故人會。","君學梅福隱，余從伯鸞邁。","別後能相思，浮雲在吳會。"]', '["朝乘汴河流，夕次譙縣界。","幸值西风吹，得與故人會。","君学梅福隐，余從伯鸾邁。","別後能相思，浮云在吳會。"]', '诗', 'shi', '', NULL, '適越留別譙縣張主簿申屠少府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc13bd5f-5ad3-4308-8042-d3749b6c1c61', '送陳七赴西軍', '送陳七赴西軍', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["吾觀非常者，碌碌在目前。","君負鴻鵠志，蹉跎書劒年。","一聞邊烽動，萬里忽爭先。","余亦赴京國，何當獻凱還。"]', '["吾观非常者，碌碌在目前。","君負鴻鵠志，蹉跎书劒年。","一闻邊烽动，万里忽爭先。","余亦赴京国，何當獻凱還。"]', '诗', 'shi', '', NULL, '送陳七赴西軍 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a908c83-c762-412c-b00e-671e5ba131cb', '送從弟邕下第後尋會稽', '送從弟邕下第後尋會稽', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["疾風吹征帆，倏爾向空沒。","千里在俄頃，三江坐超忽。","向來共歡娛，日夕成楚越。","落羽更分飛，誰能不驚骨。"]', '["疾风吹征帆，倏爾向空沒。","千里在俄頃，三江坐超忽。","向来共歡娛，日夕成楚越。","落羽更分飞，誰能不驚骨。"]', '诗', 'shi', '', NULL, '送從弟邕下第後尋會稽 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee0206b-15bf-4a62-bdc3-bb84400d3be8', '送辛大之鄂渚不及', '送辛大之鄂渚不及', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["送君不相見，日暮獨愁緒。","江上空裴回，天邊迷處所。","郡邑經樊鄧，山河入嵩汝。","蒲輪去漸遙，石徑徒延佇。"]', '["送君不相见，日暮独愁緒。","江上空裴回，天邊迷处所。","郡邑經樊鄧，山河入嵩汝。","蒲輪去漸遙，石徑徒延佇。"]', '诗', 'shi', '', NULL, '送辛大之鄂渚不及 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6801f70a-aaf2-46ae-beab-bd2e567fc047', '江上別流人', '江上別流人', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["以我越鄉客，逢君謫居者。","分飛黃鶴樓，流落蒼梧野。","驛使乘雲去，征帆沿溜下。","不知從此分，還袂何時把。"]', '["以我越乡客，逢君謫居者。","分飞黄鹤楼，流落蒼梧野。","驛使乘云去，征帆沿溜下。","不知從此分，還袂何时把。"]', '诗', 'shi', '', NULL, '江上別流人 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5acef5-c403-43a5-a69f-97256231868c', '宴包二融宅', '宴包二融宅', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["閑居枕清洛，左右接大野。","門庭無雜賓，車轍多長者。","是時方盛夏，風物自瀟灑。","五日休沐歸，相攜竹林下。","開襟成歡趣，對酒不能罷。","煙暝棲鳥迷，余將歸白社。"]', '["闲居枕清洛，左右接大野。","门庭無杂賓，车轍多长者。","是时方盛夏，风物自瀟灑。","五日休沐归，相携竹林下。","开襟成歡趣，对酒不能罷。","煙暝棲鸟迷，余將归白社。"]', '诗', 'shi', '', NULL, '宴包二融宅 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('268aae62-5eac-44ea-8f36-f6ef9314ea6e', '與王昌齡宴王道士房', '與王昌齡宴王道士房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["歸來臥青山，常夢遊清都。","漆園有傲吏，惠好在招呼。","書幌神仙籙，畫屏山海圖。","酌霞復對此，宛似入蓬壺。"]', '["归来臥青山，常梦游清都。","漆园有傲吏，惠好在招呼。","书幌神仙籙，畫屏山海圖。","酌霞复对此，宛似入蓬壺。"]', '诗', 'shi', '', NULL, '與王昌齡宴王道士房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('395bcd77-f628-46a0-9b63-0a26fac694cc', '襄陽公宅飲', '襄陽公宅饮', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["窈窕夕陽佳，䒠茸春色好。","欲覓淹留處，無過狹斜道。","綺席卷龍鬚，香杯浮碼碯。","北林積修樹，南池生別島。","手撥金翠花，心迷玉紅草。","談笑光六義，發論明三倒。","座非陳子驚，門還魏公掃。","榮辱應無間，歡娛當共保。"]', '["窈窕夕陽佳，䒠茸春色好。","欲覓淹留处，無過狹斜道。","綺席卷龙鬚，香杯浮碼碯。","北林積修樹，南池生別島。","手撥金翠花，心迷玉紅草。","談笑光六義，發論明三倒。","座非陳子驚，门還魏公掃。","榮辱應無间，歡娛當共保。"]', '诗', 'shi', '', NULL, '襄陽公宅飲 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c2aef7-133f-4151-950e-7eea2865a9e1', '尋香山湛上人', '尋香山湛上人', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["朝遊訪名山，山遠在空翠。","氛氳亙百里，日入行始至。","杖策尋故人，解鞭暫停騎。","石門殊豁險，篁逕轉森邃。","法侶欣相逢，清談曉不寐。","平生慕真隱，累日探奇異。","野老朝入田，山僧暮歸寺。","松泉多逸響，苔壁饒古意。","谷口聞鐘聲，林端識香氣。","願言投此山，身世兩相棄。"]', '["朝游訪名山，山远在空翠。","氛氳亙百里，日入行始至。","杖策尋故人，解鞭暫停騎。","石门殊豁險，篁逕轉森邃。","法侶欣相逢，清談晓不寐。","平生慕真隐，累日探奇異。","野老朝入田，山僧暮归寺。","松泉多逸响，苔壁饒古意。","谷口闻鐘声，林端識香氣。","願言投此山，身世兩相棄。"]', '诗', 'shi', '', NULL, '尋香山湛上人 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('893eee5a-08bd-4308-b019-b7d6a692db95', '雲門寺西六七里聞符公蘭若最幽與薛八同往', '云门寺西六七里闻符公蘭若最幽與薛八同往', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["謂予獨迷方，逢子亦在野。","結交指松柏，問法尋蘭若。","小溪劣容舟，怪石屢驚馬。","所居最幽絕，所住皆靜者。","雲簇興座隅，天空落階下。","上人亦何聞，塵念都已捨。","四禪合真如，一切是虛假。","願承甘露潤，喜得惠風灑。","依止託山門，誰能效丘也。"]', '["謂予独迷方，逢子亦在野。","結交指松柏，问法尋蘭若。","小溪劣容舟，怪石屢驚马。","所居最幽絕，所住皆静者。","云簇兴座隅，天空落階下。","上人亦何闻，塵念都已捨。","四禪合真如，一切是虛假。","願承甘露潤，喜得惠风灑。","依止託山门，誰能效丘也。"]', '诗', 'shi', '', NULL, '雲門寺西六七里聞符公蘭若最幽與薛八同往 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1366a20-e085-4e4a-9a79-645be7e27a63', '宿天台桐柏觀', '宿天台桐柏观', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["海行信風帆，夕宿逗雲島。","緬尋滄洲趣，近愛赤城好。","捫蘿亦踐苔，輟櫂恣探討。","息陰憩桐柏，采秀弄芝草。","鶴唳清露垂，雞鳴信潮早。","願言解纓紱，從此去煩惱。","高步凌四明，玄蹤得三老。","紛吾遠遊意，學彼長生道。","日夕望三山，雲濤空浩浩。"]', '["海行信风帆，夕宿逗云島。","緬尋滄洲趣，近愛赤城好。","捫蘿亦踐苔，輟櫂恣探討。","息陰憩桐柏，采秀弄芝草。","鹤唳清露垂，雞鳴信潮早。","願言解纓紱，從此去煩惱。","高步凌四明，玄蹤得三老。","紛吾远游意，学彼长生道。","日夕望三山，云濤空浩浩。"]', '诗', 'shi', '', NULL, '宿天台桐柏觀 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1338a23c-19fc-4e56-b634-984b02e7fff0', '峴潭作', '峴潭作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["石潭傍隈隩，沙岸曉夤緣。","試垂竹竿釣，果得槎頭鯿。","美人騁金錯，纖手膾紅鮮。","因謝陸內史，蓴羹何足傳。"]', '["石潭傍隈隩，沙岸晓夤緣。","試垂竹竿釣，果得槎头鯿。","美人騁金錯，纖手膾紅鲜。","因謝陸內史，蓴羹何足傳。"]', '诗', 'shi', '', NULL, '峴潭作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('771875f8-d1a0-44a4-a84f-c4a2f281b5b6', '題終南翠微寺空上人房', '題終南翠微寺空上人房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["翠微終南裏，雨後宜返照。","閉關久沈冥，杖策一登眺。","遂造幽人室，始知靜者妙。","儒道雖異門，雲林頗同調。","兩心相喜得，畢景共談笑。","暝還高窗眠，時見遠山燒。","緬懷赤城標，更憶臨海嶠。","風泉有清音，何必蘇門嘯。"]', '["翠微終南裏，雨後宜返照。","閉关久沈冥，杖策一登眺。","遂造幽人室，始知静者妙。","儒道雖異门，云林頗同調。","兩心相喜得，畢景共談笑。","暝還高窗眠，时见远山燒。","緬懷赤城標，更憶臨海嶠。","风泉有清音，何必蘇门嘯。"]', '诗', 'shi', '', NULL, '題終南翠微寺空上人房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22be6369-771a-4154-b989-5328ae459209', '初春漢中漾舟', '初春漢中漾舟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["羊公峴山下，神女漢臯曲。","雪罷冰復開，春潭千丈綠。","輕舟恣來往，探翫無厭足。","波影搖妓釵，沙光逐人目。","傾杯魚鳥醉，聯句鸎花續。","良會難再逢，日入須秉燭。"]', '["羊公峴山下，神女漢臯曲。","雪罷冰复开，春潭千丈綠。","轻舟恣来往，探翫無厭足。","波影搖妓釵，沙光逐人目。","傾杯鱼鸟醉，聯句鸎花續。","良會难再逢，日入須秉燭。"]', '诗', 'shi', '', NULL, '初春漢中漾舟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e504df9-b22d-480e-9e7c-9f8ab8591b91', '宿業師山房期丁大不至', '宿業師山房期丁大不至', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["夕陽度西嶺，羣壑倏已暝。","松月生夜涼，風泉滿清聽。","樵人歸欲盡，煙鳥棲初定。","之子期宿來，孤琴候蘿逕。"]', '["夕陽度西嶺，羣壑倏已暝。","松月生夜涼，风泉满清听。","樵人归欲尽，煙鸟棲初定。","之子期宿来，孤琴候蘿逕。"]', '诗', 'shi', '', NULL, '宿業師山房期丁大不至 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83c44c92-0198-4004-892f-a1d34a6858da', '耶溪泛舟', '耶溪泛舟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["落景馀清輝，輕橈弄溪渚。","澄明愛水物，臨泛何容與。","白首垂釣翁，新妝浣紗女。","相看似相識，脉脉不得語。"]', '["落景馀清輝，轻橈弄溪渚。","澄明愛水物，臨泛何容與。","白首垂釣翁，新妝浣紗女。","相看似相識，脉脉不得語。"]', '诗', 'shi', '', NULL, '耶溪泛舟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752944d2-bcb8-4036-a780-c86fd953f2ca', '彭蠡湖中望廬山', '彭蠡湖中望廬山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["太虛生月暈，舟子知天風。","挂席候明發，眇漫平湖中。","中流見匡阜，勢壓九江雄。","黤黕容霽色，崢嶸當曉空。","香爐初上日，瀑布噴成虹。","久欲追尚子，況茲懷遠公。","我來限于役，未暇息微躬。","淮海途將半，星霜歲欲窮。","寄言巖棲者，畢趣當來同。"]', '["太虛生月暈，舟子知天风。","挂席候明發，眇漫平湖中。","中流见匡阜，勢壓九江雄。","黤黕容霽色，崢嶸當晓空。","香爐初上日，瀑布噴成虹。","久欲追尚子，況茲懷远公。","我来限于役，未暇息微躬。","淮海途將半，星霜歲欲窮。","寄言巖棲者，畢趣當来同。"]', '诗', 'shi', '', NULL, '彭蠡湖中望廬山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0236836c-e75b-4b63-bf8d-46439dc02df9', '登鹿門山', '登鹿门山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["清曉因興來，乘流越江峴。","沙禽近方識，浦樹遙莫辨。","漸至鹿門山，山明翠微淺。","巖潭多屈曲，舟檝屢回轉。","昔聞龐德公，采藥遂不返。","金澗餌芝朮，石牀臥苔蘚。","紛吾感耆舊，結攬事攀踐。","隱迹今尚存，高風邈已遠。","白雲何時去，丹桂空偃蹇。","探討意未窮，回艇夕陽晚。"]', '["清晓因兴来，乘流越江峴。","沙禽近方識，浦樹遙莫辨。","漸至鹿门山，山明翠微淺。","巖潭多屈曲，舟檝屢回轉。","昔闻龐德公，采藥遂不返。","金澗餌芝朮，石牀臥苔蘚。","紛吾感耆旧，結攬事攀踐。","隐迹今尚存，高风邈已远。","白云何时去，丹桂空偃蹇。","探討意未窮，回艇夕陽晚。"]', '诗', 'shi', '', NULL, '登鹿門山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1443129-8490-43d0-8520-63386cf8782a', '遊明禪師西山蘭若', '游明禪師西山蘭若', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["西山多奇狀，秀出倚前楹。","停午收彩翠，夕陽照分明。","吾師住其下，禪坐證無生。","結廬就嵌窟，剪苕通往行。","談空對樵叟，授法與山精。","日暮方辭去，田園歸冶城。"]', '["西山多奇狀，秀出倚前楹。","停午收彩翠，夕陽照分明。","吾師住其下，禪坐證無生。","結廬就嵌窟，剪苕通往行。","談空对樵叟，授法與山精。","日暮方辞去，田园归冶城。"]', '诗', 'shi', '', NULL, '遊明禪師西山蘭若 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('220cabf0-4db3-4bf4-9897-fdbf0a25b579', '登望楚山最高頂', '登望楚山最高頂', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["山水觀形勝，襄陽美會稽。","最高唯望楚，曾未一攀躋。","石壁疑削成，衆山比全低。","晴明試登陟，目極無端倪。","雲夢掌中小，武陵花處迷。","暝還歸騎下，蘿月映深谿。"]', '["山水观形勝，襄陽美會稽。","最高唯望楚，曾未一攀躋。","石壁疑削成，衆山比全低。","晴明試登陟，目極無端倪。","云梦掌中小，武陵花处迷。","暝還归騎下，蘿月映深谿。"]', '诗', 'shi', '', NULL, '登望楚山最高頂 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aade0f4a-6f9b-4239-85ca-725b32795b6d', '疾愈過龍泉寺精舍呈易業二公', '疾愈過龙泉寺精舍呈易業二公', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["停午聞山鐘，起行散愁疾。","尋林采芝去，轉谷松翠密。","傍見精舍開，長廊飯僧畢。","石渠流雪水，金子耀霜橘。","竹房思舊遊，過憩終永日。","入洞窺石髓，傍崖采蜂蜜。","日暮辭遠公，虎溪相送出。"]', '["停午闻山鐘，起行散愁疾。","尋林采芝去，轉谷松翠密。","傍见精舍开，长廊飯僧畢。","石渠流雪水，金子耀霜橘。","竹房思旧游，過憩終永日。","入洞窺石髓，傍崖采蜂蜜。","日暮辞远公，虎溪相送出。"]', '诗', 'shi', '', NULL, '疾愈過龍泉寺精舍呈易業二公 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34beee01-7e97-4e2d-b1df-015523f16fda', '萬山潭作', '万山潭作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["垂釣坐盤石，水清心亦閑。","魚行潭樹下，猿挂島藤間。","游女昔解佩，傳聞於此山。","求之不可得，沿月櫂歌還。"]', '["垂釣坐盤石，水清心亦闲。","鱼行潭樹下，猿挂島藤间。","游女昔解佩，傳闻於此山。","求之不可得，沿月櫂歌還。"]', '诗', 'shi', '', NULL, '萬山潭作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e92f66-319c-4cf5-b5c0-08938846a812', '與黃侍御北津泛舟', '與黄侍御北津泛舟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["津無蛟龍患，日夕常安流。","本欲避驄馬，何如同鷁舟。","豈伊今日幸，曾是昔年遊。","莫奏琴中鶴，且隨波上鷗。","隄緣九里郭，山面百城樓。","自顧躬耕者，才非管樂儔。","聞君薦草澤，從此泛滄洲。"]', '["津無蛟龙患，日夕常安流。","本欲避驄马，何如同鷁舟。","豈伊今日幸，曾是昔年游。","莫奏琴中鹤，且隨波上鷗。","隄緣九里郭，山面百城楼。","自顧躬耕者，才非管乐儔。","闻君薦草澤，從此泛滄洲。"]', '诗', 'shi', '', NULL, '與黃侍御北津泛舟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc1488a1-dbea-4dda-9917-33b19d463cc9', '洗然弟竹亭', '洗然弟竹亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["吾與二三子，平生結交深。","俱懷鴻鵠志，昔有鶺鴒心。","逸氣假毫翰，清風在竹林。","達是酒中趣，琴上偶然音。"]', '["吾與二三子，平生結交深。","俱懷鴻鵠志，昔有鶺鴒心。","逸氣假毫翰，清风在竹林。","達是酒中趣，琴上偶然音。"]', '诗', 'shi', '', NULL, '洗然弟竹亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b313eaa-8040-4f8d-b0d6-14c96c6e3e82', '山中逢道士雲公', '山中逢道士云公', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["春餘草木繁，耕種滿田園。","酌酒聊自勸，農夫安與言。","忽聞荆山子，時出桃花源。","采樵過北谷，賣藥來西村。","村煙日云夕，榛路有歸客。","杖策前相逢，依然是疇昔。","邂逅歡覯止，殷勤敘離隔。","謂予搏扶桑，輕舉振六翮。","奈何偶昌運，獨見遺草澤。","既笑接輿狂，仍憐孔丘厄。","物情趨勢利，吾道貴閑寂。","偃息西山下，門庭罕人迹。","何時還清溪，從爾鍊丹液。"]', '["春餘草木繁，耕種满田园。","酌酒聊自勸，農夫安與言。","忽闻荆山子，时出桃花源。","采樵過北谷，賣藥来西村。","村煙日云夕，榛路有归客。","杖策前相逢，依然是疇昔。","邂逅歡覯止，殷勤敘離隔。","謂予搏扶桑，轻舉振六翮。","奈何偶昌運，独见遺草澤。","既笑接輿狂，仍怜孔丘厄。","物情趨勢利，吾道貴闲寂。","偃息西山下，门庭罕人迹。","何时還清溪，從爾鍊丹液。"]', '诗', 'shi', '', NULL, '山中逢道士雲公 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('506fb234-a294-4502-805e-3843c053d7f4', '越中逢天台太乙子', '越中逢天台太乙子', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["仙穴逢羽人，停艫向前拜。","問余涉風水，何處遠行邁。","登陸尋天台，順流下吳會。","茲山夙所尚，安得問靈怪。","上逼青天高，俯臨滄海大。","雞鳴見日出，常覿仙人斾。","往來赤城中，逍遙白雲外。","莓苔異人間，瀑布當空界。","福庭長自然，華頂舊稱最。","永此從之遊，何當濟所屆。"]', '["仙穴逢羽人，停艫向前拜。","问余涉风水，何处远行邁。","登陸尋天台，順流下吳會。","茲山夙所尚，安得问靈怪。","上逼青天高，俯臨滄海大。","雞鳴见日出，常覿仙人斾。","往来赤城中，逍遙白云外。","莓苔異人间，瀑布當空界。","福庭长自然，华頂旧稱最。","永此從之游，何當濟所屆。"]', '诗', 'shi', '', NULL, '越中逢天台太乙子 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8271afe1-8fa7-4656-a5fd-2a4c9dd15df1', '家園臥疾畢太祝曜見尋', '家园臥疾畢太祝曜见尋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["伏枕舊遊曠，笙簧勞夢思。","平生重交結，迨此令人疑。","冰室無煖氣，炎雲空赫曦。","隙駒不暫駐，日聽涼蟬悲。","壯圖哀未立，斑白恨吾衰。","夫子自南楚，緬懷嵩汝期。","顧予衡茅下，兼致稟物資。","脫分趨庭禮，殷勤伐木詩。","脫君車前鞅，設我園中葵。","斗酒須寒興，明朝難重持。"]', '["伏枕旧游曠，笙簧勞梦思。","平生重交結，迨此令人疑。","冰室無煖氣，炎云空赫曦。","隙駒不暫駐，日听涼蟬悲。","壯圖哀未立，斑白恨吾衰。","夫子自南楚，緬懷嵩汝期。","顧予衡茅下，兼致稟物資。","脫分趨庭禮，殷勤伐木诗。","脫君车前鞅，設我园中葵。","斗酒須寒兴，明朝难重持。"]', '诗', 'shi', '', NULL, '家園臥疾畢太祝曜見尋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d6086c-9973-45f3-891a-56eefc3801da', '白雲先生王迥見訪', '白云先生王迥见訪', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["閑歸日無事，雲臥晝不起。","有客款柴扉，自云巢居子。","居閑好芝朮，采藥來城市。","家在鹿門山，常遊澗澤水。","手持白羽扇，脚步青芒履。","聞道鶴書徵，臨流還洗耳。"]', '["闲归日無事，云臥晝不起。","有客款柴扉，自云巢居子。","居闲好芝朮，采藥来城市。","家在鹿门山，常游澗澤水。","手持白羽扇，脚步青芒履。","闻道鹤书徵，臨流還洗耳。"]', '诗', 'shi', '', NULL, '白雲先生王迥見訪 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34976884-7b4f-4cc1-9f80-076caf259a16', '田園作', '田园作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["弊廬隔塵喧，惟先養恬素。","卜鄰近三徑，植果盈千樹。","粵余任推遷，三十猶未遇。","書劒時將晚，丘園日已暮。","晨興自多懷，晝坐常寡悟。","沖天羨鴻鵠，爭食羞雞騖。","望斷金馬門，勞歌采樵路。","鄉曲無知己，朝端乏親故。","誰能爲揚雄，一薦甘泉賦。"]', '["弊廬隔塵喧，惟先養恬素。","卜鄰近三徑，植果盈千樹。","粵余任推遷，三十猶未遇。","书劒时將晚，丘园日已暮。","晨兴自多懷，晝坐常寡悟。","沖天羨鴻鵠，爭食羞雞騖。","望斷金马门，勞歌采樵路。","乡曲無知己，朝端乏親故。","誰能爲揚雄，一薦甘泉賦。"]', '诗', 'shi', '', NULL, '田園作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab8706d-2305-4651-ae36-6d47a6bd1c78', '采樵作', '采樵作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["采樵入深山，山深樹重疊。","橋崩臥槎擁，路險垂藤接。","日落伴將稀，山風拂蘿衣。","長歌負輕策，平野望煙歸。"]', '["采樵入深山，山深樹重叠。","橋崩臥槎擁，路險垂藤接。","日落伴將稀，山风拂蘿衣。","长歌負轻策，平野望煙归。"]', '诗', 'shi', '', NULL, '采樵作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae57919c-2a2a-45a6-b931-f0aad8edacbc', '自潯陽泛舟經明海', '自潯陽泛舟經明海', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["大江分九流，淼淼成水鄉。","舟子乘利涉，往來至潯陽。","因之泛五湖，流浪經三湘。","觀濤壯枚發，弔屈痛沈湘。","魏闕心恆在，金門詔不忘。","遙憐上林雁，冰泮也回翔。"]', '["大江分九流，淼淼成水乡。","舟子乘利涉，往来至潯陽。","因之泛五湖，流浪經三湘。","观濤壯枚發，弔屈痛沈湘。","魏闕心恆在，金门詔不忘。","遙怜上林雁，冰泮也回翔。"]', '诗', 'shi', '', NULL, '自潯陽泛舟經明海 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e1e6c2-2dbb-4650-b7a7-1ec27257fe25', '早發漁浦潭', '早發漁浦潭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["東旭早光芒，渚禽已驚聒。","臥聞漁浦口，橈聲暗相撥。","日出氣象分，始知江湖闊。","美人常晏起，照影弄流沫。","飲水畏驚猿，祭魚時見獺。","舟行自無悶，況值晴景豁。"]', '["东旭早光芒，渚禽已驚聒。","臥闻漁浦口，橈声暗相撥。","日出氣象分，始知江湖闊。","美人常晏起，照影弄流沫。","饮水畏驚猿，祭鱼时见獺。","舟行自無悶，況值晴景豁。"]', '诗', 'shi', '', NULL, '早發漁浦潭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('445c47d9-3246-4217-9655-bab39a914e01', '經七里灘', '經七里灘', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["予奉垂堂誡，千金非所輕。","爲多山水樂，頻作泛舟行。","五嶽追向子，三湘弔屈平。","湖經洞庭闊，江入新安清。","復聞嚴陵瀨，乃在茲湍路。","疊障數百里，沿洄非一趣。","彩翠相氛氳，別流亂奔注。","釣磯平可坐，苔磴滑難步。","猨飲石下潭，鳥還日邊樹。","觀奇恨來晚，倚櫂惜將暮。","揮手弄潺湲，從茲洗塵慮。"]', '["予奉垂堂誡，千金非所轻。","爲多山水乐，頻作泛舟行。","五嶽追向子，三湘弔屈平。","湖經洞庭闊，江入新安清。","复闻嚴陵瀨，乃在茲湍路。","叠障數百里，沿洄非一趣。","彩翠相氛氳，別流亂奔注。","釣磯平可坐，苔磴滑难步。","猨饮石下潭，鸟還日邊樹。","观奇恨来晚，倚櫂惜將暮。","揮手弄潺湲，從茲洗塵慮。"]', '诗', 'shi', '', NULL, '經七里灘 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8d0d861-6be7-4d1b-b54d-28ab7f4b81c0', '歲暮海上作', '歲暮海上作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["仲尼既云歿，余亦浮于海。","昏見斗柄回，方知歲星改。","虛舟任所適，垂釣非有待。","爲問乘槎人，滄洲復誰在。"]', '["仲尼既云歿，余亦浮于海。","昏见斗柄回，方知歲星改。","虛舟任所適，垂釣非有待。","爲问乘槎人，滄洲复誰在。"]', '诗', 'shi', '', NULL, '歲暮海上作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d916be-1cd2-490f-84ee-3d507a1c7dac', '南歸阻雪', '南归阻雪', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["我行滯宛許，日夕望京豫。","曠野莽茫茫，鄉山在何處。","孤煙村際起，歸雁天邊去。","積雪復平臯，饑鷹捉寒兔。","少年弄文墨，屬意在章句。","十上恥還家，裴回守歸路。"]', '["我行滯宛許，日夕望京豫。","曠野莽茫茫，乡山在何处。","孤煙村際起，归雁天邊去。","積雪复平臯，饑鷹捉寒兔。","少年弄文墨，屬意在章句。","十上恥還家，裴回守归路。"]', '诗', 'shi', '', NULL, '南歸阻雪 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58e6008e-cd4a-4098-8c0f-d96e1af09d9e', '聽鄭五愔彈琴', '听鄭五愔彈琴', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["阮籍推名飲，清風滿竹林。","半酣下衫袖，拂拭龍脣琴。","一杯彈一曲，不覺夕陽沈。","予意在山水，聞之諧夙心。"]', '["阮籍推名饮，清风满竹林。","半酣下衫袖，拂拭龙脣琴。","一杯彈一曲，不覺夕陽沈。","予意在山水，闻之諧夙心。"]', '诗', 'shi', '', NULL, '聽鄭五愔彈琴 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ff81f9-2f4d-4aaf-8b42-7b7b5a97d661', '同張明府清鏡歎', '同張明府清镜歎', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["妾有盤龍鏡，清光常晝發。","自從生塵埃，有若霧中月。","愁來試取照，坐歎生白髮。","寄語邊塞人，如何久離別。"]', '["妾有盤龙镜，清光常晝發。","自從生塵埃，有若霧中月。","愁来試取照，坐歎生白髮。","寄語邊塞人，如何久離別。"]', '诗', 'shi', '', NULL, '同張明府清鏡歎 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01aa20e7-3ec5-4146-9516-d1d2242be806', '庭橘', '庭橘', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["明發覽羣物，萬木何陰森。","凝霜漸漸水，庭橘似懸金。","女伴爭攀摘，摘窺礙葉深。","竝生憐共蒂，相示感同心。","骨刺紅羅被，香黏翠羽簪。","擎來玉盤裏，全勝在幽林。"]', '["明發覽羣物，万木何陰森。","凝霜漸漸水，庭橘似懸金。","女伴爭攀摘，摘窺礙葉深。","竝生怜共蒂，相示感同心。","骨刺紅羅被，香黏翠羽簪。","擎来玉盤裏，全勝在幽林。"]', '诗', 'shi', '', NULL, '庭橘 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55031508-e6f7-4322-b449-f4e23d321e4d', '早梅', '早梅', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["園中有早梅，年例犯寒開。","少婦曾攀折，將歸插鏡臺。","猶言看不足，更欲剪刀裁。"]', '["园中有早梅，年例犯寒开。","少婦曾攀折，將归插镜台。","猶言看不足，更欲剪刀裁。"]', '诗', 'shi', '', NULL, '早梅 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c4db3a-f443-4b13-8768-3502b5b8e002', '清明即事', '清明即事', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["帝里重清明，人心自愁思。","車聲上路合，柳色東城翠。","花落草齊生，鸎飛蝶雙戲。","空堂坐相憶，酌茗聊代醉。"]', '["帝里重清明，人心自愁思。","车声上路合，柳色东城翠。","花落草齊生，鸎飞蝶雙戲。","空堂坐相憶，酌茗聊代醉。"]', '诗', 'shi', '', NULL, '清明即事 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0710b58a-d326-462e-893e-767cb053d0d4', '和盧明府送鄭十三還京兼寄之什', '和盧明府送鄭十三還京兼寄之什', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["昔時風景登臨地，今日衣冠送別筵。","醉坐自傾彭澤酒，思歸長望白雲天。","洞庭一葉驚秋早，濩落空嗟滯江島。","寄語朝廷當世人，何時重見長安道。"]', '["昔时风景登臨地，今日衣冠送別筵。","醉坐自傾彭澤酒，思归长望白云天。","洞庭一葉驚秋早，濩落空嗟滯江島。","寄語朝廷當世人，何时重见长安道。"]', '诗', 'shi', '', NULL, '和盧明府送鄭十三還京兼寄之什 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b495a1e-d43e-476f-8e9c-3864d042c649', '高陽池送朱二', '高陽池送朱二', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["當昔襄陽雄盛時，山公常醉習家池。","池邊釣女日相隨，妝成照影競來窺。","澄波澹澹芙蓉發，綠岸毿毿楊柳垂。","一朝物變人亦非，四面荒涼人徑稀。","意氣豪華何處在，空餘草露濕羅衣。","此地朝來餞行者，翻向此中牧征馬。","征馬分飛日漸斜，見此空爲人所嗟。","殷勤爲訪桃源路，予亦歸來松子家。"]', '["當昔襄陽雄盛时，山公常醉習家池。","池邊釣女日相隨，妝成照影競来窺。","澄波澹澹芙蓉發，綠岸毿毿楊柳垂。","一朝物变人亦非，四面荒涼人徑稀。","意氣豪华何处在，空餘草露濕羅衣。","此地朝来餞行者，翻向此中牧征马。","征马分飞日漸斜，见此空爲人所嗟。","殷勤爲訪桃源路，予亦归来松子家。"]', '诗', 'shi', '', NULL, '高陽池送朱二 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e13edf-da16-4e83-88d4-b8efe6b40415', '鸚鵡洲送王九之江左', '鸚鵡洲送王九之江左', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["昔登江上黃鶴樓，遙愛江中鸚鵡洲。","洲勢逶迤遶碧流，鴛鴦鸂鶒滿灘頭。","灘頭日落沙磧長，金沙熠熠動飆光。","舟人牽錦纜，浣女結羅裳。","月明全見蘆花白，風起遙聞杜若香，君行采采莫相忘。"]', '["昔登江上黄鹤楼，遙愛江中鸚鵡洲。","洲勢逶迤遶碧流，鴛鴦鸂鶒满灘头。","灘头日落沙磧长，金沙熠熠动飆光。","舟人牽錦纜，浣女結羅裳。","月明全见蘆花白，风起遙闻杜若香，君行采采莫相忘。"]', '诗', 'shi', '', NULL, '鸚鵡洲送王九之江左 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dbac132-ef59-4538-9643-603c63452311', '送王七尉松滋得陽臺雲', '送王七尉松滋得陽台云', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["君不見巫山神女作行雲，霏紅沓翠曉氛氳。","嬋娟流入楚王夢，倏忽還隨零雨分。","空中飛去復飛來，朝朝暮暮下陽臺。","愁君此去爲仙尉，便逐行雲去不回。"]', '["君不见巫山神女作行云，霏紅沓翠晓氛氳。","嬋娟流入楚王梦，倏忽還隨零雨分。","空中飞去复飞来，朝朝暮暮下陽台。","愁君此去爲仙尉，便逐行云去不回。"]', '诗', 'shi', '', NULL, '送王七尉松滋得陽臺雲 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0e7ac3-bde4-4491-8ae5-027106709e72', '夜歸鹿門山歌', '夜归鹿门山歌', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["山寺鐘鳴晝已昏，漁梁渡頭爭渡喧。","人隨沙路向江村，余亦乘舟歸鹿門。","鹿門月照開煙樹，忽到龐公棲隱處。","巖扉松徑長寂寥，惟有幽人夜來去。"]', '["山寺鐘鳴晝已昏，漁梁渡头爭渡喧。","人隨沙路向江村，余亦乘舟归鹿门。","鹿门月照开煙樹，忽到龐公棲隐处。","巖扉松徑长寂寥，惟有幽人夜来去。"]', '诗', 'shi', '', NULL, '夜歸鹿門山歌 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e193b15-1a2b-4c6e-a64a-23c4eadfbab2', '長樂宮', '长乐宮', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["秦城舊來稱窈窕，漢家更衣應不少。","紅粉邀君在何處，青樓苦夜長難曉。","長樂宮中鐘暗來，可憐歌舞慣相催。","歡娛此事今寂寞，惟有年年陵樹哀。"]', '["秦城旧来稱窈窕，漢家更衣應不少。","紅粉邀君在何处，青楼苦夜长难晓。","长乐宮中鐘暗来，可怜歌舞慣相催。","歡娛此事今寂寞，惟有年年陵樹哀。"]', '诗', 'shi', '', NULL, '長樂宮 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165d393f-99c7-4e2f-acb7-96be6e186524', '示孟郊', '示孟郊', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["蔓草蔽極野，蘭芝結孤根。","衆音何其繁，伯牙獨不喧。","當時高深意，舉世無能分。","鍾期一見知，山水千秋聞。","爾其保靜節，薄俗徒云云。"]', '["蔓草蔽極野，蘭芝結孤根。","衆音何其繁，伯牙独不喧。","當时高深意，舉世無能分。","鍾期一见知，山水千秋闻。","爾其保静節，薄俗徒云云。"]', '诗', 'shi', '', NULL, '示孟郊 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51192c53-8821-4948-929a-2ddb51766821', '和張丞相春朝對雪', '和張丞相春朝对雪', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["迎氣當春至，承恩喜雪來。","潤從河漢下，花逼豔陽開。","不覩豐年瑞，焉知燮理才。","撒鹽如可擬，願糝和羹梅。"]', '["迎氣當春至，承恩喜雪来。","潤從河漢下，花逼豔陽开。","不覩豐年瑞，焉知燮理才。","撒鹽如可擬，願糝和羹梅。"]', '诗', 'shi', '', NULL, '和張丞相春朝對雪 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('409f2e08-6ed5-45f7-8979-e19bb732f1b1', '和張明府登鹿門作', '和張明府登鹿门作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["忽示登高作，能寬旅寓情。","弦歌既多暇，山水思微清。","草得風光動，虹因雨氣成。","謬承巴里和，非敢應同聲。"]', '["忽示登高作，能寬旅寓情。","弦歌既多暇，山水思微清。","草得风光动，虹因雨氣成。","謬承巴里和，非敢應同声。"]', '诗', 'shi', '', NULL, '和張明府登鹿門作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ddbbcdc-df32-4238-9382-52f059514ff2', '和張二自穰縣還途中遇雪', '和張二自穰縣還途中遇雪', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["風吹沙海雪，漸作柳園春。","宛轉隨香騎，輕盈伴玉人。","歌疑郢中客，態比洛川神。","今日南歸楚，雙飛似入秦。"]', '["风吹沙海雪，漸作柳园春。","宛轉隨香騎，轻盈伴玉人。","歌疑郢中客，態比洛川神。","今日南归楚，雙飞似入秦。"]', '诗', 'shi', '', NULL, '和張二自穰縣還途中遇雪 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f97d0ffb-0341-4d90-bfb8-cff3c4b5ddfd', '和賈主簿弁九日登峴山', '和賈主簿弁九日登峴山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["楚萬重陽日，羣公賞讌來。","共乘休沐暇，同醉菊花杯。","逸思高秋發，歡情落景催。","國人咸寡和，遙媿洛陽才。"]', '["楚万重陽日，羣公賞讌来。","共乘休沐暇，同醉菊花杯。","逸思高秋發，歡情落景催。","国人咸寡和，遙媿洛陽才。"]', '诗', 'shi', '', NULL, '和賈主簿弁九日登峴山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6975adab-25d0-40c6-af3a-3a05847e7717', '望洞庭湖贈張丞相', '望洞庭湖贈張丞相', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["八月湖水平，涵虛混太清。","氣蒸雲夢澤，波撼岳陽城。","欲濟無舟楫，端居恥聖明。","坐觀垂釣者，空有羨魚情。"]', '["八月湖水平，涵虛混太清。","氣蒸云梦澤，波撼岳陽城。","欲濟無舟楫，端居恥聖明。","坐观垂釣者，空有羨鱼情。"]', '诗', 'shi', '', NULL, '望洞庭湖贈張丞相 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d917d875-586b-414c-842f-753be5c6341d', '贈道士參寥', '贈道士參寥', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["蜀琴久不弄，玉匣細塵生。","絲脆弦將斷，金徽色尚榮。","知音徒自惜，聾俗本相輕。","不遇鍾期聽，誰知鸞鳳聲。"]', '["蜀琴久不弄，玉匣細塵生。","絲脆弦將斷，金徽色尚榮。","知音徒自惜，聾俗本相轻。","不遇鍾期听，誰知鸾鳳声。"]', '诗', 'shi', '', NULL, '贈道士參寥 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c87cf33e-e4cd-4a14-b2e8-23f825a963ec', '京還贈張維', '京還贈張維', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["拂衣何處去，高枕南山南。","欲徇五斗祿，其如七不堪。","早朝非晚起，束帶異抽簪。","因向智者說，遊魚思舊潭。"]', '["拂衣何处去，高枕南山南。","欲徇五斗祿，其如七不堪。","早朝非晚起，束带異抽簪。","因向智者说，游鱼思旧潭。"]', '诗', 'shi', '', NULL, '京還贈張維 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c363732-3fc9-4a9d-8ef2-526b78f2a947', '題李十四莊兼贈綦毋校書', '題李十四莊兼贈綦毋校书', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["聞君息陰地，東郭柳林間。","左右瀍澗水，門庭緱氏山。","抱琴來取醉，垂釣坐乘閑。","歸客莫相待，尋源殊未還。"]', '["闻君息陰地，东郭柳林间。","左右瀍澗水，门庭緱氏山。","抱琴来取醉，垂釣坐乘闲。","归客莫相待，尋源殊未還。"]', '诗', 'shi', '', NULL, '題李十四莊兼贈綦毋校書 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5290d79a-2997-4b2b-94de-7193b71ba36b', '九日龍沙作寄劉大眘虛', '九日龙沙作寄劉大眘虛', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["龍沙豫章北，九日挂帆過。","風俗因時見，湖山發興多。","客中誰送酒，櫂裏自成歌。","歌竟乘流去，滔滔任夕波。"]', '["龙沙豫章北，九日挂帆過。","风俗因时见，湖山發兴多。","客中誰送酒，櫂裏自成歌。","歌竟乘流去，滔滔任夕波。"]', '诗', 'shi', '', NULL, '九日龍沙作寄劉大眘虛 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a65364-18ab-4d5b-916e-92ed2aacc757', '寄趙正字', '寄趙正字', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["正字芸香閣，幽人竹素園。","經過宛如昨，歸臥寂無喧。","高鳥能擇木，羚羊漫觸藩。","物情今已見，從此願忘言。"]', '["正字芸香閣，幽人竹素园。","經過宛如昨，归臥寂無喧。","高鸟能擇木，羚羊漫觸藩。","物情今已见，從此願忘言。"]', '诗', 'shi', '', NULL, '寄趙正字 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ebb556e-539d-481d-9308-b64453ce702b', '洞庭湖寄閻九', '洞庭湖寄閻九', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["洞庭秋正闊，余欲泛歸船。","莫辨荆吳地，唯餘水共天。","渺瀰江樹沒，合沓海潮連。","遲爾爲舟楫，相將濟巨川。"]', '["洞庭秋正闊，余欲泛归船。","莫辨荆吳地，唯餘水共天。","渺瀰江樹沒，合沓海潮連。","遲爾爲舟楫，相將濟巨川。"]', '诗', 'shi', '', NULL, '洞庭湖寄閻九 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0613f575-4f07-4326-8591-603fb3d1da45', '秦中感秋寄遠上人', '秦中感秋寄远上人', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["一丘常欲臥，三徑苦無資。","北土非吾願，東林懷我師。","黃金然桂盡，壯志逐年衰。","日夕涼風至，聞蟬但益悲。"]', '["一丘常欲臥，三徑苦無資。","北土非吾願，东林懷我師。","黄金然桂尽，壯志逐年衰。","日夕涼风至，闻蟬但益悲。"]', '诗', 'shi', '', NULL, '秦中感秋寄遠上人 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e54d3a06-8591-4a33-8c6b-05c2fff77b45', '宿永嘉江寄山陰崔少府國輔', '宿永嘉江寄山陰崔少府国輔', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["我行窮水國，君使入京華。","相去日千里，孤帆天一涯。","臥聞海潮至，起視江月斜。"]', '["我行窮水国，君使入京华。","相去日千里，孤帆天一涯。","臥闻海潮至，起視江月斜。"]', '诗', 'shi', '', NULL, '宿永嘉江寄山陰崔少府國輔 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4424d55d-0179-4785-9660-4c8df95419c5', '上巳洛中寄王九迥', '上巳洛中寄王九迥', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["卜洛成周地，浮杯上巳筵。","鬬雞寒食下，走馬射堂前。","垂柳金堤合，平沙翠幕連。","不知王逸少，何處會羣賢。"]', '["卜洛成周地，浮杯上巳筵。","鬬雞寒食下，走马射堂前。","垂柳金堤合，平沙翠幕連。","不知王逸少，何处會羣賢。"]', '诗', 'shi', '', NULL, '上巳洛中寄王九迥 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed983c5a-2e44-40b1-8393-93b64c6820f9', '聞裴侍御朏自襄州司戶除豫州司戶因以投寄', '闻裴侍御朏自襄州司戶除豫州司戶因以投寄', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["故人荆府掾，尚有柏臺威。","移職自樊衍，芳聲聞帝畿。","昔余臥林巷，載酒過柴扉。","松菊無時賞，鄉園欲懶歸。"]', '["故人荆府掾，尚有柏台威。","移職自樊衍，芳声闻帝畿。","昔余臥林巷，載酒過柴扉。","松菊無时賞，乡园欲懶归。"]', '诗', 'shi', '', NULL, '聞裴侍御朏自襄州司戶除豫州司戶因以投寄 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfae0d5d-d438-4aba-aa2d-436880c795cd', '江上寄山陰崔少府國輔', '江上寄山陰崔少府国輔', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["春堤楊柳發，憶與故人期。","草木本無意，榮枯自有時。","山陰定遠近，江上日相思。","不及蘭亭會，空吟祓禊詩。"]', '["春堤楊柳發，憶與故人期。","草木本無意，榮枯自有时。","山陰定远近，江上日相思。","不及蘭亭會，空吟祓禊诗。"]', '诗', 'shi', '', NULL, '江上寄山陰崔少府國輔 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a60a215-c9ac-4290-9870-84f852b0f537', '夜泊廬江聞故人在東寺以詩寄之', '夜泊廬江闻故人在东寺以诗寄之', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["江路經廬阜，松門入虎谿。","聞君尋寂樂，清夜宿招提。","石鏡山精怯，禪枝怖鴿棲。","一燈如悟道，爲照客心迷。"]', '["江路經廬阜，松门入虎谿。","闻君尋寂乐，清夜宿招提。","石镜山精怯，禪枝怖鴿棲。","一灯如悟道，爲照客心迷。"]', '诗', 'shi', '', NULL, '夜泊廬江聞故人在東寺以詩寄之 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1dad78c-4dd8-4b99-b37b-741ed761f26a', '宿桐廬江寄廣陵舊遊', '宿桐廬江寄廣陵旧游', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["山暝聞猿愁，滄江急夜流。","風鳴兩岸葉，月照一孤舟。","建德非吾土，維揚憶舊遊。","還將兩行淚，遙寄海西頭。"]', '["山暝闻猿愁，滄江急夜流。","风鳴兩岸葉，月照一孤舟。","建德非吾土，維揚憶旧游。","還將兩行泪，遙寄海西头。"]', '诗', 'shi', '', NULL, '宿桐廬江寄廣陵舊遊 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f88c34b-1018-4218-a9a6-5a92e79ac637', '南還舟中寄袁太祝', '南還舟中寄袁太祝', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["沿泝非便習，風波厭苦辛。","忽聞遷谷鳥，來報五陵春。","嶺北回征帆，巴東問故人。","桃源何處是，遊子正迷津。"]', '["沿泝非便習，风波厭苦辛。","忽闻遷谷鸟，来報五陵春。","嶺北回征帆，巴东问故人。","桃源何处是，游子正迷津。"]', '诗', 'shi', '', NULL, '南還舟中寄袁太祝 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd3c576b-1fa2-4505-bc95-7556193d67f6', '東陂遇雨率爾貽謝南池', '东陂遇雨率爾貽謝南池', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["田家春事起，丁壯就東陂。","殷殷雷聲作，森森雨足垂。","海虹晴始見，河柳潤初移。","予意在耕鑿，因君問土宜。"]', '["田家春事起，丁壯就东陂。","殷殷雷声作，森森雨足垂。","海虹晴始见，河柳潤初移。","予意在耕鑿，因君问土宜。"]', '诗', 'shi', '', NULL, '東陂遇雨率爾貽謝南池 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0a1a53-c25f-4ab2-9a62-4bfa8e60b0d6', '行至汝墳寄盧徵君', '行至汝墳寄盧徵君', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["行乏憩予駕，依然見汝墳。","洛川方罷雪，嵩嶂有殘雲。","曳曳半空裏，明明五色分。","聊題一時興，因寄盧徵君。"]', '["行乏憩予駕，依然见汝墳。","洛川方罷雪，嵩嶂有殘云。","曳曳半空裏，明明五色分。","聊題一时兴，因寄盧徵君。"]', '诗', 'shi', '', NULL, '行至汝墳寄盧徵君 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0c3a46-8e2f-467e-a93d-8b28da121a51', '寄天台道士', '寄天台道士', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["海上求仙客，三山望幾時。","焚香宿華頂，裛露采靈芝。","屢躡莓苔滑，將尋汗漫期。","倘因松子去，長與世人辭。"]', '["海上求仙客，三山望幾时。","焚香宿华頂，裛露采靈芝。","屢躡莓苔滑，將尋汗漫期。","倘因松子去，长與世人辞。"]', '诗', 'shi', '', NULL, '寄天台道士 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e4d9b9-671b-4e85-b425-9ebe6009d1e8', '唐城館中早發寄楊使君', '唐城館中早發寄楊使君', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["犯霜驅曉駕，數里見唐城。","旅館歸心逼，荒村客思盈。","訪人留後信，策蹇赴前程。","欲識離魂斷，長空聽雁聲。"]', '["犯霜驱晓駕，數里见唐城。","旅館归心逼，荒村客思盈。","訪人留後信，策蹇赴前程。","欲識離魂斷，长空听雁声。"]', '诗', 'shi', '', NULL, '唐城館中早發寄楊使君 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ace890-c01e-4336-bb15-3678b9ee5937', '澗南即事貽皎上人', '澗南即事貽皎上人', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["弊廬在郭外，素產惟田園。","左右林野曠，不聞朝市喧。","釣竿垂北澗，樵唱入南軒。","書取幽棲事，將尋靜者論。"]', '["弊廬在郭外，素產惟田园。","左右林野曠，不闻朝市喧。","釣竿垂北澗，樵唱入南軒。","书取幽棲事，將尋静者論。"]', '诗', 'shi', '', NULL, '澗南即事貽皎上人 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b0bd05-ca33-4464-b8f3-878cdc829016', '重酬李少府見贈', '重酬李少府见贈', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["養疾衡簷下，由來浩氣真。","五行將禁火，十步任尋春。","致敬惟桑梓，邀歡即主人。","回看後彫色，青翠有松筠。"]', '["養疾衡簷下，由来浩氣真。","五行將禁火，十步任尋春。","致敬惟桑梓，邀歡即主人。","回看後彫色，青翠有松筠。"]', '诗', 'shi', '', NULL, '重酬李少府見贈 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811368c7-06fb-4de0-b8a4-2af293cf0d4c', '九日懷襄陽', '九日懷襄陽', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["去國似如昨，倏然經杪秋。","峴山不可見，風景令人愁。","誰采籬下菊，應閑池上樓。","宜城多美酒，歸與葛彊遊。"]', '["去国似如昨，倏然經杪秋。","峴山不可见，风景令人愁。","誰采籬下菊，應闲池上楼。","宜城多美酒，归與葛彊游。"]', '诗', 'shi', '', NULL, '九日懷襄陽 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eccf8c0-9664-4a4c-ba4c-71942bd3d5c9', '初出關旅亭夜坐懷王大校書', '初出关旅亭夜坐懷王大校书', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["向夕槐煙起，蔥蘢池館曛。","客中無偶坐，關外惜離羣。","燭至螢光滅，荷枯雨滴聞。","永懷芸閣友，寂寞滯[揚]雲。"]', '["向夕槐煙起，蔥蘢池館曛。","客中無偶坐，关外惜離羣。","燭至螢光滅，荷枯雨滴闻。","永懷芸閣友，寂寞滯[揚]云。"]', '诗', 'shi', '', NULL, '初出關旅亭夜坐懷王大校書 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('258a24ef-f6c4-4d4a-a5f8-75274a7ec3a5', '人日登南陽驛門亭子懷漢川諸友', '人日登南陽驛门亭子懷漢川諸友', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["朝來登陟處，不似豔陽時。","異縣殊風物，羈懷多所思。","剪花驚歲早，看柳訝春遲。","未有南飛雁，裁書欲寄誰。"]', '["朝来登陟处，不似豔陽时。","異縣殊风物，羈懷多所思。","剪花驚歲早，看柳訝春遲。","未有南飞雁，裁书欲寄誰。"]', '诗', 'shi', '', NULL, '人日登南陽驛門亭子懷漢川諸友 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e18183e-5a58-4805-b672-1726969d6526', '早寒江上有懷', '早寒江上有懷', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["木落雁南度，北風江上寒。","我家襄水上，遙隔楚雲端。","鄉淚客中盡，孤帆天際看。","迷津欲有問，平海夕漫漫。"]', '["木落雁南度，北风江上寒。","我家襄水上，遙隔楚云端。","乡泪客中尽，孤帆天際看。","迷津欲有问，平海夕漫漫。"]', '诗', 'shi', '', NULL, '早寒江上有懷 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db81cdd3-a240-4b47-b8d6-e54e3c59ac1a', '閑園懷蘇子', '闲园懷蘇子', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["林園雖少事，幽獨自多違。","向夕開簾坐，庭陰落景微。","鳥過煙樹宿，螢傍水軒飛。","感念同懷子，京華去不歸。"]', '["林园雖少事，幽独自多違。","向夕开簾坐，庭陰落景微。","鸟過煙樹宿，螢傍水軒飞。","感念同懷子，京华去不归。"]', '诗', 'shi', '', NULL, '閑園懷蘇子 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a700f2fb-51fb-4886-8cc8-1c6565ee9c45', '同盧明府餞張郎中除義王府司馬海園作', '同盧明府餞張郎中除義王府司马海园作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["上國山河列，賢王邸第開。","故人分職去，潘令寵行來。","冠蓋趨梁苑，江湘失楚材。","豫愁軒騎動，賓客散池臺。"]', '["上国山河列，賢王邸第开。","故人分職去，潘令寵行来。","冠蓋趨梁苑，江湘失楚材。","豫愁軒騎动，賓客散池台。"]', '诗', 'shi', '', NULL, '同盧明府餞張郎中除義王府司馬海園作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('979af412-5c5f-4252-9134-e42de27da386', '送張子容進士赴舉', '送張子容進士赴舉', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["夕曛山照滅，送客出柴門。","惆悵野中別，殷勤岐路言。","茂林予偃息，喬木爾飛翻。","無使谷風誚，須令友道存。"]', '["夕曛山照滅，送客出柴门。","惆悵野中別，殷勤岐路言。","茂林予偃息，喬木爾飞翻。","無使谷风誚，須令友道存。"]', '诗', 'shi', '', NULL, '送張子容進士赴舉 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e114ed7-43c7-4362-b26d-fa3e003e2e40', '送張參明經舉兼向涇州覲省', '送張參明經舉兼向涇州覲省', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["十五綵衣年，承歡慈母前。","孝廉因歲貢，懷橘向秦川。","四座推文舉，中郎許仲宣。","泛舟江上別，誰不仰神仙。"]', '["十五綵衣年，承歡慈母前。","孝廉因歲貢，懷橘向秦川。","四座推文舉，中郎許仲宣。","泛舟江上別，誰不仰神仙。"]', '诗', 'shi', '', NULL, '送張參明經舉兼向涇州覲省 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a85b668-87ea-4e34-a0fc-8f35290cd205', '送張祥之房陵', '送張祥之房陵', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["我家南渡頭，慣習野人舟。","日夕弄清淺，林湍逆上流。","山河據形勝，天地生豪酋。","君意在利往，知音期自投。"]', '["我家南渡头，慣習野人舟。","日夕弄清淺，林湍逆上流。","山河據形勝，天地生豪酋。","君意在利往，知音期自投。"]', '诗', 'shi', '', NULL, '送張祥之房陵 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b2a6b7-1588-463e-82c4-fc1d85d42778', '送吳宣從事', '送吳宣從事', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["才有幕中士，寧無塞上勳。","漢兵將滅虜，王粲始從軍。","旌斾邊庭去，山川地脉分。","平生一匕首，感激贈夫君。"]', '["才有幕中士，寧無塞上勳。","漢兵將滅虜，王粲始從軍。","旌斾邊庭去，山川地脉分。","平生一匕首，感激贈夫君。"]', '诗', 'shi', '', NULL, '送吳宣從事 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7a009ac-e24e-49db-b9cd-906b490c475a', '送桓子之郢城禮', '送桓子之郢城禮', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["聞君馳綵騎，躞蹀指南荆。","爲結潘楊好，言過鄢郢城。","摽梅詩有贈，羔雁禮將行。","今夜神仙女，應來感夢情。"]', '["闻君驰綵騎，躞蹀指南荆。","爲結潘楊好，言過鄢郢城。","摽梅诗有贈，羔雁禮將行。","今夜神仙女，應来感梦情。"]', '诗', 'shi', '', NULL, '送桓子之郢城禮 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4cacb5-cde8-40de-9b14-e223879cc2f4', '留別王侍御維', '留別王侍御維', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["寂寂竟何待，朝朝空自歸。","欲尋芳草去，惜與故人違。","當路誰相假，知音世所稀。","秪應守索寞，還掩故園扉。"]', '["寂寂竟何待，朝朝空自归。","欲尋芳草去，惜與故人違。","當路誰相假，知音世所稀。","秪應守索寞，還掩故园扉。"]', '诗', 'shi', '', NULL, '留別王侍御維 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2763c49-0c78-482f-abd0-bc341079771b', '早春潤州送從弟還鄉', '早春潤州送從弟還乡', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["兄弟遊吳國，庭闈戀楚關。","已多新歲感，更餞白眉還。","歸泛西江水，離筵北固山。","鄉園欲有贈，梅柳著先攀。"]', '["兄弟游吳国，庭闈戀楚关。","已多新歲感，更餞白眉還。","归泛西江水，離筵北固山。","乡园欲有贈，梅柳著先攀。"]', '诗', 'shi', '', NULL, '早春潤州送從弟還鄉 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7af3c0b-3b9d-4c79-bb31-1c8786680fdd', '峴山餞房琯崔宗之', '峴山餞房琯崔宗之', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["貴賤平生隔，軒車是日來。","青陽一覯止，雲路豁然開。","祖道衣冠列，分亭驛騎催。","方期九日聚，還待二星回。"]', '["貴賤平生隔，軒车是日来。","青陽一覯止，云路豁然开。","祖道衣冠列，分亭驛騎催。","方期九日聚，還待二星回。"]', '诗', 'shi', '', NULL, '峴山餞房琯崔宗之 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77ca368-a416-4c01-a436-b5d1d3ead16b', '送謝錄事之越', '送謝錄事之越', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["清旦江天迥，涼風西北吹。","白雲向吳會，征帆亦相隨。","想到耶溪日，應探禹穴奇。","仙書倘相示，予在此山陲。"]', '["清旦江天迥，涼风西北吹。","白云向吳會，征帆亦相隨。","想到耶溪日，應探禹穴奇。","仙书倘相示，予在此山陲。"]', '诗', 'shi', '', NULL, '送謝錄事之越 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849e9bc2-5db4-49ab-a177-61b0ed446705', '洛中送奚三還揚州', '洛中送奚三還揚州', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["水國無邊際，舟行共使風。","羨君從此去，朝夕見鄉中。","予亦離家久，南歸恨不同。","音書若有問，江上會相逢。"]', '["水国無邊際，舟行共使风。","羨君從此去，朝夕见乡中。","予亦離家久，南归恨不同。","音书若有问，江上會相逢。"]', '诗', 'shi', '', NULL, '洛中送奚三還揚州 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09a0f790-c9d1-4fa4-9029-87c601a34a0d', '送告八從軍', '送告八從軍', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["男兒一片氣，何必五車書。","好勇方過我，多才便起予。","運籌將入幕，養拙就閑居。","正待功名遂，從君繼兩疎。"]', '["男兒一片氣，何必五车书。","好勇方過我，多才便起予。","運籌將入幕，養拙就闲居。","正待功名遂，從君繼兩疎。"]', '诗', 'shi', '', NULL, '送告八從軍 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e221150-d0e2-44b8-b6e7-e4a791090b07', '送元公之鄂渚尋觀主張驂鸞', '送元公之鄂渚尋观主張驂鸾', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["桃花春水漲，之子忽乘流。","峴首辭蛟浦，江中問鶴樓。","贈君青竹杖，送爾白蘋洲。","應是神仙子，相期汗漫遊。"]', '["桃花春水漲，之子忽乘流。","峴首辞蛟浦，江中问鹤楼。","贈君青竹杖，送爾白蘋洲。","應是神仙子，相期汗漫游。"]', '诗', 'shi', '', NULL, '送元公之鄂渚尋觀主張驂鸞 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca9800b7-d993-466d-90f1-7a51e80c3bb6', '送王五昆季省覲', '送王五昆季省覲', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["公子戀庭闈，勞歌涉海涯。","水乘舟檝去，親望老萊歸。","斜日催烏鳥，清江照綵衣。","平生急難意，遙仰鶺鴒飛。"]', '["公子戀庭闈，勞歌涉海涯。","水乘舟檝去，親望老萊归。","斜日催烏鸟，清江照綵衣。","平生急难意，遙仰鶺鴒飞。"]', '诗', 'shi', '', NULL, '送王五昆季省覲 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ab6d41d-b049-46b6-befa-1f34a9ff39a4', '送崔遏', '送崔遏', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["片玉來誇楚，治中作主人。","江山增潤色，詞賦動陽春。","別館當虛敞，離情任吐伸。","因聲兩京舊，誰念臥漳濱。"]', '["片玉来誇楚，治中作主人。","江山增潤色，词賦动陽春。","別館當虛敞，離情任吐伸。","因声兩京旧，誰念臥漳濱。"]', '诗', 'shi', '', NULL, '送崔遏 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6954689c-9081-45d8-960c-3d587b079a6a', '送盧少府使入秦', '送盧少府使入秦', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["楚關望秦國，相去千里餘。","州縣勤王事，山河轉使車。","祖筵江上列，離恨別前書。","願及芳年賞，嬌鶯二月初。"]', '["楚关望秦国，相去千里餘。","州縣勤王事，山河轉使车。","祖筵江上列，離恨別前书。","願及芳年賞，嬌鶯二月初。"]', '诗', 'shi', '', NULL, '送盧少府使入秦 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bedf7d6-42ff-49b2-980f-7d451e1cb90d', '送袁十嶺南尋弟', '送袁十嶺南尋弟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["早聞牛渚詠，今見鶺鴒心。","羽翼嗟零落，悲鳴別故林。","蒼梧白雲遠，煙水洞庭深。","萬里獨飛去，南風遲爾音。"]', '["早闻牛渚詠，今见鶺鴒心。","羽翼嗟零落，悲鳴別故林。","蒼梧白云远，煙水洞庭深。","万里独飞去，南风遲爾音。"]', '诗', 'shi', '', NULL, '送袁十嶺南尋弟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051e7f83-3873-4fa7-9819-e8f6d0dcf204', '永嘉別張子容', '永嘉別張子容', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["舊國余歸楚，新年子北征。","挂帆愁海路，分手戀朋情。","日夕故園意，汀洲春草生。"]', '["旧国余归楚，新年子北征。","挂帆愁海路，分手戀朋情。","日夕故园意，汀洲春草生。"]', '诗', 'shi', '', NULL, '永嘉別張子容 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf8c5c3-1478-4ad7-a85d-55e1351a766d', '東京留別諸公', '东京留別諸公', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["吾道昧所適，驅車還向東。","主人開舊館，留客醉新豐。","樹繞溫泉綠，塵遮晚日紅。","拂衣從此去，高步躡華嵩。"]', '["吾道昧所適，驱车還向东。","主人开旧館，留客醉新豐。","樹繞溫泉綠，塵遮晚日紅。","拂衣從此去，高步躡华嵩。"]', '诗', 'shi', '', NULL, '東京留別諸公 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e9425e-7f31-4c3f-99b4-e6da547d6a85', '送袁太祝尉豫章', '送袁太祝尉豫章', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["何幸遇休明，觀光來上京。","相逢武陵客，獨送豫章行。","隨牒牽黃綬，離羣會墨卿。","江南佳麗地，山水舊難名。"]', '["何幸遇休明，观光来上京。","相逢武陵客，独送豫章行。","隨牒牽黄綬，離羣會墨卿。","江南佳丽地，山水旧难名。"]', '诗', 'shi', '', NULL, '送袁太祝尉豫章 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9aeb4ff-dc74-49cb-9777-5ddc98253cb0', '都下送辛大之鄂', '都下送辛大之鄂', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["南國辛居士，言歸舊竹林。","未逢調鼎用，徒有濟川心。","予亦忘機者，田園在漢陰。","因君故鄉去，遙寄式微吟。"]', '["南国辛居士，言归旧竹林。","未逢調鼎用，徒有濟川心。","予亦忘機者，田园在漢陰。","因君故乡去，遙寄式微吟。"]', '诗', 'shi', '', NULL, '都下送辛大之鄂 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39b0639-2392-4ee1-aa16-0aa858b2ebb4', '送席大', '送席大', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["惜爾懷其寶，迷邦倦客遊。","江山歷全楚，河洛越成周。","道路疲千里，鄉園老一丘。","知君命不偶，同病亦同憂。"]', '["惜爾懷其寶，迷邦倦客游。","江山歷全楚，河洛越成周。","道路疲千里，乡园老一丘。","知君命不偶，同病亦同憂。"]', '诗', 'shi', '', NULL, '送席大 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e25abf-74e3-4f84-9ee1-f5c7030858b9', '送賈昇主簿之荆府', '送賈昇主簿之荆府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["奉使推能者，勤王不暫閑。","觀風隨按察，乘騎度荆關。","送別登何處，開筵舊峴山。","征軒明日遠，空望郢門間。"]', '["奉使推能者，勤王不暫闲。","观风隨按察，乘騎度荆关。","送別登何处，开筵旧峴山。","征軒明日远，空望郢门间。"]', '诗', 'shi', '', NULL, '送賈昇主簿之荆府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5826d16e-068d-45f0-8a86-919e35bc1471', '送王大校書', '送王大校书', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["導漾自嶓冢，東流爲漢川。","維桑君有意，解纜我開筵。","雲雨從茲別，林端意渺然。","尺書能不恡，時望鯉魚傳。"]', '["導漾自嶓冢，东流爲漢川。","維桑君有意，解纜我开筵。","云雨從茲別，林端意渺然。","尺书能不恡，时望鯉鱼傳。"]', '诗', 'shi', '', NULL, '送王大校書 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4937a4e9-aa26-480f-bc6d-a2239d94f1ef', '遊江西留別富陽裴劉二少府', '游江西留別富陽裴劉二少府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["西上遊江西，臨流恨解攜。","千山疊成嶂，萬水瀉爲溪。","石淺流難泝，藤長險易躋。","誰憐問津者，歲晏此中迷。"]', '["西上游江西，臨流恨解携。","千山叠成嶂，万水瀉爲溪。","石淺流难泝，藤长險易躋。","誰怜问津者，歲晏此中迷。"]', '诗', 'shi', '', NULL, '遊江西留別富陽裴劉二少府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b9a4931-3927-4b33-a72c-f35979a91ec3', '廣陵別薛八', '廣陵別薛八', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["士有不得志，棲棲吳楚間。","廣陵相遇罷，彭蠡泛舟還。","檣出江中樹，波連海上山。","風帆明日遠，何處更追攀。"]', '["士有不得志，棲棲吳楚间。","廣陵相遇罷，彭蠡泛舟還。","檣出江中樹，波連海上山。","风帆明日远，何处更追攀。"]', '诗', 'shi', '', NULL, '廣陵別薛八 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cebb0a57-e8cd-4af4-a7d3-05a4dc90bf0e', '送洗然弟進士舉', '送洗然弟進士舉', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["獻策金門去，承歡綵服違。","以吾一日長，念爾聚星稀。","昏定須溫席，寒多未授衣。","桂枝如已擢，早逐雁南飛。"]', '["獻策金门去，承歡綵服違。","以吾一日长，念爾聚星稀。","昏定須溫席，寒多未授衣。","桂枝如已擢，早逐雁南飞。"]', '诗', 'shi', '', NULL, '送洗然弟進士舉 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c19f4e-70c1-4168-b3a4-44008ed7b91c', '崔明府宅夜觀妓', '崔明府宅夜观妓', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["白日既云暮，朱顏亦已酡。","畫堂初點燭，金幌半垂羅。","長袖平陽曲，新聲子夜歌。","從來慣留客，茲夕爲誰多。"]', '["白日既云暮，朱顏亦已酡。","畫堂初点燭，金幌半垂羅。","长袖平陽曲，新声子夜歌。","從来慣留客，茲夕爲誰多。"]', '诗', 'shi', '', NULL, '崔明府宅夜觀妓 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed74c173-6f97-4bc3-b8f8-d3530882a027', '同盧明府早秋宴張郎中海亭', '同盧明府早秋宴張郎中海亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["側聽弦歌宰，文書游夏徒。","故園欣賞竹，爲邑幸來蘇。","華省曾聯事，仙舟復與俱。","欲知臨泛久，荷露漸成珠。"]', '["側听弦歌宰，文书游夏徒。","故园欣賞竹，爲邑幸来蘇。","华省曾聯事，仙舟复與俱。","欲知臨泛久，荷露漸成珠。"]', '诗', 'shi', '', NULL, '同盧明府早秋宴張郎中海亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b60ea171-1629-4c37-a497-34b66b97c086', '盧明府早秋宴張郎中海園即事得秋字', '盧明府早秋宴張郎中海园即事得秋字', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["邑有弦歌宰，翔鸞狎野鷗。","眷言華省舊，暫拂海池遊。","鬱島藏深竹，前溪對舞樓。","更聞書即事，雲物是清秋。"]', '["邑有弦歌宰，翔鸾狎野鷗。","眷言华省旧，暫拂海池游。","鬱島藏深竹，前溪对舞楼。","更闻书即事，云物是清秋。"]', '诗', 'shi', '', NULL, '盧明府早秋宴張郎中海園即事得秋字 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5de78bc-8cdf-4f9d-b21c-3a9762300ca9', '宴榮二山池', '宴榮二山池', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["甲第開金穴，榮期樂自多。","櫪嘶支遁馬，池養右軍鵝。","竹引攜琴入，花邀載酒過。","山公來取醉，時唱接䍦歌。"]', '["甲第开金穴，榮期乐自多。","櫪嘶支遁马，池養右軍鵝。","竹引携琴入，花邀載酒過。","山公来取醉，时唱接䍦歌。"]', '诗', 'shi', '', NULL, '宴榮二山池 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9944b19-7b4b-47fb-94f5-e9746e9c07a5', '夏日與崔二十一同集衛明府宅', '夏日與崔二十一同集衛明府宅', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["言避一時暑，池亭五月開。","喜逢金馬客，同飲玉人杯。","舞鶴乘軒至，遊魚擁釣來。","座中殊未起，簫管莫相催。"]', '["言避一时暑，池亭五月开。","喜逢金马客，同饮玉人杯。","舞鹤乘軒至，游鱼擁釣来。","座中殊未起，簫管莫相催。"]', '诗', 'shi', '', NULL, '夏日與崔二十一同集衛明府宅 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2b5090e-e6fe-4d4f-9dd6-fe94ff6d4b5c', '清明日宴梅道士房', '清明日宴梅道士房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["林臥愁春盡，開軒覽物華。","忽逢青鳥使，邀入赤松家。","丹竈初開火，仙桃正落花。","童顏若可駐，何惜醉流霞。"]', '["林臥愁春尽，开軒覽物华。","忽逢青鸟使，邀入赤松家。","丹竈初开火，仙桃正落花。","童顏若可駐，何惜醉流霞。"]', '诗', 'shi', '', NULL, '清明日宴梅道士房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95f0a885-bbdc-4a4c-acc7-cb9d8f42eda4', '寒夜張明府宅宴', '寒夜張明府宅宴', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["瑞雪初盈尺，寒宵始半更。","列筵邀酒伴，刻燭限詩成。","香炭金爐煖，嬌弦玉指清。","醉來方欲臥，不覺曉雞鳴。"]', '["瑞雪初盈尺，寒宵始半更。","列筵邀酒伴，刻燭限诗成。","香炭金爐煖，嬌弦玉指清。","醉来方欲臥，不覺晓雞鳴。"]', '诗', 'shi', '', NULL, '寒夜張明府宅宴 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16943777-44e8-491d-a4a8-fb33f6d2c3c9', '宴張別駕新齋', '宴張別駕新斋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["世業傳珪組，江城佐股肱。","高齋徵學問，虛薄濫先登。","講論陪諸子，文章得舊朋。","士元多賞激，衰病恨無能。"]', '["世業傳珪組，江城佐股肱。","高斋徵学问，虛薄濫先登。","講論陪諸子，文章得旧朋。","士元多賞激，衰病恨無能。"]', '诗', 'shi', '', NULL, '宴張別駕新齋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b71d7c9c-7e92-4797-b2c9-8715dd0c2881', '與諸子登峴山', '與諸子登峴山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["人事有代謝，往來成古今。","江山留勝跡，我輩復登臨。","水落魚梁淺，天寒夢澤深。","羊公碑字在，讀罷淚沾襟。"]', '["人事有代謝，往来成古今。","江山留勝跡，我輩复登臨。","水落鱼梁淺，天寒梦澤深。","羊公碑字在，读罷泪沾襟。"]', '诗', 'shi', '', NULL, '與諸子登峴山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd87caec-0cbf-4003-b5ca-7ee0208c5232', '與杭州薛司戶登樟亭樓作', '與杭州薛司戶登樟亭楼作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["水樓一登眺，半出青林高。","帟幕英僚敞，芳筵下客叨。","山藏伯禹穴，城壓伍胥濤。","今日觀溟漲，垂綸學釣鼇。"]', '["水楼一登眺，半出青林高。","帟幕英僚敞，芳筵下客叨。","山藏伯禹穴，城壓伍胥濤。","今日观溟漲，垂綸学釣鼇。"]', '诗', 'shi', '', NULL, '與杭州薛司戶登樟亭樓作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87687c59-0427-4eda-81c9-1ab22702709f', '尋天台山', '尋天台山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["吾友太乙子，餐霞臥赤城。","欲尋華頂去，不憚惡谿名。","歇馬憑雲宿，揚帆截海行。","高高翠微裏，遙見石梁橫。"]', '["吾友太乙子，餐霞臥赤城。","欲尋华頂去，不憚惡谿名。","歇马憑云宿，揚帆截海行。","高高翠微裏，遙见石梁橫。"]', '诗', 'shi', '', NULL, '尋天台山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245a8ea8-f347-4cfe-90c2-6b6ef8b1d123', '同曹三御史行泛湖歸越', '同曹三御史行泛湖归越', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["秋入詩人意，巴歌和者稀。","泛湖同逸旅，吟會是思歸。","白簡徒推薦，滄洲已拂衣。","杳冥雲外去，誰不羨鴻飛。"]', '["秋入诗人意，巴歌和者稀。","泛湖同逸旅，吟會是思归。","白簡徒推薦，滄洲已拂衣。","杳冥云外去，誰不羨鴻飞。"]', '诗', 'shi', '', NULL, '同曹三御史行泛湖歸越 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b128b1ea-3c7c-48e2-8d21-566d654b10fa', '晚泊潯陽望廬山', '晚泊潯陽望廬山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["挂席幾千里，名山都未逢。","泊舟潯陽郭，始見香爐峰。","嘗讀遠公傳，永懷塵外蹤。","東林精舍近，日暮但聞鐘。"]', '["挂席幾千里，名山都未逢。","泊舟潯陽郭，始见香爐峰。","嘗读远公傳，永懷塵外蹤。","东林精舍近，日暮但闻鐘。"]', '诗', 'shi', '', NULL, '晚泊潯陽望廬山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96fe1282-e447-430f-a22a-72e9caaad9fd', '陪張丞相登嵩陽樓', '陪張丞相登嵩陽楼', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["獨步人何在，嵩陽有故樓。","歲寒問耆舊，行縣擁諸候。","林莽北彌望，沮漳東會流。","客中遇知己，無復越鄉憂。"]', '["独步人何在，嵩陽有故楼。","歲寒问耆旧，行縣擁諸候。","林莽北彌望，沮漳东會流。","客中遇知己，無复越乡憂。"]', '诗', 'shi', '', NULL, '陪張丞相登嵩陽樓 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83128aff-73de-4b0d-a57d-ae2039b628ae', '武陵泛舟', '武陵泛舟', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["武陵川路狹，前櫂入花林。","莫測幽源裏，仙家信幾深。","水回青嶂合，雲度綠溪陰。","坐聽閑猿嘯，彌清塵外心。"]', '["武陵川路狹，前櫂入花林。","莫測幽源裏，仙家信幾深。","水回青嶂合，云度綠溪陰。","坐听闲猿嘯，彌清塵外心。"]', '诗', 'shi', '', NULL, '武陵泛舟 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400cfc13-2169-4520-be44-0a5a1bb32567', '與顏錢塘登障樓望潮作', '與顏錢塘登障楼望潮作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["百里聞雷震，鳴弦暫輟彈。","府中連騎出，江上待潮觀。","照日秋雲廻，浮天渤澥寬。","驚濤來似雪，一坐凜生寒。"]', '["百里闻雷震，鳴弦暫輟彈。","府中連騎出，江上待潮观。","照日秋云廻，浮天渤澥寬。","驚濤来似雪，一坐凜生寒。"]', '诗', 'shi', '', NULL, '與顏錢塘登障樓望潮作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46555335-434e-41cd-9811-b0376d8144d7', '姚開府山池', '姚开府山池', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["主人新邸第，相國舊池臺。","館是招賢闢，樓因教舞開。","軒車人已散，簫管鳳初來。","今日龍門下，誰知文舉才。"]', '["主人新邸第，相国旧池台。","館是招賢闢，楼因教舞开。","軒车人已散，簫管鳳初来。","今日龙门下，誰知文舉才。"]', '诗', 'shi', '', NULL, '姚開府山池 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20855c2b-467c-4ecd-af09-87d46a19a3f8', '夏日浮舟過陳大水亭', '夏日浮舟過陳大水亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["水亭涼氣多，閑櫂晚來過。","澗影見松竹，潭香聞芰荷。","野童扶醉舞，山鳥助酣歌。","幽賞未云徧，煙光奈夕何。"]', '["水亭涼氣多，闲櫂晚来過。","澗影见松竹，潭香闻芰荷。","野童扶醉舞，山鸟助酣歌。","幽賞未云徧，煙光奈夕何。"]', '诗', 'shi', '', NULL, '夏日浮舟過陳大水亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80d8466-83b1-4821-ad08-edcdf6c437f0', '與白明府遊江', '與白明府游江', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["故人來自遠，邑宰復初臨。","執手恨爲別，同舟無異心。","沿洄洲渚趣，演漾弦歌音。","誰識躬耕者，年年梁甫吟。"]', '["故人来自远，邑宰复初臨。","執手恨爲別，同舟無異心。","沿洄洲渚趣，演漾弦歌音。","誰識躬耕者，年年梁甫吟。"]', '诗', 'shi', '', NULL, '與白明府遊江 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709677a9-d6dc-4967-ac80-f6783a0053a2', '遊鳳林寺西嶺', '游鳳林寺西嶺', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["共喜年華好，來遊水石間。","煙容開遠樹，春色滿幽山。","壺酒朋情洽，琴歌野興閑。","莫愁歸路暝，招月伴人還。"]', '["共喜年华好，来游水石间。","煙容开远樹，春色满幽山。","壺酒朋情洽，琴歌野兴闲。","莫愁归路暝，招月伴人還。"]', '诗', 'shi', '', NULL, '遊鳳林寺西嶺 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05844dc3-b427-49c9-931f-73ab8e5b98f3', '秋日陪李侍御渡松滋江', '秋日陪李侍御渡松滋江', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["南紀西江闊，皇華御史雄。","截流寧假楫，挂席自生風。","僚宷爭攀鷁，魚龍亦避驄。","坐聽白[雪]唱，翻入櫂歌中。"]', '["南紀西江闊，皇华御史雄。","截流寧假楫，挂席自生风。","僚宷爭攀鷁，鱼龙亦避驄。","坐听白[雪]唱，翻入櫂歌中。"]', '诗', 'shi', '', NULL, '秋日陪李侍御渡松滋江 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d065f491-380a-4109-a65e-c648bb9eeb33', '陪獨孤使君同與蕭員外證登萬山亭', '陪独孤使君同與蕭員外證登万山亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["萬山青嶂曲，千騎使君遊。","神女鳴環佩，仙郎接獻酬。","遍觀雲夢野，自愛江城樓。","何必東南守，空傳沈隱侯。"]', '["万山青嶂曲，千騎使君游。","神女鳴环佩，仙郎接獻酬。","遍观云梦野，自愛江城楼。","何必东南守，空傳沈隐侯。"]', '诗', 'shi', '', NULL, '陪獨孤使君同與蕭員外證登萬山亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('650782bc-3e01-44d2-969a-c49c5694e4a3', '秋登張明府海亭', '秋登張明府海亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["海亭秋日望，委曲見江山。","染翰聊題壁，傾壺一解顏。","歌逢彭澤令，歸賞故園間。","予亦將琴史，棲遲共取閑。"]', '["海亭秋日望，委曲见江山。","染翰聊題壁，傾壺一解顏。","歌逢彭澤令，归賞故园间。","予亦將琴史，棲遲共取闲。"]', '诗', 'shi', '', NULL, '秋登張明府海亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33885176-3272-4f6a-89a1-3673b82b52d6', '臨渙裴明府席遇張十一房六', '臨渙裴明府席遇張十一房六', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["河縣柳林邊，河橋晚泊船。","文叨才子會，官喜故人連。","笑語同今夕，輕肥異往年。","晨風理歸櫂，吳楚各依然。"]', '["河縣柳林邊，河橋晚泊船。","文叨才子會，官喜故人連。","笑語同今夕，轻肥異往年。","晨风理归櫂，吳楚各依然。"]', '诗', 'shi', '', NULL, '臨渙裴明府席遇張十一房六 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f69bc1-db32-4ecf-8029-3c5a56f1e709', '梅道士水亭', '梅道士水亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["傲吏非凡吏，名流即道流。","隱居不可見，高論莫能酬。","水接仙源近，山藏鬼谷幽。","再來迷處所，花下問漁舟。"]', '["傲吏非凡吏，名流即道流。","隐居不可见，高論莫能酬。","水接仙源近，山藏鬼谷幽。","再来迷处所，花下问漁舟。"]', '诗', 'shi', '', NULL, '梅道士水亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60e7f5f-9fd7-404a-aa1e-e3f0b5024526', '遊景空寺蘭若', '游景空寺蘭若', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["龍象經行處，山腰度石關。","屢迷青嶂合，時愛綠蘿閑。","宴息花林下，高談竹嶼間。","寥寥隔塵事，疑是入雞山。"]', '["龙象經行处，山腰度石关。","屢迷青嶂合，时愛綠蘿闲。","宴息花林下，高談竹嶼间。","寥寥隔塵事，疑是入雞山。"]', '诗', 'shi', '', NULL, '遊景空寺蘭若 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d19e8d9-4fbb-4d8d-9edf-40b941d3b05b', '陪李侍御訪聰上人禪居', '陪李侍御訪聰上人禪居', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["欣逢柏臺友，共謁聰公禪。","石室無人到，繩牀見虎眠。","陰崖常抱雪，枯澗爲生泉。","出處雖云異，同歡在法筵。"]', '["欣逢柏台友，共謁聰公禪。","石室無人到，繩牀见虎眠。","陰崖常抱雪，枯澗爲生泉。","出处雖云異，同歡在法筵。"]', '诗', 'shi', '', NULL, '陪李侍御訪聰上人禪居 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9119ad9-0cb7-46f0-b713-1bc42f5efe88', '遊精思觀回王白雲在後', '游精思观回王白云在後', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["出谷未停午，到家日已曛。","回瞻下山路，但見牛羊羣。","樵子暗相失，草蟲寒不聞。","衡門猶未掩，佇立望夫君。"]', '["出谷未停午，到家日已曛。","回瞻下山路，但见牛羊羣。","樵子暗相失，草蟲寒不闻。","衡门猶未掩，佇立望夫君。"]', '诗', 'shi', '', NULL, '遊精思觀回王白雲在後 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffcb1174-6051-471d-bc51-4f7b74b04e65', '夏日辨玉法師茅齋', '夏日辨玉法師茅斋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["夏日茅齋裏，無風坐亦涼。","竹林深筍穊，藤架引梢長。","燕覓巢窠處，蜂來造蜜房。","物華皆可翫，花橤四時芳。"]', '["夏日茅斋裏，無风坐亦涼。","竹林深筍穊，藤架引梢长。","燕覓巢窠处，蜂来造蜜房。","物华皆可翫，花橤四时芳。"]', '诗', 'shi', '', NULL, '夏日辨玉法師茅齋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f5b51a-791b-4b78-952e-82e288cda0fe', '與張折衝遊耆闍寺', '與張折衝游耆闍寺', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["釋子彌天秀，將軍武庫才。","橫行塞北盡，獨步漢南來。","貝葉傳金口，山樓作賦開。","因君振嘉藻，江楚氣雄哉。"]', '["釋子彌天秀，將軍武庫才。","橫行塞北尽，独步漢南来。","貝葉傳金口，山楼作賦开。","因君振嘉藻，江楚氣雄哉。"]', '诗', 'shi', '', NULL, '與張折衝遊耆闍寺 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b4773e-03fc-4234-a59e-5e5c4c153a29', '遊精思題觀主山房', '游精思題观主山房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["誤入桃源裏，初憐竹逕深。","方知仙子宅，未有世人尋。","舞鶴過閑砌，飛猿嘯密林。","漸通玄妙理，深得坐忘心。"]', '["誤入桃源裏，初怜竹逕深。","方知仙子宅，未有世人尋。","舞鹤過闲砌，飞猿嘯密林。","漸通玄妙理，深得坐忘心。"]', '诗', 'shi', '', NULL, '遊精思題觀主山房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4edaf23-405c-4ace-9882-c347bc3ea45d', '宿立公房', '宿立公房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["支遁初求道，深公笑買山。","何如石巖趣，自入戶庭間。","苔潤春泉滿，蘿軒夜月閑。","能令許玄度，吟臥不知還。"]', '["支遁初求道，深公笑買山。","何如石巖趣，自入戶庭间。","苔潤春泉满，蘿軒夜月闲。","能令許玄度，吟臥不知還。"]', '诗', 'shi', '', NULL, '宿立公房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ccd9712-a50d-47f4-b603-bafe4a879f53', '尋陳逸人故居', '尋陳逸人故居', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["人事一朝盡，荒蕪三徑休。","始聞漳浦臥，奄作岱宗遊。","池水猶含墨，風雲已落秋。","今宵泉壑裏，何處覓藏舟。"]', '["人事一朝尽，荒蕪三徑休。","始闻漳浦臥，奄作岱宗游。","池水猶含墨，风云已落秋。","今宵泉壑裏，何处覓藏舟。"]', '诗', 'shi', '', NULL, '尋陳逸人故居 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8e93b2-34fa-4d15-b7e2-fe3672e76753', '尋梅道士', '尋梅道士', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["彭澤先生柳，山陰道士鵝。","我來從所好，停策漢陰多。","重以觀魚樂，因之鼓枻歌。","崔徐迹未朽，千載揖清波。"]', '["彭澤先生柳，山陰道士鵝。","我来從所好，停策漢陰多。","重以观鱼乐，因之鼓枻歌。","崔徐迹未朽，千載揖清波。"]', '诗', 'shi', '', NULL, '尋梅道士 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e43255-8176-414b-858f-fa0cf69bc970', '陪姚使君題惠上人房', '陪姚使君題惠上人房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["帶雪梅初煖，含煙柳尚青。","來窺童子偈，得聽法王經。","會理知無我，觀空厭有形。","迷心應覺悟，客思未遑寧。"]', '["带雪梅初煖，含煙柳尚青。","来窺童子偈，得听法王經。","會理知無我，观空厭有形。","迷心應覺悟，客思未遑寧。"]', '诗', 'shi', '', NULL, '陪姚使君題惠上人房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa0cc741-a21b-42e7-8f47-c2553bdec94e', '晚春題遠上人南亭', '晚春題远上人南亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["給園支遁隱，虛寂養身和。","春晚羣木秀，間關黃鳥歌。","林棲居士竹，池養右軍鵝。","炎月北窗下，清風期再過。"]', '["給园支遁隐，虛寂養身和。","春晚羣木秀，间关黄鸟歌。","林棲居士竹，池養右軍鵝。","炎月北窗下，清风期再過。"]', '诗', 'shi', '', NULL, '晚春題遠上人南亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965506ed-7133-4826-ad87-abdabc3e23d8', '題大禹寺義公禪房', '題大禹寺義公禪房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["義公習禪處，結構依空林。","戶外一峰秀，階前羣壑深。","夕陽連雨足，空翠落庭陰。","看取蓮花淨，應知不染心。"]', '["義公習禪处，結構依空林。","戶外一峰秀，階前羣壑深。","夕陽連雨足，空翠落庭陰。","看取蓮花淨，應知不染心。"]', '诗', 'shi', '', NULL, '題大禹寺義公禪房 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c3b0c4-e278-4ff4-af07-1febf280e064', '尋白鶴巖張子容隱居', '尋白鹤巖張子容隐居', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["白鶴青巖半，幽人有隱居。","階庭空水石，林壑罷樵漁。","歲月青松老，風霜苦竹疎。","覩茲懷舊業，回策返吾廬。"]', '["白鹤青巖半，幽人有隐居。","階庭空水石，林壑罷樵漁。","歲月青松老，风霜苦竹疎。","覩茲懷旧業，回策返吾廬。"]', '诗', 'shi', '', NULL, '尋白鶴巖張子容隱居 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974bfa5a-da38-4c0f-936f-c7849571d758', '題融公蘭若', '題融公蘭若', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["精舍買金開，流泉遶砌回。","芰荷薰講席，松柏映香臺。","法雨晴飛去，天花晝下來。","談玄殊未已，歸騎夕陽催。"]', '["精舍買金开，流泉遶砌回。","芰荷薰講席，松柏映香台。","法雨晴飞去，天花晝下来。","談玄殊未已，归騎夕陽催。"]', '诗', 'shi', '', NULL, '題融公蘭若 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23410e2c-9358-4604-96bc-13506f2b2ca9', '過景空寺故融公蘭若', '過景空寺故融公蘭若', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["池上青蓮宇，林間白馬泉。","故人成異物，過客獨潸然。","既禮新松塔，還尋舊石筵。","平生竹如意，猶挂草堂前。"]', '["池上青蓮宇，林间白马泉。","故人成異物，過客独潸然。","既禮新松塔，還尋旧石筵。","平生竹如意，猶挂草堂前。"]', '诗', 'shi', '', NULL, '過景空寺故融公蘭若 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d6cbe25-f63a-448c-8b1f-a5dd2df5ad51', '題張野人園廬', '題張野人园廬', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["與君園廬竝，微尚頗亦同。","耕釣方自逸，壺觴趣不空。","門無俗士駕，人有上皇風。","何處先賢傳，惟稱龐德公。"]', '["與君园廬竝，微尚頗亦同。","耕釣方自逸，壺觴趣不空。","门無俗士駕，人有上皇风。","何处先賢傳，惟稱龐德公。"]', '诗', 'shi', '', NULL, '題張野人園廬 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f11c01e5-4f3d-4790-9460-a09b223c9123', '李少府與楊九再來', '李少府與楊九再来', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["弱歲早登龍，今來喜再逢。","如何春月柳，猶憶歲寒松。","煙火臨寒食，笙歌達曙鐘。","喧喧鬬雞道，行樂羨朋從。"]', '["弱歲早登龙，今来喜再逢。","如何春月柳，猶憶歲寒松。","煙火臨寒食，笙歌達曙鐘。","喧喧鬬雞道，行乐羨朋從。"]', '诗', 'shi', '', NULL, '李少府與楊九再來 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8980bc-3acf-4173-909b-5a15ac7b990c', '尋張五回夜園作', '尋張五回夜园作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["聞就龐公隱，移居近洞湖。","興來林是竹，歸臥谷名愚。","挂席樵風便，開軒琴月孤。","歲寒何用賞，霜落故園蕪。"]', '["闻就龐公隐，移居近洞湖。","兴来林是竹，归臥谷名愚。","挂席樵风便，开軒琴月孤。","歲寒何用賞，霜落故园蕪。"]', '诗', 'shi', '', NULL, '尋張五回夜園作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c855bc1-4c16-4e4f-8154-7fc0626c4ec7', '裴司士員司戶見尋', '裴司士員司戶见尋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["府僚能枉駕，家醞復新開。","落日池上酌，清風松下來。","廚人具雞黍，稚子摘楊梅。","誰道山公醉，猶能騎馬回。"]', '["府僚能枉駕，家醞复新开。","落日池上酌，清风松下来。","廚人具雞黍，稚子摘楊梅。","誰道山公醉，猶能騎马回。"]', '诗', 'shi', '', NULL, '裴司士員司戶見尋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1cb5334-51e5-4c2b-b791-2bc74d5d693e', '春中喜王九相尋', '春中喜王九相尋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["二月湖水清，家家春鳥鳴。","林花掃更落，徑草踏還生。","酒伴來相命，開尊共解酲。","當杯已入手，歌妓莫停聲。"]', '["二月湖水清，家家春鸟鳴。","林花掃更落，徑草踏還生。","酒伴来相命，开尊共解酲。","當杯已入手，歌妓莫停声。"]', '诗', 'shi', '', NULL, '春中喜王九相尋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041749fb-f22e-49be-895a-9bd55d5bc691', '李氏園林臥疾', '李氏园林臥疾', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["我愛陶家趣，園林無俗情。","春雷百卉坼，寒食四鄰清。","伏枕嗟公幹，歸山羨子平。","年年白社客，空滯洛陽城。"]', '["我愛陶家趣，园林無俗情。","春雷百卉坼，寒食四鄰清。","伏枕嗟公幹，归山羨子平。","年年白社客，空滯洛陽城。"]', '诗', 'shi', '', NULL, '李氏園林臥疾 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9309205e-1d08-4a7b-99ef-4a05a9ee4370', '過故人莊', '過故人莊', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["故人具雞黍，邀我至田家。","綠樹村邊合，青山郭外斜。","開筵面場圃，把酒話桑麻。","待到重陽日，還來就菊花。"]', '["故人具雞黍，邀我至田家。","綠樹村邊合，青山郭外斜。","开筵面場圃，把酒話桑麻。","待到重陽日，還来就菊花。"]', '诗', 'shi', '', NULL, '過故人莊 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d404f3-989e-464e-843b-380f90c154aa', '張七及辛大見尋南亭醉作', '張七及辛大见尋南亭醉作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["山公能飲酒，居士好彈箏。","世外交初得，林中契已幷。","納涼風颯至，逃暑日將傾。","便就南亭裏，餘尊惜解酲。"]', '["山公能饮酒，居士好彈箏。","世外交初得，林中契已幷。","納涼风颯至，逃暑日將傾。","便就南亭裏，餘尊惜解酲。"]', '诗', 'shi', '', NULL, '張七及辛大見尋南亭醉作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('542cb326-1037-4bd9-b0f6-6479d165dc4c', '歲暮歸南山', '歲暮归南山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["北闕休上書，南山歸敝廬。","不才明主棄，多病故人疎。","白髮催年老，青陽逼歲除。","永懷愁不寐，松月夜窗虛。"]', '["北闕休上书，南山归敝廬。","不才明主棄，多病故人疎。","白髮催年老，青陽逼歲除。","永懷愁不寐，松月夜窗虛。"]', '诗', 'shi', '', NULL, '歲暮歸南山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd845d2-6948-480f-879e-019e40d2e32d', '南山下與老圃期種瓜', '南山下與老圃期種瓜', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["樵牧南山近，林閭北郭賒。","先人留素業，老圃作鄰家。","不種千株橘，惟資五色瓜。","邵平能就我，開徑剪蓬麻。"]', '["樵牧南山近，林閭北郭賒。","先人留素業，老圃作鄰家。","不種千株橘，惟資五色瓜。","邵平能就我，开徑剪蓬麻。"]', '诗', 'shi', '', NULL, '南山下與老圃期種瓜 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49642de8-9fce-42fa-a30e-e67d80a92ec9', '泝江至武昌', '泝江至武昌', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["家本洞湖上，歲時歸思催。","客心徒欲速，江路苦邅回。","殘凍因風解，新正度臘開。","行看武昌柳，髣髴映樓臺。"]', '["家本洞湖上，歲时归思催。","客心徒欲速，江路苦邅回。","殘凍因风解，新正度臘开。","行看武昌柳，髣髴映楼台。"]', '诗', 'shi', '', NULL, '泝江至武昌 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f59f3b55-df15-4226-b0bf-4103bb74e1a1', '舟中曉望', '舟中晓望', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["挂席東南望，青山水國遙。","舳艫爭利涉，來往接風潮。","問我今何去，天台訪石橋。","坐看霞色曉，疑是赤城標。"]', '["挂席东南望，青山水国遙。","舳艫爭利涉，来往接风潮。","问我今何去，天台訪石橋。","坐看霞色晓，疑是赤城標。"]', '诗', 'shi', '', NULL, '舟中曉望 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02214ffe-3a50-4e2c-8dca-038d928eff3b', '自洛之越', '自洛之越', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["皇皇三十載，書劒兩無成。","山水尋吳越，風塵厭洛京。","扁舟泛湖海，長揖謝公卿。","且樂杯中物，誰論世上名。"]', '["皇皇三十載，书劒兩無成。","山水尋吳越，风塵厭洛京。","扁舟泛湖海，长揖謝公卿。","且乐杯中物，誰論世上名。"]', '诗', 'shi', '', NULL, '自洛之越 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e11173c-add7-4d51-a7c7-9fa28a194396', '途中遇晴', '途中遇晴', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["已失巴陵雨，猶逢蜀坂泥。","天開斜景遍，山出晚雲低。","餘濕猶霑草，殘流尚入溪。","今宵有明月，鄉思遠悽悽。"]', '["已失巴陵雨，猶逢蜀坂泥。","天开斜景遍，山出晚云低。","餘濕猶霑草，殘流尚入溪。","今宵有明月，乡思远悽悽。"]', '诗', 'shi', '', NULL, '途中遇晴 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c9a812b-17cd-4d10-8a03-a07611947a9d', '歸至郢中', '归至郢中', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["遠遊經海嶠，返櫂歸山阿。","日夕見喬木，鄉關在伐柯。","愁隨江路盡，喜入郢門多。","左右看桑土，依然即匪他。"]', '["远游經海嶠，返櫂归山阿。","日夕见喬木，乡关在伐柯。","愁隨江路尽，喜入郢门多。","左右看桑土，依然即匪他。"]', '诗', 'shi', '', NULL, '歸至郢中 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d8dea3-4da6-4eca-888b-5005050c3909', '夕次蔡陽館', '夕次蔡陽館', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["日暮馬行疾，城荒人住稀。","聽歌知近楚，投館忽如歸。","魯堰田疇廣，章陵氣色微。","明朝拜嘉慶，須著老萊衣。"]', '["日暮马行疾，城荒人住稀。","听歌知近楚，投館忽如归。","魯堰田疇廣，章陵氣色微。","明朝拜嘉慶，須著老萊衣。"]', '诗', 'shi', '', NULL, '夕次蔡陽館 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a6b9883-ec6b-43cf-9378-22426db599f9', '他鄉七夕', '他乡七夕', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["他鄉逢七夕，旅館益羇愁。","不見穿鍼婦，空懷故國樓。","緒風初減熱，新月始臨秋。","誰忍窺河漢，迢迢問斗牛。"]', '["他乡逢七夕，旅館益羇愁。","不见穿鍼婦，空懷故国楼。","緒风初減熱，新月始臨秋。","誰忍窺河漢，迢迢问斗牛。"]', '诗', 'shi', '', NULL, '他鄉七夕 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c93ca3b-8719-4004-8515-140d83266788', '夜泊牛渚趁薛八船不及', '夜泊牛渚趁薛八船不及', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["星羅牛渚夕，風退鷁舟遲。","浦漵嘗同宿，煙波忽間之。","榜歌空裏失，船火望中疑。","明發泛潮海，茫茫何處期。"]', '["星羅牛渚夕，风退鷁舟遲。","浦漵嘗同宿，煙波忽间之。","榜歌空裏失，船火望中疑。","明發泛潮海，茫茫何处期。"]', '诗', 'shi', '', NULL, '夜泊牛渚趁薛八船不及 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513a6fc8-e634-4955-9830-7b6f13da87eb', '曉入南山', '晓入南山', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["瘴氣曉氛氳，南山復水雲。","鯤飛今始見，鳥墮舊來聞。","地接長沙近，江從汨渚分。","賈生曾弔屈，予亦痛斯文。"]', '["瘴氣晓氛氳，南山复水云。","鯤飞今始见，鸟墮旧来闻。","地接长沙近，江從汨渚分。","賈生曾弔屈，予亦痛斯文。"]', '诗', 'shi', '', NULL, '曉入南山 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1695f005-7a4d-4cce-8694-df08455000f5', '夜渡湘水', '夜渡湘水', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["客舟貪利涉，闇裏渡湘川。","露氣聞芳杜，歌聲識采蓮。","榜人投岸火，漁子宿潭煙。","行侶時相問，潯陽何處邊。"]', '["客舟貪利涉，闇裏渡湘川。","露氣闻芳杜，歌声識采蓮。","榜人投岸火，漁子宿潭煙。","行侶时相问，潯陽何处邊。"]', '诗', 'shi', '', NULL, '夜渡湘水 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50697800-8688-40ca-ac1a-43de223f5d12', '赴京途中遇雪', '赴京途中遇雪', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["迢遞秦京道，蒼茫藏暮天。","窮陰連晦朔，積雪滿山川。","落雁迷沙渚，饑烏集野田。","客愁空佇立，不見有人煙。"]', '["迢遞秦京道，蒼茫藏暮天。","窮陰連晦朔，積雪满山川。","落雁迷沙渚，饑烏集野田。","客愁空佇立，不见有人煙。"]', '诗', 'shi', '', NULL, '赴京途中遇雪 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efec7307-9053-4578-a033-b1c942f1672b', '途次望鄉', '途次望乡', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["客行愁落日，鄉思重相催。","況在他山外，天寒夕鳥來。","雪深迷郢路，雲暗失陽臺。","可歎悽惶子，高歌誰爲媒。"]', '["客行愁落日，乡思重相催。","況在他山外，天寒夕鸟来。","雪深迷郢路，云暗失陽台。","可歎悽惶子，高歌誰爲媒。"]', '诗', 'shi', '', NULL, '途次望鄉 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f881c202-e9ce-4128-87f3-3a54dd4442dd', '永嘉上浦館逢張八子容', '永嘉上浦館逢張八子容', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["逆旅相逢處，江村日暮時。","衆山遙對酒，孤嶼共題詩。","廨宇鄰蛟室，人煙接島夷。","鄉園萬餘里，失路一相悲。"]', '["逆旅相逢处，江村日暮时。","衆山遙对酒，孤嶼共題诗。","廨宇鄰蛟室，人煙接島夷。","乡园万餘里，失路一相悲。"]', '诗', 'shi', '', NULL, '永嘉上浦館逢張八子容 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f17cab-6467-4451-a5d6-129727037dcc', '宿武陽即事', '宿武陽即事', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["川暗夕陽盡，孤舟泊岸初。","嶺猿相呌嘯，潭嶂似空虛。","就枕滅明燭，扣舷聞夜漁。","雞鳴問何處，人物是秦餘。"]', '["川暗夕陽尽，孤舟泊岸初。","嶺猿相呌嘯，潭嶂似空虛。","就枕滅明燭，扣舷闻夜漁。","雞鳴问何处，人物是秦餘。"]', '诗', 'shi', '', NULL, '宿武陽即事 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8255598c-9ddd-44f0-b2a1-4e7fcb662dc8', '渡揚子江', '渡揚子江', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["桂檝中流望，京江兩畔明。","林開揚子驛，山出潤州城。","海盡邊陰靜，江寒朔吹生。","更聞楓葉下，淅瀝度秋聲。"]', '["桂檝中流望，京江兩畔明。","林开揚子驛，山出潤州城。","海尽邊陰静，江寒朔吹生。","更闻楓葉下，淅瀝度秋声。"]', '诗', 'shi', '', NULL, '渡揚子江 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8374b43-48b6-42be-993f-1465e20d113f', '田家元日', '田家元日', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["昨夜斗回北，今朝歲起東。","我年已強仕，無祿尚憂農。","桑野就耕父，荷鋤隨牧童。","田家占氣候，共說此年豐。"]', '["昨夜斗回北，今朝歲起东。","我年已強仕，無祿尚憂農。","桑野就耕父，荷鋤隨牧童。","田家占氣候，共说此年豐。"]', '诗', 'shi', '', NULL, '田家元日 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54601a1-c350-4df6-9183-11f1c5203318', '九日得新字', '九日得新字', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["初九未成旬，重陽即此晨。","登高聞古事，載酒訪幽人。","落帽恣歡飲，授衣同試新。","茱萸正可佩，折取寄情親。"]', '["初九未成旬，重陽即此晨。","登高闻古事，載酒訪幽人。","落帽恣歡饮，授衣同試新。","茱萸正可佩，折取寄情親。"]', '诗', 'shi', '', NULL, '九日得新字 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7fd7ff3-b5a1-4cf5-ac6d-c05d53b1ecfa', '除夜樂城逢張少府', '除夜乐城逢張少府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["雲海泛甌閩，風潮泊島濱。","何知歲除夜，得見故鄉親。","余是乘槎客，君爲失路人。","平生復能幾，一別十餘春。"]', '["云海泛甌閩，风潮泊島濱。","何知歲除夜，得见故乡親。","余是乘槎客，君爲失路人。","平生复能幾，一別十餘春。"]', '诗', 'shi', '', NULL, '除夜樂城逢張少府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fcb766-aecd-49f6-b532-69d1267cd6fb', '歲除夜會樂城張少府宅', '歲除夜會乐城張少府宅', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["疇昔通家好，相知無間然。","續明催畫燭，守歲接長筵。","舊曲梅花唱，新正柏酒傳。","客行隨處樂，不見度年年。"]', '["疇昔通家好，相知無间然。","續明催畫燭，守歲接长筵。","旧曲梅花唱，新正柏酒傳。","客行隨处乐，不见度年年。"]', '诗', 'shi', '', NULL, '歲除夜會樂城張少府宅 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ab54826-ac0e-4cab-8aef-e9ea4839b7ea', '寒夜', '寒夜', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["閨夕綺窗閉，佳人罷縫衣。","理琴開寶匣，就枕臥重幃。","夜久燈花落，薰籠香氣微。","錦衾重自煖，遮莫曉霜飛。"]', '["閨夕綺窗閉，佳人罷縫衣。","理琴开寶匣，就枕臥重幃。","夜久灯花落，薰籠香氣微。","錦衾重自煖，遮莫晓霜飞。"]', '诗', 'shi', '', NULL, '寒夜 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2912dc0-60fd-407f-b203-9e4e9a5a4e24', '賦得盈盈樓上女', '賦得盈盈楼上女', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["夫壻久離別，青樓空望歸。","妝成卷簾坐，愁思嬾縫衣。","燕子家家入，楊花處處飛。","空牀難獨守，誰爲報金徽。"]', '["夫壻久離別，青楼空望归。","妝成卷簾坐，愁思嬾縫衣。","燕子家家入，楊花处处飞。","空牀难独守，誰爲報金徽。"]', '诗', 'shi', '', NULL, '賦得盈盈樓上女 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d066c36-ecd4-43ec-8a87-ec5e1afef33f', '春意', '春意', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["佳人能畫眉，妝罷出簾帷。","照水空自愛，折花將遺誰。","春情多豔逸，春意倍相思。","愁心極楊柳，一種亂如絲。"]', '["佳人能畫眉，妝罷出簾帷。","照水空自愛，折花將遺誰。","春情多豔逸，春意倍相思。","愁心極楊柳，一種亂如絲。"]', '诗', 'shi', '', NULL, '春意 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb33438-0559-4ddf-9083-0ac7f2cf1df7', '閨情', '閨情', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["一別隔炎涼，君衣忘短長。","裁縫無處等，以意忖情量。","畏瘦疑傷窄，防寒更厚裝。","半啼封裹了，知欲寄誰將。"]', '["一別隔炎涼，君衣忘短长。","裁縫無处等，以意忖情量。","畏瘦疑傷窄，防寒更厚裝。","半啼封裹了，知欲寄誰將。"]', '诗', 'shi', '', NULL, '閨情 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa42ef19-becc-4ee2-ba26-3b25e938db06', '美人分香', '美人分香', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["豔色本傾城，分香更有情。","髻鬟垂欲解，眉黛拂能輕。","舞學平陽態，歌翻子夜聲。","春風狹斜道，含笑待逢迎。"]', '["豔色本傾城，分香更有情。","髻鬟垂欲解，眉黛拂能轻。","舞学平陽態，歌翻子夜声。","春风狹斜道，含笑待逢迎。"]', '诗', 'shi', '', NULL, '美人分香 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db26b30-0913-4711-9557-e8d625092adc', '傷峴山雲表觀主', '傷峴山云表观主', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["少小學書劒，秦吳多歲年。","歸來一登眺，陵谷尚依然。","豈意餐霞客，溘隨朝露先。","因之問閭里，把臂幾人全。"]', '["少小学书劒，秦吳多歲年。","归来一登眺，陵谷尚依然。","豈意餐霞客，溘隨朝露先。","因之问閭里，把臂幾人全。"]', '诗', 'shi', '', NULL, '傷峴山雲表觀主 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3acc29be-70aa-4daa-93ea-17435dbfddfc', '題梧州陳司馬山齋', '題梧州陳司马山斋', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["南國無霜霰，連年對物華。","青林暗換葉，紅橤亦開花。","春去無山鳥，秋來見海槎。","流芳雖可悅，會自泣長沙。"]', '["南国無霜霰，連年对物华。","青林暗換葉，紅橤亦开花。","春去無山鸟，秋来见海槎。","流芳雖可悅，會自泣长沙。"]', '诗', 'shi', '', NULL, '題梧州陳司馬山齋 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5af383-765a-4d56-b00b-79ee2ccd5111', '歲除夜有懷', '歲除夜有懷', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["迢遞三巴路，羈危萬里身。","亂山殘雪夜，孤燈異鄉人。","漸與骨肉遠，轉於奴僕親。","那堪正飄泊，來日歲華新。"]', '["迢遞三巴路，羈危万里身。","亂山殘雪夜，孤灯異乡人。","漸與骨肉远，轉於奴僕親。","那堪正飄泊，来日歲华新。"]', '诗', 'shi', '', NULL, '歲除夜有懷 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e7d327-0142-4e91-a9c1-ea6988cf1a1a', '登安陽城樓', '登安陽城楼', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["縣城南面漢江流，江漲開成南雍州。","才子乘春來騁望，羣公暇日坐銷憂。","樓臺晚映青山郭，羅綺晴驕綠水洲。","向夕波搖明月動，更疑神女弄珠遊。"]', '["縣城南面漢江流，江漲开成南雍州。","才子乘春来騁望，羣公暇日坐銷憂。","楼台晚映青山郭，羅綺晴驕綠水洲。","向夕波搖明月动，更疑神女弄珠游。"]', '诗', 'shi', '', NULL, '登安陽城樓 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaad319a-e2a1-4eb0-b943-fcf22f936735', '登萬歲樓', '登万歲楼', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["萬歲樓頭望故鄉，獨令鄉思更茫茫。","天寒雁度堪垂淚，日落猿啼欲斷腸。","曲引古堤臨凍浦，斜分遠岸近枯楊。","今朝偶見同袍友，却喜家書寄八行。"]', '["万歲楼头望故乡，独令乡思更茫茫。","天寒雁度堪垂泪，日落猿啼欲斷腸。","曲引古堤臨凍浦，斜分远岸近枯楊。","今朝偶见同袍友，却喜家书寄八行。"]', '诗', 'shi', '', NULL, '登萬歲樓 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de48798-4e30-4693-97ca-3fef9671220b', '除夜有懷', '除夜有懷', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["五更鐘漏欲相催，四氣推遷往復回。","帳裏殘燈纔去熖，爐中香氣盡成灰。","漸看春逼芙蓉枕，頓覺寒銷竹葉杯。","守歲家家應未臥，相思那得夢魂來。"]', '["五更鐘漏欲相催，四氣推遷往复回。","帳裏殘灯纔去熖，爐中香氣尽成灰。","漸看春逼芙蓉枕，頓覺寒銷竹葉杯。","守歲家家應未臥，相思那得梦魂来。"]', '诗', 'shi', '', NULL, '除夜有懷 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('528e4d50-713f-4ce4-a051-d895834c7177', '春情', '春情', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["青樓曉日珠簾映，紅粉春妝寶鏡催。","已厭交歡憐枕席，相將遊戲繞池臺。","坐時衣帶縈纖草，行即裙裾掃落梅。","更道明朝不當作，相期共鬬管絃來。"]', '["青楼晓日珠簾映，紅粉春妝寶镜催。","已厭交歡怜枕席，相將游戲繞池台。","坐时衣带縈纖草，行即裙裾掃落梅。","更道明朝不當作，相期共鬬管絃来。"]', '诗', 'shi', '', NULL, '春情 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd9b6623-1ef8-4794-af81-9abb9f0881c1', '長安早春', '长安早春', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["關戍惟東井，城池起北辰。","咸歌太平日，共樂建寅春。","雪盡青山樹，冰開黑水濱。","草迎金埒馬，花伴玉樓人。","鴻漸看無數，鶯歌聽欲頻。","何當遂榮擢，歸及柳條新。"]', '["关戍惟东井，城池起北辰。","咸歌太平日，共乐建寅春。","雪尽青山樹，冰开黑水濱。","草迎金埒马，花伴玉楼人。","鴻漸看無數，鶯歌听欲頻。","何當遂榮擢，归及柳條新。"]', '诗', 'shi', '', NULL, '長安早春 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e57206e-6b37-458e-b7e8-50f1185d50e9', '荆門上張丞相', '荆门上張丞相', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["共理分荆國，招賢媿不材。","召南風更闡，丞相閣還開。","覯止欣眉睫，沈淪拔草萊。","坐登徐孺榻，頻接李膺杯。","始慰蟬鳴柳，俄看雪間梅。","四時年籥盡，千里客程催。","日下瞻歸翼，沙邊厭曝鰓。","佇聞宣室召，星象列三台。"]', '["共理分荆国，招賢媿不材。","召南风更闡，丞相閣還开。","覯止欣眉睫，沈淪拔草萊。","坐登徐孺榻，頻接李膺杯。","始慰蟬鳴柳，俄看雪间梅。","四时年籥尽，千里客程催。","日下瞻归翼，沙邊厭曝鰓。","佇闻宣室召，星象列三台。"]', '诗', 'shi', '', NULL, '荆門上張丞相 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e1710a-4d30-437c-9fea-bc32f0f57b59', '陪張丞相登荆城樓因寄薊州張使君及浪泊戍主劉家', '陪張丞相登荆城楼因寄薊州張使君及浪泊戍主劉家', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["薊門天北畔，銅柱日南端。","出守聲彌遠，投荒法未寬。","側身聊倚望，攜手莫同歡。","白璧無瑕玷，青松有歲寒。","府中丞相閣，江上使君灘。","興盡回舟去，方知行路難。"]', '["薊门天北畔，銅柱日南端。","出守声彌远，投荒法未寬。","側身聊倚望，携手莫同歡。","白璧無瑕玷，青松有歲寒。","府中丞相閣，江上使君灘。","兴尽回舟去，方知行路难。"]', '诗', 'shi', '', NULL, '陪張丞相登荆城樓因寄薊州張使君及浪泊戍主劉家 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5995ee4-f2d9-46e3-8dd4-fec82bafe040', '陪張丞相祠紫蓋山途經玉泉寺', '陪張丞相祠紫蓋山途經玉泉寺', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["望秩宣王命，齋心待漏行。","青衿列胄子，從事有參卿。","五馬尋歸路，雙林指化城。","聞鐘度門近，照膽玉泉清。","皁蓋依松憩，緇徒擁錫迎。","天宮上兜率，沙界豁迷明。","欲就終焉志，恭聞智者名。","人隨逝水沒，波逐覆舟傾。","想像若在眼，周流空復情。","謝公還欲臥，誰與濟蒼生。"]', '["望秩宣王命，斋心待漏行。","青衿列胄子，從事有參卿。","五马尋归路，雙林指化城。","闻鐘度门近，照膽玉泉清。","皁蓋依松憩，緇徒擁錫迎。","天宮上兜率，沙界豁迷明。","欲就終焉志，恭闻智者名。","人隨逝水沒，波逐覆舟傾。","想像若在眼，周流空复情。","謝公還欲臥，誰與濟蒼生。"]', '诗', 'shi', '', NULL, '陪張丞相祠紫蓋山途經玉泉寺 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea9c522-80c5-4d5c-bcfb-775bae3d8041', '陪張丞相自松滋江東泊渚宮', '陪張丞相自松滋江东泊渚宮', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["放溜下松滋，登舟命檝師。","詎忘經濟日，不憚沍寒時。","洗幘豈獨古，濯纓良在茲。","政成人自理，機息鳥無疑。","雲物凝孤嶼，江山辨四維。","晚來風稍急，冬至日行遲。","臘響驚雲夢，漁歌激楚辭。","渚宮何處是，川暝欲安之。"]', '["放溜下松滋，登舟命檝師。","詎忘經濟日，不憚沍寒时。","洗幘豈独古，濯纓良在茲。","政成人自理，機息鸟無疑。","云物凝孤嶼，江山辨四維。","晚来风稍急，冬至日行遲。","臘响驚云梦，漁歌激楚辞。","渚宮何处是，川暝欲安之。"]', '诗', 'shi', '', NULL, '陪張丞相自松滋江東泊渚宮 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e6f7794-d0f7-47a1-bd3e-6062c16a0f8f', '和張判官登萬山亭因贈洪府都督韓公', '和張判官登万山亭因贈洪府都督韓公', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["韓公是襄士，日賞城西岑。","結搆意不淺，巖潭趣轉深。","皇華一動詠，荆國幾謠吟。","舊徑蘭勿剪，新堤柳欲陰。","砌傍餘怪石，沙上有閑禽。","自牧豫章郡，空瞻楓樹林。","因聲寄流水，善聽在知音。","耆舊眇不接，崔徐無處尋。","物情多貴遠，賢俊豈無今。","遲爾長江暮，澄清一洗心。"]', '["韓公是襄士，日賞城西岑。","結搆意不淺，巖潭趣轉深。","皇华一动詠，荆国幾謠吟。","旧徑蘭勿剪，新堤柳欲陰。","砌傍餘怪石，沙上有闲禽。","自牧豫章郡，空瞻楓樹林。","因声寄流水，善听在知音。","耆旧眇不接，崔徐無处尋。","物情多貴远，賢俊豈無今。","遲爾长江暮，澄清一洗心。"]', '诗', 'shi', '', NULL, '和張判官登萬山亭因贈洪府都督韓公 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd71b080-94ae-41bd-a8ce-a7b43fc85a60', '和宋太史北樓新亭', '和宋太史北楼新亭', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["返耕意未遂，日夕登城隅。","誰道山林近，坐爲符竹拘。","麗譙非改作，軒檻是新圖。","遠水自嶓冢，長雲吞具區。","願隨江燕賀，羞逐府僚趨。","欲識狂歌者，丘園一豎儒。"]', '["返耕意未遂，日夕登城隅。","誰道山林近，坐爲符竹拘。","丽譙非改作，軒檻是新圖。","远水自嶓冢，长云吞具區。","願隨江燕賀，羞逐府僚趨。","欲識狂歌者，丘园一豎儒。"]', '诗', 'shi', '', NULL, '和宋太史北樓新亭 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1060b761-fa9f-4c13-b6ad-da1b8cf43248', '贈蕭少府', '贈蕭少府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["上德如流水，安仁道若山。","聞君秉高節，而得奉清顏。","鴻漸昇儀羽，牛刀列下班。","處腴能不潤，居劇體常閑。","去詐人無諂，除邪吏息姦。","欲知清與潔，明月照澄灣。"]', '["上德如流水，安仁道若山。","闻君秉高節，而得奉清顏。","鴻漸昇儀羽，牛刀列下班。","处腴能不潤，居劇體常闲。","去詐人無諂，除邪吏息姦。","欲知清與潔，明月照澄灣。"]', '诗', 'shi', '', NULL, '贈蕭少府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6859788-9f1d-4e91-b870-e2c90921062d', '秦中苦雨思歸贈袁左丞賀侍郎', '秦中苦雨思归贈袁左丞賀侍郎', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["苦學三十載，閉門江漢陰。","用賢遭聖日，羇旅屬秋霖。","豈直昏墊苦，亦爲權勢沈。","二毛催白髮，百鎰罄黃金。","淚憶峴山墮，愁懷湘水深。","謝公積憤懣，莊舃空謠吟。","躍馬非吾事，狎鷗宜我心。","寄言當路者，去矣北山岑。"]', '["苦学三十載，閉门江漢陰。","用賢遭聖日，羇旅屬秋霖。","豈直昏墊苦，亦爲權勢沈。","二毛催白髮，百鎰罄黄金。","泪憶峴山墮，愁懷湘水深。","謝公積憤懣，莊舃空謠吟。","躍马非吾事，狎鷗宜我心。","寄言當路者，去矣北山岑。"]', '诗', 'shi', '', NULL, '秦中苦雨思歸贈袁左丞賀侍郎 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91224327-bb86-42a7-b076-b85e69878220', '同張明府碧溪贈答', '同張明府碧溪贈答', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["別業聞新製，同聲和者多。","還看碧溪答，不羨綠珠歌。","自有陽臺女，朝朝拾翠過。","綺筵鋪錦繡，妝牖閉藤蘿。","秩滿休閑日，春餘景氣和。","仙鳧能作伴，羅襪共凌波。","曲島尋花藥，回潭折芰荷。","更憐斜日照，紅粉豔青娥。"]', '["別業闻新製，同声和者多。","還看碧溪答，不羨綠珠歌。","自有陽台女，朝朝拾翠過。","綺筵鋪錦繡，妝牖閉藤蘿。","秩满休闲日，春餘景氣和。","仙鳧能作伴，羅襪共凌波。","曲島尋花藥，回潭折芰荷。","更怜斜日照，紅粉豔青娥。"]', '诗', 'shi', '', NULL, '同張明府碧溪贈答 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cfd24fe-7fb6-41b5-bb90-7c0eda48d6a2', '久滯越中貽謝南池會稽賀少府', '久滯越中貽謝南池會稽賀少府', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["陳平無產業，尼父倦東西。","負郭昔云翳，問津今亦迷。","未能忘魏闕，空此滯秦稽。","兩見夏雲起，再聞春鳥啼。","懷仙梅福市，訪舊若耶溪。","聖主賢爲寶，君何隱遯棲。"]', '["陳平無產業，尼父倦东西。","負郭昔云翳，问津今亦迷。","未能忘魏闕，空此滯秦稽。","兩见夏云起，再闻春鸟啼。","懷仙梅福市，訪旧若耶溪。","聖主賢爲寶，君何隐遯棲。"]', '诗', 'shi', '', NULL, '久滯越中貽謝南池會稽賀少府 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('606c8581-c618-44fe-b210-e6b9bd85c215', '送韓使君除洪州都曹', '送韓使君除洪州都曹', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["述職撫荆衡，分符襲寵榮。","往來看擁傳，前後賴專城。","勿翦棠猶在，波澄水更清。","重推江漢理，旋改豫章行。","召父多遺愛，羊公有令名。","衣冠列祖道，耆舊擁前旌。","峴首晨風送，江陵夜火迎。","無才慙孺子，千里媿同聲。"]', '["述職撫荆衡，分符襲寵榮。","往来看擁傳，前後賴專城。","勿翦棠猶在，波澄水更清。","重推江漢理，旋改豫章行。","召父多遺愛，羊公有令名。","衣冠列祖道，耆旧擁前旌。","峴首晨风送，江陵夜火迎。","無才慙孺子，千里媿同声。"]', '诗', 'shi', '', NULL, '送韓使君除洪州都曹 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80aa5a4b-5b5a-4b58-9d5c-0caf70a39535', '送莫甥兼諸昆弟從韓司馬入西軍', '送莫甥兼諸昆弟從韓司马入西軍', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["念爾習詩禮，未曾違戶庭。","平生早偏露，萬里更飄零。","坐棄三牲養，行觀八陣形。","飾裝辭故里，謀策赴邊庭。","壯志吞鴻鵠，遙心伴鶺鴒。","所從文且武，不戰自應寧。"]', '["念爾習诗禮，未曾違戶庭。","平生早偏露，万里更飄零。","坐棄三牲養，行观八陣形。","飾裝辞故里，謀策赴邊庭。","壯志吞鴻鵠，遙心伴鶺鴒。","所從文且武，不戰自應寧。"]', '诗', 'shi', '', NULL, '送莫甥兼諸昆弟從韓司馬入西軍 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f7cd549-d714-42ab-8e7a-890b3bc7ec23', '峴山送蕭員外之荆州', '峴山送蕭員外之荆州', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["峴山江岸曲，郢水郭門前。","自古登臨處，非今獨黯然。","亭樓明落照，井邑秀通川。","澗竹生幽興，林風入管弦。","再飛鵬激水，一舉鶴沖天。","佇立三荆使，看君駟馬旋。"]', '["峴山江岸曲，郢水郭门前。","自古登臨处，非今独黯然。","亭楼明落照，井邑秀通川。","澗竹生幽兴，林风入管弦。","再飞鵬激水，一舉鹤沖天。","佇立三荆使，看君駟马旋。"]', '诗', 'shi', '', NULL, '峴山送蕭員外之荆州 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3eef5ead-96d6-4531-8eeb-be21f3a31d68', '送王昌齡之嶺南', '送王昌齡之嶺南', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["洞庭去遠近，楓葉早驚秋。","峴首羊公愛，長沙賈誼愁。","土毛無縞紵，鄉味有槎頭。","已抱沈痼疾，更貽魑魅憂。","數年同筆硯，茲夕間衾裯。","意氣今何在，相思望斗牛。"]', '["洞庭去远近，楓葉早驚秋。","峴首羊公愛，长沙賈誼愁。","土毛無縞紵，乡味有槎头。","已抱沈痼疾，更貽魑魅憂。","數年同笔硯，茲夕间衾裯。","意氣今何在，相思望斗牛。"]', '诗', 'shi', '', NULL, '送王昌齡之嶺南 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca9483e0-c192-46da-8579-a8fa5bbc4208', '峴山送張去非遊巴東', '峴山送張去非游巴东', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["峴山南郭外，送別每登臨。","沙岸江村近，松門山寺深。","一言予有贈，三峽爾將尋。","祖席宜城酒，征途雲夢林。","蹉跎遊子意，眷戀故人心。","去矣勿淹滯，巴東猿夜吟。"]', '["峴山南郭外，送別每登臨。","沙岸江村近，松门山寺深。","一言予有贈，三峽爾將尋。","祖席宜城酒，征途云梦林。","蹉跎游子意，眷戀故人心。","去矣勿淹滯，巴东猿夜吟。"]', '诗', 'shi', '', NULL, '峴山送張去非遊巴東 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a240044b-c1d2-49b9-b181-d29db41637da', '奉先張明府休沐還鄉海亭宴集', '奉先張明府休沐還乡海亭宴集', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["自君理畿甸，予亦經江淮。","萬里書信斷，數年雲雨乖。","歸來休澣日，始得賞心諧。","朱紱恩雖重，滄州趣每懷。","樹低新舞閣，山對舊書齋。","何以發秋興，陰蟲鳴夜堦。"]', '["自君理畿甸，予亦經江淮。","万里书信斷，數年云雨乖。","归来休澣日，始得賞心諧。","朱紱恩雖重，滄州趣每懷。","樹低新舞閣，山对旧书斋。","何以發秋兴，陰蟲鳴夜堦。"]', '诗', 'shi', '', NULL, '奉先張明府休沐還鄉海亭宴集 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3394ed-7763-4409-b695-7ba2c7aad299', '宴張記室宅', '宴張記室宅', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["甲第金張館，門庭車騎多。","家封漢陽郡，文會楚材過。","曲島浮觴酌，前山入詠歌。","妓堂花映發，書閣柳逶迤。","玉指調箏柱，金泥飾舞羅。","寧知書劒者，歲月獨蹉跎。"]', '["甲第金張館，门庭车騎多。","家封漢陽郡，文會楚材過。","曲島浮觴酌，前山入詠歌。","妓堂花映發，书閣柳逶迤。","玉指調箏柱，金泥飾舞羅。","寧知书劒者，歲月独蹉跎。"]', '诗', 'shi', '', NULL, '宴張記室宅 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f933e19d-3030-447f-911e-214f6c712c94', '宴崔明府宅夜觀妓', '宴崔明府宅夜观妓', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["畫堂觀妙妓，長夜正留賓。","燭吐蓮花豔，妝成桃李春。","髻鬟低舞席，衫袖掩歌脣。","汗濕偏宜粉，羅輕詎著身。","調移箏柱促，歡會酒杯頻。","倘使曹王見，應嫌洛浦神。"]', '["畫堂观妙妓，长夜正留賓。","燭吐蓮花豔，妝成桃李春。","髻鬟低舞席，衫袖掩歌脣。","汗濕偏宜粉，羅轻詎著身。","調移箏柱促，歡會酒杯頻。","倘使曹王见，應嫌洛浦神。"]', '诗', 'shi', '', NULL, '宴崔明府宅夜觀妓 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132cea71-0a7f-46e4-87b5-3ce49c30cb57', '盧明府九日峴山宴袁使君張郎中崔員外', '盧明府九日峴山宴袁使君張郎中崔員外', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["宇宙誰開闢，江山此鬱盤。","登臨今古用，風俗歲時觀。","地理荆州分，天涯楚塞寬。","百城今刺史，華省舊郎官。","共美重陽節，俱懷落帽歡。","酒邀彭澤載，琴輟武城彈。","獻壽先浮菊，尋幽或藉蘭。","煙虹鋪藻翰，松竹挂衣冠。","叔子神如在，山公興未闌。","傳聞騎馬醉，還向習池看。"]', '["宇宙誰开闢，江山此鬱盤。","登臨今古用，风俗歲时观。","地理荆州分，天涯楚塞寬。","百城今刺史，华省旧郎官。","共美重陽節，俱懷落帽歡。","酒邀彭澤載，琴輟武城彈。","獻壽先浮菊，尋幽或藉蘭。","煙虹鋪藻翰，松竹挂衣冠。","叔子神如在，山公兴未闌。","傳闻騎马醉，還向習池看。"]', '诗', 'shi', '', NULL, '盧明府九日峴山宴袁使君張郎中崔員外 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('910cc3ee-4160-436f-8d1d-92b6aee411f0', '登龍興寺閣', '登龙兴寺閣', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["閣道乘空出，披軒遠目開。","逶迤見江勢，客至屢緣回。","茲郡何填委，遙山復幾哉。","蒼蒼皆草木，處處盡樓臺。","驟雨一陽散，行舟四海來。","鳥歸餘興遠，周覽更裴回。"]', '["閣道乘空出，披軒远目开。","逶迤见江勢，客至屢緣回。","茲郡何填委，遙山复幾哉。","蒼蒼皆草木，处处尽楼台。","驟雨一陽散，行舟四海来。","鸟归餘兴远，周覽更裴回。"]', '诗', 'shi', '', NULL, '登龍興寺閣 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be11008d-45cc-4d1d-b2ab-b95fc88d9706', '登總持寺浮圖', '登總持寺浮圖', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["半空躋寶塔，晴望盡京華。","竹遶渭川遍，山連上苑斜。","四門開帝宅，阡陌俯人家。","累劫從初地，爲童憶聚沙。","一窺功德見，彌益道心加。","坐覺諸天近，空香送落花。"]', '["半空躋寶塔，晴望尽京华。","竹遶渭川遍，山連上苑斜。","四门开帝宅，阡陌俯人家。","累劫從初地，爲童憶聚沙。","一窺功德见，彌益道心加。","坐覺諸天近，空香送落花。"]', '诗', 'shi', '', NULL, '登總持寺浮圖 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ba04b2-3834-42ec-aac3-147a9da0c039', '與崔二十一遊鏡湖寄包賀二公', '與崔二十一游镜湖寄包賀二公', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["試覽鏡湖物，中流到底清。","不知鱸魚味，但識鷗鳥情。","帆得樵風送，春逢穀雨晴。","將探夏禹穴，稍背越王城。","府掾有包子，文章推賀生。","滄浪醉後唱，因此寄同聲。"]', '["試覽镜湖物，中流到底清。","不知鱸鱼味，但識鷗鸟情。","帆得樵风送，春逢穀雨晴。","將探夏禹穴，稍背越王城。","府掾有包子，文章推賀生。","滄浪醉後唱，因此寄同声。"]', '诗', 'shi', '', NULL, '與崔二十一遊鏡湖寄包賀二公 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39482263-8152-41b8-af07-4e18de311e3f', '夜登孔伯昭南樓時沈太清朱昇在座', '夜登孔伯昭南楼时沈太清朱昇在座', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["誰家無風月，此地有琴尊。","山水會稽郡，詩書孔氏門。","再來值秋杪，高閣夜無喧。","華燭罷然蠟，清絃方奏鵾。","沈生隱侯胤，朱子買臣孫。","好我意不淺，登茲共話言。"]', '["誰家無风月，此地有琴尊。","山水會稽郡，诗书孔氏门。","再来值秋杪，高閣夜無喧。","华燭罷然蠟，清絃方奏鵾。","沈生隐侯胤，朱子買臣孫。","好我意不淺，登茲共話言。"]', '诗', 'shi', '', NULL, '夜登孔伯昭南樓時沈太清朱昇在座 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e31ccbb-c82d-4c9f-9976-c81f05d1fe93', '陪盧明府泛舟回作', '陪盧明府泛舟回作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["百里行春返，清流逸興多。","鷁舟隨雁泊，江火共星羅。","已救田家旱，仍醫俗化訛。","文章推後輩，風雅激頹波。","高岸迷陵谷，新聲滿櫂歌。","猶憐不才子，白首未登科。"]', '["百里行春返，清流逸兴多。","鷁舟隨雁泊，江火共星羅。","已救田家旱，仍醫俗化訛。","文章推後輩，风雅激頹波。","高岸迷陵谷，新声满櫂歌。","猶怜不才子，白首未登科。"]', '诗', 'shi', '', NULL, '陪盧明府泛舟回作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed11140f-321d-4be7-9f03-b2f9f4c40e54', '臘月八日於剡縣石城寺禮拜', '臘月八日於剡縣石城寺禮拜', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["石壁開金像，香山倚鐵圍。","下生彌勒見，回向一心歸。","竹柏禪庭古，樓臺世界稀。","夕嵐增氣色，餘照發光輝。","講席邀談柄，泉堂施浴衣。","願承功德水，從此濯塵機。"]', '["石壁开金像，香山倚鐵圍。","下生彌勒见，回向一心归。","竹柏禪庭古，楼台世界稀。","夕嵐增氣色，餘照發光輝。","講席邀談柄，泉堂施浴衣。","願承功德水，從此濯塵機。"]', '诗', 'shi', '', NULL, '臘月八日於剡縣石城寺禮拜 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce232659-3a0e-406f-ab50-eb4100f8db51', '同獨孤使君東齋作', '同独孤使君东斋作', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["郎官舊華省，天子命分憂。","襄土歲頻旱，隨車雨再流。","雲陰自南楚，河潤及東周。","廨宇宜新霽，田家賀有秋。","竹間殘照入，池上夕陽浮。","寄謝東陽守，何如八詠樓。"]', '["郎官旧华省，天子命分憂。","襄土歲頻旱，隨车雨再流。","云陰自南楚，河潤及东周。","廨宇宜新霽，田家賀有秋。","竹间殘照入，池上夕陽浮。","寄謝东陽守，何如八詠楼。"]', '诗', 'shi', '', NULL, '同獨孤使君東齋作 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5b191f-4753-4d8b-9bee-64a0158b3b6a', '同王九題就師山房', '同王九題就師山房', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["晚憩支公室，故人逢右軍。","軒窗避炎暑，翰墨動新文。","竹蔽簷前日，雨隨堦下雲。","周遊清蔭徧，吟臥夕陽曛。","江靜櫂歌歇，溪深樵語聞。","歸途未忍去，攜手戀清芬。"]', '["晚憩支公室，故人逢右軍。","軒窗避炎暑，翰墨动新文。","竹蔽簷前日，雨隨堦下云。","周游清蔭徧，吟臥夕陽曛。","江静櫂歌歇，溪深樵語闻。","归途未忍去，携手戀清芬。"]', '诗', 'shi', '', NULL, '同王九題就師山房 孟浩然 shi');
